INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自上而下", "is_correct": true, "explanation": "正确：“自上而下”作状语，修饰“整理”，表示按从上到下逐层进行。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示一起进行，与“一层一层地”的逐层过程矛盾。"}, {"text": "胡乱地", "is_correct": false, "explanation": "语义：“胡乱地”表示没有条理，与“一层一层地”的有序整理相反。"}, {"text": "一下子", "is_correct": false, "explanation": "搭配：“一下子”表示一次完成，与“一层一层地”的逐层过程不搭配。"}], "explanations": {"自上而下": "正确：“自上而下”作状语，修饰“整理”，表示按从上到下逐层进行。", "同时": "语义：“同时”表示一起进行，与“一层一层地”的逐层过程矛盾。", "胡乱地": "语义：“胡乱地”表示没有条理，与“一层一层地”的有序整理相反。", "一下子": "搭配：“一下子”表示一次完成，与“一层一层地”的逐层过程不搭配。"}, "sentence_index": 6, "correct_answer": "自上而下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师自上而下，一下子就把每一行字都写完了。", "explanation": "这里应该用〈一行一行〉。这句把“自上而下”当成了“整体同时完成”的意思，它只表示按顺序从上往下。"}, {"text": "这把伞是自上而下撑开的。", "explanation": "错用：“自上而下”只表示从上往下的方向，不能用来描述撑伞的动作，伞是向四周撑开的。"}, {"text": "这碗汤自上而下很好喝。", "explanation": "这里应该用〈鲜美〉之类的词。这句把“自上而下”当成了评价味道的词，它只能表示方向或层级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗户要自上而下的擦干净。", "corrected_sentence": "窗户要自上而下地擦干净。", "error_description": "“自上而下”修饰动词“擦”时要用“地”，不能用“的”，应说“自上而下地擦干净”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要自上而下了清理仓库。", "corrected_sentence": "我们要自上而下地清理仓库。", "error_description": "“自上而下”修饰动词“清理”时要用“地”，不能用“了”；“了”表示完成，不能放在状语后面。正确形式是“我们要自上而下地清理仓库”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
