INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26948, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电网是送电的网。", "primary_collocate": null, "pronunciation": "diàn wǎng", "ipa": "tjɛn˥˩ wɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "电网把电送到每个家。", "target_word": "电网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的电来自电网。", "target_word": "电网", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个电网连着三个村子。", "target_word": "电网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，电网有时会出问题。", "target_word": "电网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人在山上修电网。", "target_word": "电网", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电网坏了，全城都停电了。", "target_word": "电网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电网很大，覆盖很多城市。", "target_word": "电网", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "有了电网，大家才有电用。", "target_word": "电网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了电网是怎么工作的。", "target_word": "电网", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新电网让山里的人也用上了电。", "target_word": "电网", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "電網", "label": "繁体"}, {"form": "智能电网", "label": "复合"}, {"form": "国家电网", "label": "复合"}], "register": "中性", "sense_fingerprint": "电网：把电送到各家各户的网", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815e1ad1-3b67-482d-a38a-19e3d87ec5a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电网", "is_correct": true, "explanation": "「电网」就是送电的网，正是把电送到各家各户的设施，与句意相符。"}, {"text": "水管", "is_correct": false, "explanation": "语义：「水管」输送的是水，不能把电送到每家。"}, {"text": "网站", "is_correct": false, "explanation": "语义：「网站」是网页的集合，不能输送电能。"}, {"text": "电梯", "is_correct": false, "explanation": "搭配：「送到每个家」的主体需是输电设施，「电梯」与「把电送到」搭配不当。"}], "explanations": {"电网": "「电网」就是送电的网，正是把电送到各家各户的设施，与句意相符。", "水管": "语义：「水管」输送的是水，不能把电送到每家。", "网站": "语义：「网站」是网页的集合，不能输送电能。", "电梯": "搭配：「送到每个家」的主体需是输电设施，「电梯」与「把电送到」搭配不当。"}, "sentence_index": 0, "correct_answer": "电网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的电网是从路边拉来的。", "explanation": "这里应该用〈电线〉。单户接入用的是〈电线〉，「电网」是一整套输配电设施，不说「拉来电网」。"}, {"text": "屋顶的太阳能板就是我家的电网。", "explanation": "这里应该用〈发电设备〉或〈电源〉。「电网」只负责输送电，不产生电能，不能把太阳能板说成电网。"}, {"text": "厨房的电网坏了，插不了插头。", "explanation": "这里应该用〈插座〉。单个插座坏了说〈插座〉，「电网」指大范围输送电的设施，不说厨房的电网坏了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电网", "is_correct": true, "explanation": "「电网」覆盖的是大片区域，与「很大」「覆盖很多城市」相符。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能「覆盖很多城市」。"}, {"text": "寺庙", "is_correct": false, "explanation": "语义：寺庙是宗教场所，与「覆盖很多城市」的范围不符。"}, {"text": "盆景", "is_correct": false, "explanation": "搭配：「覆盖」多用于网络或范围，不说「盆景覆盖城市」。"}], "explanations": {"电网": "「电网」覆盖的是大片区域，与「很大」「覆盖很多城市」相符。", "饼干": "语义：饼干是食品，不能「覆盖很多城市」。", "寺庙": "语义：寺庙是宗教场所，与「覆盖很多城市」的范围不符。", "盆景": "搭配：「覆盖」多用于网络或范围，不说「盆景覆盖城市」。"}, "sentence_index": 6, "correct_answer": "电网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新电网是一台能烧水的小家电。", "explanation": "这里应该用〈电器〉。「电网」指输送电的网络，不是能烧水的家用电器。"}, {"text": "我们村新装了一只电网。", "explanation": "这里量词用错。「只」多用于动物或成对的物品，电网应用〈个〉或〈套〉。"}, {"text": "我们村新建了一台电网。", "explanation": "这里量词用错。「台」用于机器设备，电网是输电网络，应用〈个〉或〈套〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只电网覆盖了整个县。", "corrected_sentence": "这个电网覆盖了整个县。", "error_description": "量词错误：「电网」应用量词「个」，不用「只」（「只」多用于动物或成对的物品）。应改为「这个电网覆盖了整个县」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里的电网终于修了好。", "corrected_sentence": "村里的电网终于修好了。", "error_description": "补语与体标错误：「修好了」是结果补语加「了」，「好」必须紧跟动词，不能说「修了好」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
