INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26950, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "产消者就是自己制造东西，也自己使用的人。", "primary_collocate": null, "pronunciation": "chǎn xiāo zhě", "ipa": "ʈʂʰan˨˩˦ ɕjau˥ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "老王自己做面包自己吃，是个产消者。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产消者自己造东西，也自己用。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我奶奶自己种菜自己吃，她是产消者。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用自己的风车发电，是一位产消者。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位产消者每天自己做衣服穿。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做家具自己用的人，可以叫产消者。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里有很多产消者，他们自己种菜自己吃。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做了手机架自己用，就是产消者。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产消者不用买太多东西，因为他们自己做。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家人自己织布做衣服穿，是产消者。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名词：自己制造又自己使用的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff80419-2652-460d-9a29-0cfc782ab013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产消者", "is_correct": true, "explanation": "正确。“产消者”指自己制造东西又自己使用的人，与句意相符。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手以唱歌为职业，与“自己做面包自己吃”的内容无关。"}, {"text": "消防员", "is_correct": false, "explanation": "语义：消防员的职业与做面包、自己吃无关。"}, {"text": "园丁", "is_correct": false, "explanation": "搭配：园丁通常照料植物，与“做面包”不搭配。"}], "explanations": {"产消者": "正确。“产消者”指自己制造东西又自己使用的人，与句意相符。", "歌手": "语义：歌手以唱歌为职业，与“自己做面包自己吃”的内容无关。", "消防员": "语义：消防员的职业与做面包、自己吃无关。", "园丁": "搭配：园丁通常照料植物，与“做面包”不搭配。"}, "sentence_index": 0, "correct_answer": "产消者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂大量生产衣服，卖给商店，是一家产消者。", "explanation": "这里应该用〈生产者〉。这家工厂只生产、把产品卖出，并不自己使用，产消者要自己制造也自己使用。"}, {"text": "他每天在田里种菜卖给别人，是一位产消者。", "explanation": "这里应该用〈菜农〉。他种菜卖给别人，自己并不使用，产消者要自己制造也自己使用。"}, {"text": "他每天只在超市买菜，不做东西，是一位产消者。", "explanation": "这里应该用〈消费者〉。只买东西、不自己制造的人是消费者，不是产消者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产消者", "is_correct": true, "explanation": "正确。“产消者”指自己制造又自己使用的人，与“自己种菜自己吃”相符。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是卖东西的地方，不是自己种菜吃的人，与句意相反。"}, {"text": "商店", "is_correct": false, "explanation": "语义：商店是卖东西的场所，与“自己种菜”的意思不符。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：银行是机构，与“自己种菜自己吃”不搭配，句子说的是人。"}], "explanations": {"产消者": "正确。“产消者”指自己制造又自己使用的人，与“自己种菜自己吃”相符。", "超市": "语义：超市是卖东西的地方，不是自己种菜吃的人，与句意相反。", "商店": "语义：商店是卖东西的场所，与“自己种菜”的意思不符。", "银行": "搭配：银行是机构，与“自己种菜自己吃”不搭配，句子说的是人。"}, "sentence_index": 6, "correct_answer": "产消者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人是产消者，专门做竹篮卖给别人。", "explanation": "这里应该用〈手工艺人〉。做竹篮卖给别人，自己并不使用，不符合产消者的定义。"}, {"text": "小王在网上买衣服，是一位产消者。", "explanation": "这里应该用〈买家〉。只买东西、不自己制造的人是买家，产消者要自己做也自己用。"}, {"text": "这家商店从外地进货，是一家产消者。", "explanation": "这里应该用〈经销商〉。这家商店只进货再卖出，不自己制造，不是产消者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小张自己缝衣服，自己穿，是只产消者。", "corrected_sentence": "小张自己缝衣服，自己穿，是个产消者。", "error_description": "错误在量词：指人的产消者应用“个”，不能用“只”。正确形式是“是个产消者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她自己纺线织布，是一位产消者的。", "corrected_sentence": "她自己纺线织布，是一位产消者。", "error_description": "错误在“产消者”后多了“的”：作谓语的名词后不加“的”。正确形式是“是一位产消者。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
