INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26952, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从一个地方搬到另一个地方。", "primary_collocate": null, "pronunciation": "qiān yí", "ipa": "tɕʰjɛn˥ i˧˥", "syllable_count": 2, "sentences": [{"text": "冬天到了，大雁开始向南迁移。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂今年迁移到了郊区。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民因为水库建设迁移到了山下。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算把办公室迁移到市中心。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多老人不愿意迁移到新小区，想留在老房子里。", "target_word": "迁移", "complexity_tier": "T3", "furigana": "qiān yí", "sentence_source": "generated"}, {"text": "鱼群随着水温变化慢慢迁移。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的学校下个月迁移到新校区。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个民族几百年前从北方迁移过来。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个部落为了找水源，迁移到了河边。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院迁移后，病人看病更方便了。", "target_word": "迁移", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迁移了", "label": "完成体"}, {"form": "迁移过", "label": "经历体"}, {"form": "数据迁移", "label": "复合词"}, {"form": "遷移", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从一个地方搬到另一个地方（人、动物、机构）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c6fe7c9-33e8-4c2f-b2e6-ccbf82b54954') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26952, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迁移", "is_correct": true, "explanation": "迁移（qiān yí）指从一个地方搬到另一个地方，是本题的目标词。"}, {"text": "前移", "is_correct": false, "explanation": "qián（第二声）与 qiān（第一声）声调不同，前移意思是向前挪动，不是迁移。"}, {"text": "谦逸", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）声调不同，谦逸意思是谦虚、不张扬。"}, {"text": "潜移", "is_correct": false, "explanation": "qián（第二声）与 qiān（第一声）声调不同，潜移意思是暗中逐渐改变。"}, {"text": "千亿", "is_correct": false, "explanation": "第二个音节 yì（第四声）与 yí（第二声）声调不同，千亿是数目。"}], "explanations": {"迁移": "迁移（qiān yí）指从一个地方搬到另一个地方，是本题的目标词。", "前移": "qián（第二声）与 qiān（第一声）声调不同，前移意思是向前挪动，不是迁移。", "谦逸": "yì（第四声）与 yí（第二声）声调不同，谦逸意思是谦虚、不张扬。", "潜移": "qián（第二声）与 qiān（第一声）声调不同，潜移意思是暗中逐渐改变。", "千亿": "第二个音节 yì（第四声）与 yí（第二声）声调不同，千亿是数目。"}, "sentence_index": null, "correct_answer": "迁移"}, "level_3": {"options": [{"text": "迁移", "is_correct": true, "explanation": "迁移：大雁成群从北方向南飞，符合句中的动物与方向。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化指固体受热变成液体，大雁不能融化向南。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：发芽指种子长出嫩芽，与大雁向南的动作不符。"}, {"text": "冻结", "is_correct": false, "explanation": "搭配：冻结多用于水面、资产等，不能用来说大雁冻结向南。"}], "explanations": {"迁移": "迁移：大雁成群从北方向南飞，符合句中的动物与方向。", "融化": "语义：融化指固体受热变成液体，大雁不能融化向南。", "发芽": "语义：发芽指种子长出嫩芽，与大雁向南的动作不符。", "冻结": "搭配：冻结多用于水面、资产等，不能用来说大雁冻结向南。"}, "sentence_index": 0, "correct_answer": "迁移"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人每天把货物迁移到仓库里。", "explanation": "这里应该用〈搬运〉。迁移指人、动物或机构整体改变所在地，货物的挪动要说搬运。"}, {"text": "他的心情从悲伤迁移为快乐。", "explanation": "这里应该用〈转变〉。迁移指空间位置的转移，心情的变化要说转变。"}, {"text": "我的生日迁移到了下周。", "explanation": "这里应该用〈推迟〉。日期和日程不能迁移，改期要用推迟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26952, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "迁移", "is_correct": true, "explanation": "迁移（qiān yí）指从一个地方搬到另一个地方，是本题的目标词。"}, {"text": "前移", "is_correct": false, "explanation": "qián（第二声）与 qiān（第一声）声调不同，前移意思是向前挪动，不是迁移。"}, {"text": "歉意", "is_correct": false, "explanation": "qiàn（第四声）与 qiān（第一声）声调不同，歉意指抱歉的心情。"}, {"text": "浅易", "is_correct": false, "explanation": "qiǎn（第三声）与 qiān 声调不同，yì 与 yí 声调也不同，意思是浅显容易。"}], "explanations": {"迁移": "迁移（qiān yí）指从一个地方搬到另一个地方，是本题的目标词。", "前移": "qián（第二声）与 qiān（第一声）声调不同，前移意思是向前挪动，不是迁移。", "歉意": "qiàn（第四声）与 qiān（第一声）声调不同，歉意指抱歉的心情。", "浅易": "qiǎn（第三声）与 qiān 声调不同，yì 与 yí 声调也不同，意思是浅显容易。"}, "sentence_index": null, "correct_answer": "迁移"}, "level_3": {"options": [{"text": "迁移", "is_correct": true, "explanation": "迁移到：学校从一处搬到新校区，符合句中的机构与地点。"}, {"text": "沸腾", "is_correct": false, "explanation": "语义：沸腾指液体剧烈翻滚，学校不能沸腾到新校区。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：熄灭多用于火、灯，不能用于学校。"}, {"text": "咀嚼", "is_correct": false, "explanation": "语义：咀嚼指用牙齿嚼碎食物，与学校搬迁的意思不符。"}], "explanations": {"迁移": "迁移到：学校从一处搬到新校区，符合句中的机构与地点。", "沸腾": "语义：沸腾指液体剧烈翻滚，学校不能沸腾到新校区。", "熄灭": "搭配：熄灭多用于火、灯，不能用于学校。", "咀嚼": "语义：咀嚼指用牙齿嚼碎食物，与学校搬迁的意思不符。"}, "sentence_index": 6, "correct_answer": "迁移"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的病情迁移得很快。", "explanation": "这里应该用〈好转〉。病情的好转是状态变化，迁移指空间位置的改变。"}, {"text": "油价迁移到了每桶五十元。", "explanation": "这里应该用〈上涨〉。价格的上升要说上涨，迁移不用于价格的变化。"}, {"text": "他迁移了全国纪录。", "explanation": "这里应该用〈打破〉。纪录要说打破，迁移不能用来表示超越成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司上个月迁移了深圳。", "corrected_sentence": "我们公司上个月迁移到了深圳。", "error_description": "错误形式：「迁移了深圳」缺少介词「到」。正确形式：「迁移到了深圳」。表示移到某地，要用「到」引出地点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老张去年北京迁移到了上海。", "corrected_sentence": "老张去年从北京迁移到了上海。", "error_description": "错误形式：「老张去年北京迁移到了上海」缺少介词「从」。正确形式：「老张去年从北京迁移到了上海」。表示起点要用「从」引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d1052f2-a56a-484f-8690-fcc55d9b9c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
