INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26956, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "abstract", "definition": "一个地方直接连到另一个地方。", "primary_collocate": null, "pronunciation": "diǎn duì diǎn", "ipa": "tjɛn˨˩˦ twei˥˩ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "这趟车是点对点的，中途不停。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司提供点对点的接送服务。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点对点飞行，不用在别的城市转机。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从家到学校，有一条点对点的巴士。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点对点的路线最省时间。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种快递是点对点送货，很快就到。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点对点的班车，早上八点出发。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢点对点的旅行，不想中间换车。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点对点的服务让老人出门更方便。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条地铁线是点对点的，只有两站。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "點對點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "点对点：从一个地方直接到另一个地方，中间不停不转", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815e1ad1-3b67-482d-a38a-19e3d87ec5a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "点对点", "is_correct": true, "explanation": "「点对点」指直达，从起点直接到终点，与「中途不停」相符。"}, {"text": "中转", "is_correct": false, "explanation": "语义：「中转」需要换车或停留，与「中途不停」相抵。"}, {"text": "慢车", "is_correct": false, "explanation": "语义：「慢车」每站都停，与「中途不停」矛盾。"}, {"text": "站站停", "is_correct": false, "explanation": "语义：「站站停」每站都停，与「中途不停」直接矛盾。"}], "explanations": {"点对点": "「点对点」指直达，从起点直接到终点，与「中途不停」相符。", "中转": "语义：「中转」需要换车或停留，与「中途不停」相抵。", "慢车": "语义：「慢车」每站都停，与「中途不停」矛盾。", "站站停": "语义：「站站停」每站都停，与「中途不停」直接矛盾。"}, "sentence_index": 0, "correct_answer": "点对点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的菜是点对点的，每道都不一样。", "explanation": "这里应该用〈多样〉。「点对点」描述一个地方直接连到另一个地方，不能用来形容菜式的变化。"}, {"text": "他的心情点对点地好起来了。", "explanation": "这里应该用〈逐渐〉。「点对点」指地点之间的直接连通，不能形容心情转好这种变化。"}, {"text": "他们在街上点对点地遇见了老同学。", "explanation": "这里应该用〈碰见〉。「点对点」指地点间的直接连通，不能用来描述偶然相遇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点对点", "is_correct": true, "explanation": "「点对点」班车直达，中间不停，与「早上八点出发」的班车相符。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：「午夜」与「早上八点出发」的时间矛盾。"}, {"text": "夜间", "is_correct": false, "explanation": "语义：「夜间」的班车与「早上八点出发」冲突。"}, {"text": "慢车", "is_correct": false, "explanation": "搭配：「慢车」多指停靠每站的列车，「慢车的班车」搭配不当。"}], "explanations": {"点对点": "「点对点」班车直达，中间不停，与「早上八点出发」的班车相符。", "午夜": "语义：「午夜」与「早上八点出发」的时间矛盾。", "夜间": "语义：「夜间」的班车与「早上八点出发」冲突。", "慢车": "搭配：「慢车」多指停靠每站的列车，「慢车的班车」搭配不当。"}, "sentence_index": 6, "correct_answer": "点对点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条地铁线是点对点的，途中要换好几次车。", "explanation": "这里应该用〈中转〉。「点对点」指中间不换车，途中要换好几次车应说〈中转〉，不能用「点对点」。"}, {"text": "老师的通知是点对点发到群里的，全班都能看见。", "explanation": "这里应该用〈群发〉。「点对点」指两端之间的直接连接，发到群里要用〈群发〉。"}, {"text": "这条地铁线是点对点的，每站都停，很慢。", "explanation": "这里应该用〈慢车〉。「点对点」指中间不停站，每站都停与词义矛盾，应说〈慢车〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一条点对点地专线。", "corrected_sentence": "这是一条点对点的专线。", "error_description": "的地误用：「点对点」作定语修饰「专线」，应用结构助词「的」，不能用「地」。应改为「点对点的专线」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家快递点对点送很快。", "corrected_sentence": "这家快递点对点送得很快。", "error_description": "补语标记缺失：动词「送」后带状态补语须用「得」，应说「点对点送得很快」，不能说「点对点送很快」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
