INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26962, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "两个人互相给东西，比如我用钱换你的玩具。", "primary_collocate": null, "pronunciation": "jiāo yì", "ipa": "tɕjɑʊ˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "我和哥哥做了一次交易。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个交易很公平：我给你糖，你给我书。", "target_word": "交易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你同意这个交易吗？", "target_word": "交易", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是我们两个人的小交易。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的交易是：你的笔换我的橡皮。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔交易我不亏。", "target_word": "交易", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟觉得这次交易很划算。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，交易要公平，不能骗人。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课间，我和同桌又做了一笔交易。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的交易成功了，我拿到了新玩具。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "交易所", "label": "复合"}, {"form": "交易员", "label": "复合"}], "register": "中性", "sense_fingerprint": "交易：两个人互相给对方东西，彼此交换", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815e1ad1-3b67-482d-a38a-19e3d87ec5a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26962, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交易", "is_correct": true, "explanation": "正确。「做了一次交易」指两人之间的一次互换，符合句意。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然现象，不是人能「做」的行为。"}, {"text": "雷雨", "is_correct": false, "explanation": "搭配：「做」不搭配「雷雨」，雷雨多说「下」。"}, {"text": "大雪", "is_correct": false, "explanation": "语义：大雪是天气现象，不能说「做了一次大雪」。"}], "explanations": {"交易": "正确。「做了一次交易」指两人之间的一次互换，符合句意。", "地震": "语义：地震是自然现象，不是人能「做」的行为。", "雷雨": "搭配：「做」不搭配「雷雨」，雷雨多说「下」。", "大雪": "语义：大雪是天气现象，不能说「做了一次大雪」。"}, "sentence_index": 0, "correct_answer": "交易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和弟弟交易了一个微笑。", "explanation": "这里应该用〈交换〉。「交换微笑」是互相回应，不是买卖，「交易」只指以货币或实物交换商品。"}, {"text": "老师交易了我一个问题。", "explanation": "这里应该用〈回答〉。老师对学生是回答问题，不是互相给东西；「交易」不能用于问题。"}, {"text": "我向他交易了一句对不起。", "explanation": "这里应该用〈道歉〉。说「对不起」是表达歉意，不是互相给东西，「交易」不能用于言语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交易", "is_correct": true, "explanation": "正确。「这次交易很划算」说的是这次互换的结果，符合句意。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：「感冒」是疾病，不能用「划算」来评价。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验，不能说「这次考试很划算」。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「划算」用于价钱和买卖，不用来形容天气。"}], "explanations": {"交易": "正确。「这次交易很划算」说的是这次互换的结果，符合句意。", "感冒": "语义：「感冒」是疾病，不能用「划算」来评价。", "考试": "语义：考试是测验，不能说「这次考试很划算」。", "天气": "搭配：「划算」用于价钱和买卖，不用来形容天气。"}, "sentence_index": 6, "correct_answer": "交易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和同桌交易了一次想法。", "explanation": "这里应该用〈交流〉。交流想法是互相讨论，「交易」指买卖或以实物交换，想法不能交易。"}, {"text": "他向我交易了一声问好。", "explanation": "这里应该用〈问候〉。向人问好是表达善意，「交易」指买卖或互换实物，不能用于问候。"}, {"text": "我和同桌交易了一次和好。", "explanation": "这里应该用〈和好〉。「和好」指消除矛盾，「交易」指买卖或以实物交换，不能用于和好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和弟弟做了一本交易。", "corrected_sentence": "我和弟弟做了一笔交易。", "error_description": "量词错误：「一本交易」；正确：「一笔交易」。“交易”用“笔”计量，“本”用于书册，不能修饰“交易”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这本交易做完了。", "corrected_sentence": "我把这笔交易做完了。", "error_description": "量词错误：「这本交易」；正确：「这笔交易」。“交易”用“笔”计量，“本”用于书册，不能修饰“交易”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26964, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26964, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26964, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "天气的样子，比如刮风、下雨。", "primary_collocate": null, "pronunciation": "qì xiàng", "ipa": "tɕʰi˥˩ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "今天的气象不好，又刮风又下雨。", "target_word": "气象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的气象说变就变，一会儿晴，一会儿雨。", "target_word": "气象", "complexity_tier": "T3", "furigana": "shān lǐ de qìxiàng shuō biàn jiù biàn, yíhuìr qíng, yíhuìr yǔ.", "sentence_source": "generated"}, {"text": "出海以前，要先了解气象。", "target_word": "气象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这儿的气象很特别，早上有雾。", "target_word": "气象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天北方的气象很恶劣，经常下大雪。", "target_word": "气象", "complexity_tier": "T3", "furigana": "dōngtiān běifāng de qìxiàng hěn èliè, jīngcháng xià dàxuě.", "sentence_source": "generated"}, {"text": "看气象，明天应该是晴天。", "target_word": "气象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸每天听广播，了解气象。", "target_word": "气象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的气象一会儿晴，一会儿阴。", "target_word": "气象", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的气象不错，我们去爬山吧。", "target_word": "气象", "complexity_tier": "T3", "furigana": "jīntiān de qìxiàng búcuò, wǒmen qù páshān ba.", "sentence_source": "generated"}, {"text": "气象不好，飞机不能起飞。", "target_word": "气象", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "气象台", "label": "复合"}, {"form": "气象局", "label": "复合"}], "register": "中性", "sense_fingerprint": "某时某地天气的样子，如刮风、下雨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815e1ad1-3b67-482d-a38a-19e3d87ec5a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26964, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "气象", "is_correct": true, "explanation": "正确。“今天的气象不好”指今天的天气状况，与刮风下雨相合。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：成绩指学习或工作的成果，与刮风下雨无关。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是劳动报酬，不能用来描述刮风下雨的天色。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重指身体的重量，不能用来描述天气状况。"}], "explanations": {"气象": "正确。“今天的气象不好”指今天的天气状况，与刮风下雨相合。", "成绩": "语义：成绩指学习或工作的成果，与刮风下雨无关。", "工资": "语义：工资是劳动报酬，不能用来描述刮风下雨的天色。", "体重": "体貌：体重指身体的重量，不能用来描述天气状况。"}, "sentence_index": 0, "correct_answer": "气象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的气象很低，可能要下雨。", "explanation": "这里应该用〈气压〉。气压是大气的压强，可以说高或低；气象是天气样子的总称，不能用高低来形容。"}, {"text": "这个地区的气象四季分明，春天暖和，冬天寒冷。", "explanation": "这里应该用〈气候〉。气候指一个地区长期的天气规律，可以说“四季分明”；气象指一段时间内的天气样子，不能用来概括长期的季节特点。"}, {"text": "我们学校有一只新气象。", "explanation": "这里应该用〈派〉。“只”多用于动物，抽象的“气象”要说“一派新气象”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "气象", "is_correct": true, "explanation": "正确。广播中的“气象”指天气情况，爸爸通过广播了解天气。"}, {"text": "血型", "is_correct": false, "explanation": "语义：广播不会报道血型，“了解血型”与听广播的内容不符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：广播一般不报道颜色，“了解颜色”与听广播的内容不符。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是身体的重量，广播不会报道，与“了解”的内容不符。"}], "explanations": {"气象": "正确。广播中的“气象”指天气情况，爸爸通过广播了解天气。", "血型": "语义：广播不会报道血型，“了解血型”与听广播的内容不符。", "颜色": "语义：广播一般不报道颜色，“了解颜色”与听广播的内容不符。", "体重": "体貌：体重是身体的重量，广播不会报道，与“了解”的内容不符。"}, "sentence_index": 6, "correct_answer": "气象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月食是一种常见的气象。", "explanation": "这里应该用〈天象〉。天象指日月星辰等天文现象，月食属于此类，不属于大气中的天气样子。"}, {"text": "这个班有一条新气象。", "explanation": "这里应该用〈派〉。“条”用于细长的东西，不能修饰抽象的“气象”，应说“一派新气象”。"}, {"text": "这次考试的气象很不错，我考了第一名。", "explanation": "这里应该用〈成绩〉。「气象」指天气的样子，不能用来说考试的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只气象很少见，我们要注意安全。", "corrected_sentence": "这种气象很少见，我们要注意安全。", "error_description": "量词错误：“气象”指一种天气的样子，量词应用“种”，说“这种气象”；“只”多用于动物，不能修饰“气象”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们每天都关心了气象。", "corrected_sentence": "他们每天都关心气象。", "error_description": "错误：「每天都关心了气象」；正确：「每天都关心气象」。“每天”表示经常发生的习惯，句中不宜加“了”，应说「每天都关心气象」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
