INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26978, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电力系统就是让电从发电的地方跑到我们家里用的所有东西。", "primary_collocate": null, "pronunciation": "diàn lì xì tǒng", "ipa": "tjɛn˥˩ li˥˩ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "电力系统让我们家里有电用。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电了，可能是电力系统出了问题。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电力系统包括电厂、电线和变电站。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们画了一张电力系统的图。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了电力系统，晚上我们才有灯用。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇的电力系统很旧了。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风来了，电力系统受到了影响。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在修电力系统的电线。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电力系统把电送到每个人的家。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在电力系统里上班。", "target_word": "电力系统", "complexity_tier": "T3", "furigana": "wǒ gēge zài diànlì xìtǒng lǐ shàngbān", "sentence_source": "generated"}], "morphological_forms": [{"form": "套", "label": "量词"}, {"form": "電力系統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电力系统|把电从电厂送到家里的全部设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c7e75e3-72ef-41eb-a7d0-3ec13fec9d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电视", "is_correct": false, "explanation": "语义：电视是用电的器具，不能把电送到家里，句中说的是供电设施。"}, {"text": "电力系统", "is_correct": true, "explanation": "正确：“让我们家里有电用”说的是把电送到家的设施，与电力系统的定义吻合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱也要用电，不能“让家里有电用”，句中说的是供电设施。"}, {"text": "饭碗", "is_correct": false, "explanation": "语域：“饭碗”是口语词，与这句说明性的语体不协调，也无法供电。"}], "explanations": {"电视": "语义：电视是用电的器具，不能把电送到家里，句中说的是供电设施。", "电力系统": "正确：“让我们家里有电用”说的是把电送到家的设施，与电力系统的定义吻合。", "冰箱": "语义：冰箱也要用电，不能“让家里有电用”，句中说的是供电设施。", "饭碗": "语域：“饭碗”是口语词，与这句说明性的语体不协调，也无法供电。"}, "sentence_index": 0, "correct_answer": "电力系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑了一天，电力系统还很足。", "explanation": "这里应该用〈体力〉。电力系统指把电送到家里的设备，不能比喻人的体力。"}, {"text": "我这个月的电力系统交了两百块。", "explanation": "这里应该用〈电费〉。电力系统是设备，不是费用，交的应该是电费。"}, {"text": "我们班的电力系统在运动会上得了冠军。", "explanation": "这里不能用〈电力系统〉指团队，应该用〈班级〉。电力系统不是团体，也不参加比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诗歌", "is_correct": false, "explanation": "语义：台风影响的是供电设施，诗歌与之无关，不能“受到影响”。"}, {"text": "电力系统", "is_correct": true, "explanation": "正确：台风导致供电设施受影响，与“电力系统”的含义吻合。"}, {"text": "文字", "is_correct": false, "explanation": "语义：句中讲的是台风对供电设施的破坏，文字与之无关。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语词，与这句书面的说明语体不协调。"}], "explanations": {"诗歌": "语义：台风影响的是供电设施，诗歌与之无关，不能“受到影响”。", "电力系统": "正确：台风导致供电设施受影响，与“电力系统”的含义吻合。", "文字": "语义：句中讲的是台风对供电设施的破坏，文字与之无关。", "八卦": "语域：“八卦”是口语词，与这句书面的说明语体不协调。"}, "sentence_index": 6, "correct_answer": "电力系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用电力系统炒了一盘菜。", "explanation": "这里应该用〈炉灶〉。电力系统是输电设施，不能用来做饭。"}, {"text": "他一边洗澡一边唱电力系统。", "explanation": "这里不能把〈电力系统〉当作唱的对象，它是设施，不是歌曲。"}, {"text": "他的电力系统很聪明，每次都能考第一。", "explanation": "这里应该用〈头脑〉。电力系统是设备，不能用来形容人的聪明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家安装了一只电力系统。", "corrected_sentence": "我家安装了一套电力系统。", "error_description": "量词错误：电力系统这类成套设施常用“套”（或“个”）计量，“只”多用于动物或单件器物，不用于此类设施。应说“一套电力系统”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐电力系统里工作。", "corrected_sentence": "我姐姐在电力系统里工作。", "error_description": "介词遗漏：表示处所要用“在”，应说“在电力系统里工作”，不说“电力系统里工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
