INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26982, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能源技术是让电、光、热等力量能被我们使用的方法。", "primary_collocate": null, "pronunciation": "néng yuán jì shù", "ipa": "nɤŋ˧˥ ɥɛn˧˥ tɕi˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "能源技术能把阳光变成电。", "target_word": "能源技术", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学好能源技术，就能让家里更省电。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，能源技术可以让风变成电。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用新的能源技术给村子供热。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项能源技术让路灯晚上也能亮。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸在工厂工作，他懂能源技术。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的能源技术能把热量存起来。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校开了一门能源技术课。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了能源技术，山里的人也用上了电。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种能源技术很安全，也不太贵。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "新能源技术", "label": "复合"}, {"form": "能源技術", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让电、光、热等力量能被使用的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31173b25-2d4d-4630-a105-47245d8daad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能源技术", "is_correct": true, "explanation": "正确。“能源技术”作主语，指把阳光等能量转化为电的方法，与句意相合。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：“眼睛”不能把阳光转化为电，与句意冲突。"}, {"text": "面包", "is_correct": false, "explanation": "语义：“面包”是食物，与阳光变成电毫无关系。"}, {"text": "阁下", "is_correct": false, "explanation": "语域：“阁下”是敬称、书面或古语用法，与这句科普说明的语域不合。"}], "explanations": {"能源技术": "正确。“能源技术”作主语，指把阳光等能量转化为电的方法，与句意相合。", "眼睛": "语义：“眼睛”不能把阳光转化为电，与句意冲突。", "面包": "语义：“面包”是食物，与阳光变成电毫无关系。", "阁下": "语域：“阁下”是敬称、书面或古语用法，与这句科普说明的语域不合。"}, "sentence_index": 0, "correct_answer": "能源技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们每天烧很多能源技术。", "explanation": "这里应该用〈燃料〉。能源技术是开发利用能源的方法，不是可以烧的东西，应说“烧很多燃料”。"}, {"text": "他的职业是能源技术。", "explanation": "这里应该用〈工程师〉。能源技术是方法，不能指人的职业，应说“他的职业是工程师”。"}, {"text": "能源技术很烫，别碰。", "explanation": "这里应该用〈水〉。能源技术没有温度，不能说“很烫”，应说“水很烫，别碰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能源技术", "is_correct": true, "explanation": "正确。“能源技术”作主语，指能储存热量的方法，与句意相合。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”用于定时响铃，与储存热量无关。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”是艺术作品，不能把热量存起来。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：“墨水”用于书写，不能把热量存起来，与句意冲突。"}], "explanations": {"能源技术": "正确。“能源技术”作主语，指能储存热量的方法，与句意相合。", "闹钟": "语义：“闹钟”用于定时响铃，与储存热量无关。", "歌曲": "语义：“歌曲”是艺术作品，不能把热量存起来。", "墨水": "语义：“墨水”用于书写，不能把热量存起来，与句意冲突。"}, "sentence_index": 6, "correct_answer": "能源技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "能源技术很刺耳，吵得我头疼。", "explanation": "这里应该用〈声音〉。能源技术是方法，不是声音，不能用“刺耳”形容，应说“声音很刺耳”。"}, {"text": "能源技术很认真，每天都按时上课。", "explanation": "这里应该用〈老师〉。能源技术是方法，不能指人，也不能说“认真”，应说“老师很认真”。"}, {"text": "这种能源技术很香。", "explanation": "这里应该用〈花〉。能源技术没有气味，不能说“很香”，应说“这种花很香”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把能源技术很省钱。", "corrected_sentence": "这套能源技术很省钱。", "error_description": "量词误用：“能源技术”应搭配量词“套”；“把”用于有柄的器具，不能用于技术，应说“这套能源技术”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种先进能源技术很省钱。", "corrected_sentence": "这种先进的能源技术很省钱。", "error_description": "的字省略：双音节形容词“先进”作定语修饰名词时要加“的”，应说“先进的能源技术”，不能说“先进能源技术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
