INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26984, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一个人没有朋友，很孤单。", "primary_collocate": null, "pronunciation": "gū lì", "ipa": "ku˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "新同学刚来，觉得很孤立。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有朋友，在学校很孤立。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬到新城市以后，她感到孤立。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人一个人住，常常觉得孤立。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别这样，会让自己更孤立的。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不爱说话，在班里有点孤立。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人和他玩，他一个人很孤立。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个孩子总是一个人，显得孤立。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在国外工作的头几年，我觉得很孤立。", "target_word": "孤立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她性格太冷淡，朋友越来越少，变得孤立了。", "target_word": "孤立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "孤立地", "label": "副词形式"}], "register": "中性", "sense_fingerprint": "一个人没有朋友，感到孤单", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c7e75e3-72ef-41eb-a7d0-3ec13fec9d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26984, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孤立", "is_correct": true, "explanation": "正确。新同学刚来，还没有朋友，感到孤单，符合“孤立”的意思。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”形容物体或事情的公开程度，不能说“觉得很透明”。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或眼神，不用于描述“觉得”的感受。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”形容物体的质地，不能说“觉得很坚硬”。"}], "explanations": {"孤立": "正确。新同学刚来，还没有朋友，感到孤单，符合“孤立”的意思。", "透明": "搭配：“透明”形容物体或事情的公开程度，不能说“觉得很透明”。", "明亮": "搭配：“明亮”形容光线或眼神，不用于描述“觉得”的感受。", "坚硬": "搭配：“坚硬”形容物体的质地，不能说“觉得很坚硬”。"}, "sentence_index": 0, "correct_answer": "孤立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他性格孤立，从不主动跟别人说话。", "explanation": "这里应该用〈孤僻〉。孤僻形容性格不合群，孤立指处境或状态，不能用来形容性格。"}, {"text": "他做事很孤立，从来不找别人帮忙。", "explanation": "这里应该用〈独立〉。独立指自己做事、不依赖别人，孤立指缺少朋友或支持，不适合形容做事的方式。"}, {"text": "这道菜很孤立，一点儿也不好吃。", "explanation": "这里应该用〈难吃〉。孤立形容人没有朋友、感到孤单，不用来形容菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孤立", "is_correct": true, "explanation": "正确。没有人陪他玩，他一个人很孤单，符合“孤立”的意思。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：前句“没有人和他玩”说明他独处，与“热闹”的场景相矛盾。"}, {"text": "好客", "is_correct": false, "explanation": "语义：“好客”指热情待客，一个人没有客人可接待，读来不通。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：“辽阔”形容空间范围，不能用来描述一个人的状态。"}], "explanations": {"孤立": "正确。没有人陪他玩，他一个人很孤单，符合“孤立”的意思。", "热闹": "语义：前句“没有人和他玩”说明他独处，与“热闹”的场景相矛盾。", "好客": "语义：“好客”指热情待客，一个人没有客人可接待，读来不通。", "辽阔": "搭配：“辽阔”形容空间范围，不能用来描述一个人的状态。"}, "sentence_index": 6, "correct_answer": "孤立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌很孤立，好听极了。", "explanation": "这里应该用〈优美〉。孤立形容人没有朋友、感到孤单，不用来评价歌曲。"}, {"text": "他的成绩很孤立，每次都是班里第一。", "explanation": "这里应该用〈优秀〉。孤立形容人没有朋友、感到孤单，不用来形容成绩。"}, {"text": "他的笑容很孤立，让人很舒服。", "explanation": "这里应该用〈温和〉。孤立形容人没有朋友、感到孤单，不用来形容笑容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在班里孤立的很难受。", "corrected_sentence": "他在班里孤立得很难受。", "error_description": "状态补语标记错误：形容词后接状态补语时，连接词应是“得”，不能写成“的”，应为“孤立得很难受”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他孤立的坐在角落里，没人理他。", "corrected_sentence": "他孤立地坐在角落里，没人理他。", "error_description": "状语标记错误：副词性状语后应用“地”，不能写成“的”，应为“孤立地坐在角落里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
