INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26998, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把电存起来，以后再用。", "primary_collocate": null, "pronunciation": "chǔ néng", "ipa": "ʈʂʰu˨˩˦ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个电池可以储能，晚上还能用。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白天先储能，晚上再用电。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套设备储能很快，一小时就满了。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶的太阳能板白天发电，旁边的电池负责储能。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "充电宝的作用就是储能。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风大的时候，多余的电可以用来储能。", "target_word": "储能", "complexity_tier": "T3", "furigana": "fēng dà de shí hou duō yú de diàn kě yǐ yòng lái chǔ néng", "sentence_source": "generated"}, {"text": "这座水库晚上会抽水储能。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块电池能储能，停电时也不怕。", "target_word": "储能", "complexity_tier": "T3", "furigana": "zhè kuài diàn chí néng chǔ néng tíng diàn shí yě bú pà", "sentence_source": "generated"}, {"text": "电太多了，要想办法储能。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器储能以后，可以用三天。", "target_word": "储能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抽水储能", "label": "复合"}, {"form": "储能电池", "label": "复合"}], "register": "中性", "sense_fingerprint": "储能：把电存起来留着以后用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a6d8aef-a14f-4db1-9f94-df23b2e8ce72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26998, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "储能", "is_correct": true, "explanation": "正确。“电池可以储能”指把电存起来，符合句意。"}, {"text": "绣花", "is_correct": false, "explanation": "语义：“绣花”是手工动作，电池不能绣花。"}, {"text": "唱歌", "is_correct": false, "explanation": "配价：“唱歌”以人为施事，电池不能作“唱歌”的主语。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”针对人或动物，电池不能洗澡。"}], "explanations": {"储能": "正确。“电池可以储能”指把电存起来，符合句意。", "绣花": "语义：“绣花”是手工动作，电池不能绣花。", "唱歌": "配价：“唱歌”以人为施事，电池不能作“唱歌”的主语。", "洗澡": "语义：“洗澡”针对人或动物，电池不能洗澡。"}, "sentence_index": 0, "correct_answer": "储能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农场每天储能很多粮食，放进仓库。", "explanation": "这里应该用〈储存〉。粮食要说储存；储能只指把电或能量存起来。"}, {"text": "妈妈把饼干储能在柜子里，放了很久也没坏。", "explanation": "这里应该用〈保存〉。饼干放进柜子要说保存；储能只指把电或能量存起来，不能用于饼干。"}, {"text": "电厂把电储能到城市，供大家使用。", "explanation": "这里应该用〈输送〉。储能是把能量存起来，不是把电送到别处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "储能", "is_correct": true, "explanation": "正确。“抽水储能”指用抽水方式存储能量，符合句意。"}, {"text": "写字", "is_correct": false, "explanation": "语义：水库抽水之后不能接“写字”，语义不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：水库不能跳舞，与“抽水”的语境冲突。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动作，不能接在“抽水”之后作宾语。"}], "explanations": {"储能": "正确。“抽水储能”指用抽水方式存储能量，符合句意。", "写字": "语义：水库抽水之后不能接“写字”，语义不通。", "跳舞": "语义：水库不能跳舞，与“抽水”的语境冲突。", "睡觉": "配价：“睡觉”是不及物动作，不能接在“抽水”之后作宾语。"}, "sentence_index": 6, "correct_answer": "储能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每月储能一千元，准备买房。", "explanation": "这里应该用〈储蓄〉。储能指把电或能量存起来，存钱要说储蓄。"}, {"text": "锅炉每天储能很多煤，烧得很旺。", "explanation": "这里应该用〈烧〉。煤是用来燃烧的；储能只指存电或能量，不能用于煤。"}, {"text": "这台空调能储能温度，每天都很舒服。", "explanation": "这里应该用〈调节〉。空调调节的是温度，储能不能带温度作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块新电池储能快很，半小时就满了。", "corrected_sentence": "这块新电池储能很快，半小时就满了。", "error_description": "语序错误：副词“很”应放在形容词“快”之前，说“很快”，不能说“快很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座小型电站白天就开始把储能，能供全村用一周。", "corrected_sentence": "这座小型电站白天就开始储能，能供全村用一周。", "error_description": "“开始”后直接接“储能”，不需要“把”；“把”字句要求“把”后有宾语，“把储能”缺少宾语，应说“开始储能”，去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
