INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27000, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "某些物质受压时会产生电，这种性质叫压电。", "primary_collocate": null, "pronunciation": "yā diàn", "ipa": "ja˥ tjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "压电就是一压就有电。", "target_word": "压电", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个东西具有压电的特性，一压就亮灯。", "target_word": "压电", "complexity_tier": "T3", "furigana": "zhè ge dōng xi jù yǒu yā diàn de tè xìng yí yā jiù liàng dēng", "sentence_source": "generated"}, {"text": "压电鞋走一步就亮一下。", "target_word": "压电", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，压电需要用力压。", "target_word": "压电", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "压电地板让孩子们一跑就发电。", "target_word": "压电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想知道压电是怎么来的。", "target_word": "压电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种打火机靠压电点火。", "target_word": "压电", "complexity_tier": "T2", "furigana": "zhè zhǒng dǎ huǒ jī kào yā diàn diǎn huǒ.", "sentence_source": "generated"}, {"text": "压电的东西很有意思，一压就有电。", "target_word": "压电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把手放在压电板上，灯亮了。", "target_word": "压电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了压电，走路也可以发电。", "target_word": "压电", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "壓電", "label": "繁体"}, {"form": "压电材料", "label": "复合"}], "register": "中性", "sense_fingerprint": "压电：一压就有电的能力（通俗说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bb63fc-9d85-45b8-839d-46c1b0107726') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "压电", "is_correct": true, "explanation": "“压电”是一压就有电的能力，与句中的说法相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：一般石头受压不会发电，与“一压就有电”的说法矛盾。"}, {"text": "水", "is_correct": false, "explanation": "语义：水受压不会产生电，句中的说法与水的性质不符。"}, {"text": "摩擦", "is_correct": false, "explanation": "搭配：“摩擦”起电靠的是摩擦而不是压，与“一压”搭配不当。"}], "explanations": {"压电": "“压电”是一压就有电的能力，与句中的说法相符。", "石头": "语义：一般石头受压不会发电，与“一压就有电”的说法矛盾。", "水": "语义：水受压不会产生电，句中的说法与水的性质不符。", "摩擦": "搭配：“摩擦”起电靠的是摩擦而不是压，与“一压”搭配不当。"}, "sentence_index": 0, "correct_answer": "压电"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "压电门能测出物体经过的时间。", "explanation": "这里应该用〈光电〉。压电是受压时产生电，测物体经过的时间要用光电门。"}, {"text": "压电能把温差变成电。", "explanation": "这里应该用〈热电〉。压电靠受压产生电，把温差变成电要用热电。"}, {"text": "压电升高，灯就会更亮。", "explanation": "这里应该用〈电压〉。压电指受压时产生电的特性，说电的压力升高要用电压。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压电", "is_correct": true, "explanation": "这种打火机靠压电点火，与句意相符。"}, {"text": "风", "is_correct": false, "explanation": "语义：风不能用来点火，与“靠……点火”的说法矛盾。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不能用于点火，与“靠……点火”的说法矛盾。"}, {"text": "糖", "is_correct": false, "explanation": "搭配：“糖”不能用来点火，“靠糖点火”搭配不当。"}], "explanations": {"压电": "这种打火机靠压电点火，与句意相符。", "风": "语义：风不能用来点火，与“靠……点火”的说法矛盾。", "水": "语义：水不能用于点火，与“靠……点火”的说法矛盾。", "糖": "搭配：“糖”不能用来点火，“靠糖点火”搭配不当。"}, "sentence_index": 6, "correct_answer": "压电"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "压电是储存电能的装置。", "explanation": "这里应该用〈电池〉。电池是储存电能、可以供电的装置；压电指受压时产生电的现象，不能说是储存电能的装置。"}, {"text": "压电通过导线会发热。", "explanation": "这里应该用〈电流〉。导线中定向移动的电荷叫电流，通过导线、使导线发热的是电流；压电指受压时产生电的现象。"}, {"text": "压电能阻碍电流。", "explanation": "这里应该用〈电阻〉。电阻是阻碍电流的元件；压电指受压时产生电的现象，不能阻碍电流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块垫子是很压电的，一压就有电。", "corrected_sentence": "这块垫子是压电的，一压就有电。", "error_description": "副词误用：“压电”是名词性的，前面不能用“很”修饰，应删去“很”，说“压电的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双鞋是压电了的，走一步就亮一下。", "corrected_sentence": "这双鞋是压电的，走一步就亮一下。", "error_description": "“压电”与“的”之间不能插入“了”，“压电了的”不成立，应为“压电的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
