INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27004, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "植物用阳光和空气做食物。", "primary_collocate": null, "pronunciation": "guāng hé zuò yòng", "ipa": "kwaŋ˥ xɤ˧˥ tswo˥˩ jʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "光合作用是植物做食物的方法。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植物用阳光做食物，这就是光合作用。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花草在白天做光合作用。", "target_word": "光合作用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "光合作用需要阳光和空气。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "叶子在太阳下做光合作用。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学了光合作用。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有阳光，光合作用就停了。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光合作用让植物长大。", "target_word": "光合作用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小草也有光合作用，它也用阳光做食物。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说光合作用在绿色的叶子里。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "光合作用：植物用阳光和空气做食物（通俗说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bb63fc-9d85-45b8-839d-46c1b0107726') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光合作用", "is_correct": true, "explanation": "光合作用是植物用阳光和空气做食物的方法，与句意相符。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是吸入氧气、呼出二氧化碳的过程，不是植物做食物的方法。"}, {"text": "睡眠", "is_correct": false, "explanation": "语义：睡眠是休息，与“做食物的方法”无关。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“是……的方法”后接“水”这类物质不搭配，“水是植物做食物的方法”说不通。"}], "explanations": {"光合作用": "光合作用是植物用阳光和空气做食物的方法，与句意相符。", "呼吸": "语义：呼吸是吸入氧气、呼出二氧化碳的过程，不是植物做食物的方法。", "睡眠": "语义：睡眠是休息，与“做食物的方法”无关。", "水": "搭配：“是……的方法”后接“水”这类物质不搭配，“水是植物做食物的方法”说不通。"}, "sentence_index": 0, "correct_answer": "光合作用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人靠光合作用吸进氧气。", "explanation": "这里应该用〈呼吸〉。光合作用是植物用阳光和空气做食物的方法，人吸进氧气要用呼吸。"}, {"text": "胃靠光合作用分解食物。", "explanation": "这里应该用〈消化〉。光合作用是植物做食物，胃分解食物要用消化。"}, {"text": "鸡蛋靠光合作用变成小鸡。", "explanation": "这里应该用〈孵化〉。鸡蛋变成小鸡要靠孵化，光合作用是植物做食物的方法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光合作用", "is_correct": true, "explanation": "没有阳光，光合作用就停了，与句意相符。"}, {"text": "地球", "is_correct": false, "explanation": "语义：地球不会因为没有阳光就停下来，“停了”的主语应是植物的光合作用。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不是靠阳光运作的过程，“没有阳光就停了”与木头无关。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“没有阳光”与“工资停了”毫无关联，句意不通。"}], "explanations": {"光合作用": "没有阳光，光合作用就停了，与句意相符。", "地球": "语义：地球不会因为没有阳光就停下来，“停了”的主语应是植物的光合作用。", "木头": "语义：木头不是靠阳光运作的过程，“没有阳光就停了”与木头无关。", "工资": "语义：“没有阳光”与“工资停了”毫无关联，句意不通。"}, "sentence_index": 6, "correct_answer": "光合作用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火柴靠光合作用起火。", "explanation": "这里应该用〈摩擦〉。火柴靠摩擦起火；光合作用是植物用阳光和空气做食物的方法，不能用来说火柴起火。"}, {"text": "太阳能板靠光合作用发电。", "explanation": "这里应该用〈光伏〉。太阳能板靠光照直接发电叫光伏；光合作用是植物做食物的方法。"}, {"text": "种子在土里光合作用。", "explanation": "这里应该用〈发芽〉。种子在土里长出幼芽叫发芽；光合作用是植物用阳光做食物的方法，不是种子生长的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些植物每天都在做了光合作用。", "corrected_sentence": "这些植物每天都在做光合作用。", "error_description": "“在……做”表示动作正在进行，句中已有“在”，动词后不能再加“了”；应为“在做光合作用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里植物不吃光合作用。", "corrected_sentence": "夜里植物不做光合作用。", "error_description": "动词搭配错误：“光合作用”不能与“吃”搭配，应改为“做”，即“夜里植物不做光合作用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
