INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27008, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27008, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "幕墙是建筑物外面挂着的一层墙，常用玻璃做成。", "primary_collocate": null, "pronunciation": "mù qiáng", "ipa": "mu˥˩ tɕʰjaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "幕墙是大楼外面的一层墙。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座楼的幕墙是蓝色的玻璃。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幕墙让大楼看起来很新。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在楼下抬头，看见幕墙上有云。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幕墙很大，擦一次要两天。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家商店的幕墙全是玻璃。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，幕墙亮着很多灯。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幕墙在房子的最外面。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳照在幕墙上，特别亮。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老楼没有幕墙，新楼有。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "玻璃幕墙", "label": "复合"}, {"form": "幕牆", "label": "繁体"}, {"form": "面", "label": "量词"}], "register": "中性", "sense_fingerprint": "通俗说法：大楼最外面的一层墙，常是玻璃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bb63fc-9d85-45b8-839d-46c1b0107726') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地毯", "is_correct": false, "explanation": "语义：地毯铺在地上，不是大楼外面的墙，句意不通。"}, {"text": "幕墙", "is_correct": true, "explanation": "幕墙作主语，指大楼外面的一层墙，句子成立。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，与“大楼外面的一层墙”不相符。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语义：“玩意儿”泛指东西，并非大楼外面的墙，句意不通。"}], "explanations": {"地毯": "语义：地毯铺在地上，不是大楼外面的墙，句意不通。", "幕墙": "幕墙作主语，指大楼外面的一层墙，句子成立。", "饼干": "语义：饼干是食品，与“大楼外面的一层墙”不相符。", "玩意儿": "语义：“玩意儿”泛指东西，并非大楼外面的墙，句意不通。"}, "sentence_index": 0, "correct_answer": "幕墙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在地上铺了幕墙。", "explanation": "这里应该用〈地毯〉。幕墙是挂在大楼外面的构件，不能铺在地上。"}, {"text": "他穿着新幕墙出门。", "explanation": "这里应该用〈衣服〉。幕墙是建筑外墙，不能穿在身上。"}, {"text": "我在楼下抬头，看见天上有幕墙。", "explanation": "这里应该用〈天空〉。幕墙是建筑外墙，不能说天上有幕墙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：课本不会亮着很多灯，句意不通。"}, {"text": "幕墙", "is_correct": true, "explanation": "幕墙作主语，指亮灯的建筑外墙，句意通顺。"}, {"text": "信纸", "is_correct": false, "explanation": "语义：信纸是纸张，不会亮灯，与语境矛盾。"}, {"text": "二手货", "is_correct": false, "explanation": "语义：二手货不会亮灯，与“亮着很多灯”矛盾。"}], "explanations": {"课本": "语义：课本不会亮着很多灯，句意不通。", "幕墙": "幕墙作主语，指亮灯的建筑外墙，句意通顺。", "信纸": "语义：信纸是纸张，不会亮灯，与语境矛盾。", "二手货": "语义：二手货不会亮灯，与“亮着很多灯”矛盾。"}, "sentence_index": 6, "correct_answer": "幕墙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "卧室贴了幕墙，很温馨。", "explanation": "这里应该用〈墙纸〉。幕墙是建筑外墙，不能贴在卧室的墙上。"}, {"text": "他们在草地上搭了幕墙。", "explanation": "这里应该用〈帐篷〉。幕墙是固定在建筑外面的构件，不能用来搭在草地上。"}, {"text": "他在厨房里用幕墙切菜。", "explanation": "这里应该用〈菜刀〉。幕墙不是工具，不能用来切菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "幕墙昨天擦干净。", "corrected_sentence": "幕墙昨天擦干净了。", "error_description": "体标错误：叙述已完成的动作时，“擦干净”后要带“了”，应说“幕墙昨天擦干净了”，不能省略“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里，一只幕墙亮着几盏灯。", "corrected_sentence": "夜里，一面幕墙亮着几盏灯。", "error_description": "量词错误：“幕墙”按面计量，应说“一面幕墙”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
