INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27010, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用翅膀移动到某个地方。", "primary_collocate": null, "pronunciation": "fēi dào", "ipa": "fei˥ tau˥˩", "syllable_count": 2, "sentences": [{"text": "小鸟用翅膀飞到了高高的树上。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜻蜓飞到荷叶上，一动不动。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麻雀从地上飞到屋顶上去了。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸽子飞到老人的肩膀上吃东西。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂飞到花上采蜜。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，鸟儿都飞到树林里睡觉了。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只小蚊子飞到我的耳边。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的鹦鹉飞到了邻居的阳台上。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞到窗外，看了看天空。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鹰飞到山顶，慢慢停下来。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飞到了", "label": "体标"}, {"form": "飞不到", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "用翅膀移动到某个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deaa3fc3-7c1a-43a4-81dd-1b732cf27d0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27010, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "飞到", "is_correct": true, "explanation": "飞到：fēi dào，指用翅膀移动到某个地方。"}, {"text": "飞刀", "is_correct": false, "explanation": "dāo（第一声）与 dào（第四声）声调不同，意思是飞掷的刀。"}, {"text": "飞报", "is_correct": false, "explanation": "bào（第四声）与 dào（第四声）声母不同（b／d），意思是紧急报告。"}, {"text": "黑道", "is_correct": false, "explanation": "hēi 与 fēi 声母不同（h／f），意思是黑社会的势力。"}], "explanations": {"飞到": "飞到：fēi dào，指用翅膀移动到某个地方。", "飞刀": "dāo（第一声）与 dào（第四声）声调不同，意思是飞掷的刀。", "飞报": "bào（第四声）与 dào（第四声）声母不同（b／d），意思是紧急报告。", "黑道": "hēi 与 fēi 声母不同（h／f），意思是黑社会的势力。"}, "sentence_index": null, "correct_answer": "飞到"}, "level_3": {"options": [{"text": "飞到", "is_correct": true, "explanation": "“用翅膀飞到了高高的树上”，表示小鸟借助翅膀移动到树上，符合句意。"}, {"text": "走到", "is_correct": false, "explanation": "语义：“走”是用脚移动，与“用翅膀”的方式相矛盾。"}, {"text": "爬到", "is_correct": false, "explanation": "语义：“爬”靠四肢攀登，与“用翅膀”的方式不符。"}, {"text": "跳到", "is_correct": false, "explanation": "搭配：“用翅膀”后不能接“跳”，“用翅膀跳到”搭配不当。"}], "explanations": {"飞到": "“用翅膀飞到了高高的树上”，表示小鸟借助翅膀移动到树上，符合句意。", "走到": "语义：“走”是用脚移动，与“用翅膀”的方式相矛盾。", "爬到": "语义：“爬”靠四肢攀登，与“用翅膀”的方式不符。", "跳到": "搭配：“用翅膀”后不能接“跳”，“用翅膀跳到”搭配不当。"}, "sentence_index": 0, "correct_answer": "飞到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蜗牛飞到了叶子上。", "explanation": "这里应该用〈爬到〉。蜗牛靠腹足爬行，没有翅膀，“飞到”指用翅膀移动。"}, {"text": "小猫飞到了床上。", "explanation": "这里应该用〈爬到〉。猫靠攀爬上床，不会飞，“飞到”不能用于猫。"}, {"text": "小老鼠飞到了洞里。", "explanation": "这里应该用〈钻到〉。老鼠是钻进洞里的，不会飞，“飞到”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞到", "is_correct": true, "explanation": "“一只小蚊子飞到我的耳边”，表示蚊子飞行到耳边，符合句意。"}, {"text": "游到", "is_correct": false, "explanation": "语义：蚊子不会游泳，“游到”与蚊子的动作不符。"}, {"text": "滚到", "is_correct": false, "explanation": "语义：蚊子不能滚动，“滚到”与蚊子的行为不符。"}, {"text": "吹到", "is_correct": false, "explanation": "搭配：“吹”的主语多为风，蚊子不能作“吹到”的施事，搭配不当。"}], "explanations": {"飞到": "“一只小蚊子飞到我的耳边”，表示蚊子飞行到耳边，符合句意。", "游到": "语义：蚊子不会游泳，“游到”与蚊子的动作不符。", "滚到": "语义：蚊子不能滚动，“滚到”与蚊子的行为不符。", "吹到": "搭配：“吹”的主语多为风，蚊子不能作“吹到”的施事，搭配不当。"}, "sentence_index": 6, "correct_answer": "飞到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把椅子飞到了窗边。", "explanation": "这里应该用〈挪到〉。椅子不会自己飞，移动家具应说“挪到”。"}, {"text": "猴子飞到了树枝上。", "explanation": "这里应该用〈跳到〉。猴子靠跳跃上树枝，不会飞，“飞到”不能用于猴子。"}, {"text": "木头飞到了岸边。", "explanation": "这里应该用〈漂到〉。木头是随水漂流到岸边的，不会飞，“飞到”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "燕子飞到着屋檐上。", "corrected_sentence": "燕子飞到了屋檐上。", "error_description": "“飞到”后的“了”误用为“着”。“飞到”表示动作的结果已经完成，应说“飞到了”，不能说“飞到着”。正确的说法是：燕子飞到了屋檐上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "麻雀没有飞到了屋顶上。", "corrected_sentence": "麻雀没有飞到屋顶上。", "error_description": "错误：“没有”否定已发生的动作时，“飞到”后不能再加“了”，应说“没有飞到屋顶上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
