INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27014, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "粉是一种颜色，像桃花那样的浅红色。", "primary_collocate": null, "pronunciation": "fěn", "ipa": "fən˨˩˦", "syllable_count": 1, "sentences": [{"text": "这朵花的颜色很粉。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的新裙子很粉。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一件粉衬衫。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桃花开了，满树都是粉的。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋糕上的奶油是粉的。", "target_word": "粉", "complexity_tier": "T3", "furigana": "zhè gè dàngāo shàng de nǎiyóu shì fěn de", "sentence_source": "generated"}, {"text": "这个杯子是粉的，那个是蓝的。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢粉裙子，不喜欢黑的。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面墙是粉的，很好看。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山时，天空变粉了。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹的书包是粉的。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "粉色", "label": "复合词"}, {"form": "粉红", "label": "复合词"}, {"form": "粉红色", "label": "复合词"}], "register": "中性", "sense_fingerprint": "像桃花一样的浅红色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '075e48bb-16bc-4c85-a794-089c95f7240f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27014, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "粉", "is_correct": true, "explanation": "粉（fěn）：浅红色，正是这个读音。"}, {"text": "很", "is_correct": false, "explanation": "hěn 与 fěn 声母不同（h／f），意思是很。"}, {"text": "笨", "is_correct": false, "explanation": "bèn 与 fěn 声母和声调都不同，意思是笨。"}, {"text": "反", "is_correct": false, "explanation": "fǎn 与 fěn 韵母不同（an／en），意思是相反。"}, {"text": "分", "is_correct": false, "explanation": "fēn（第一声）与 fěn（第三声）声调不同，意思是分开。"}], "explanations": {"粉": "粉（fěn）：浅红色，正是这个读音。", "很": "hěn 与 fěn 声母不同（h／f），意思是很。", "笨": "bèn 与 fěn 声母和声调都不同，意思是笨。", "反": "fǎn 与 fěn 韵母不同（an／en），意思是相反。", "分": "fēn（第一声）与 fěn（第三声）声调不同，意思是分开。"}, "sentence_index": null, "correct_answer": "粉"}, "level_3": {"options": [{"text": "粉", "is_correct": true, "explanation": "粉：浅红色，像桃花一样，正是描述花的颜色。"}, {"text": "硬", "is_correct": false, "explanation": "语义：花通常不是硬的，与“花”的特点不符。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”用于人，不能说花是聪明的。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”形容速度，不能用来形容颜色。"}], "explanations": {"粉": "粉：浅红色，像桃花一样，正是描述花的颜色。", "硬": "语义：花通常不是硬的，与“花”的特点不符。", "聪明": "搭配：“聪明”用于人，不能说花是聪明的。", "慢": "语义：“慢”形容速度，不能用来形容颜色。"}, "sentence_index": 0, "correct_answer": "粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她很粉地笑了。", "explanation": "这里应该用〈甜〉之类形容词。“粉”是颜色词，不能当副词修饰“笑”。"}, {"text": "这朵花粉得很快乐。", "explanation": "这里应该用〈开心〉之类形容词。“粉”是颜色词，不能用来描写花的心情。"}, {"text": "她的粉很高，比我还高。", "explanation": "这里应该用〈个子〉。“粉”是颜色词，不能指人的身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27014, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "粉", "is_correct": true, "explanation": "粉（fěn）：浅红色，正是这个读音。"}, {"text": "风", "is_correct": false, "explanation": "fēng（第一声）与 fěn 韵母不同（eng／en），意思是风。"}, {"text": "费", "is_correct": false, "explanation": "fèi 与 fěn 韵母不同（ei／en），意思是费用。"}, {"text": "本", "is_correct": false, "explanation": "běn 与 fěn 声母不同（b／f），意思是书本。"}, {"text": "奋", "is_correct": false, "explanation": "fèn（第四声）与 fěn（第三声）声调不同，意思是奋斗。"}], "explanations": {"粉": "粉（fěn）：浅红色，正是这个读音。", "风": "fēng（第一声）与 fěn 韵母不同（eng／en），意思是风。", "费": "fèi 与 fěn 韵母不同（ei／en），意思是费用。", "本": "běn 与 fěn 声母不同（b／f），意思是书本。", "奋": "fèn（第四声）与 fěn（第三声）声调不同，意思是奋斗。"}, "sentence_index": null, "correct_answer": "粉"}, "level_3": {"options": [{"text": "粉", "is_correct": true, "explanation": "粉：浅红色，描述裙子的颜色，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：甜指味道，不能用来形容裙子，句意不通。"}, {"text": "慢", "is_correct": false, "explanation": "语义：慢指速度，不能用来形容裙子。"}, {"text": "饿", "is_correct": false, "explanation": "搭配：“饿”只用于人或动物，不能修饰裙子。"}], "explanations": {"粉": "粉：浅红色，描述裙子的颜色，符合句意。", "甜": "语义：甜指味道，不能用来形容裙子，句意不通。", "慢": "语义：慢指速度，不能用来形容裙子。", "饿": "搭配：“饿”只用于人或动物，不能修饰裙子。"}, "sentence_index": 6, "correct_answer": "粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的声音很粉，很好听。", "explanation": "这里应该用〈甜〉。“粉”是颜色词，不能形容声音。"}, {"text": "他把数学题粉了一遍。", "explanation": "这里应该用〈检查〉。“粉”作动词指涂色，不能用于数学题。"}, {"text": "妈妈把汤粉了一下，很好喝。", "explanation": "这里应该用〈调味〉。“粉”作动词指涂色，不指给汤调味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那件外套是粉。", "corrected_sentence": "那件外套是粉的。", "error_description": "“粉”作表语时，“是……的”结构中的“的”不能省。错误在于省略了“的”，正确形式是“是粉的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹的小伞是粉。", "corrected_sentence": "妹妹的小伞是粉的。", "error_description": "“粉”作表语时，“是……的”结构中的“的”不能省。错误在于省略了“的”，正确形式是“是粉的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27016, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
