INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27016, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "植物长出果实。", "primary_collocate": null, "pronunciation": "jiē chū", "ipa": "tɕjɛ˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "这棵苹果树结出了一百个苹果。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，院子里的桃树结出桃子。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小树长大了，第一次结出果实。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "葡萄藤在秋天结出一串串葡萄。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵柿子树每年都结出很多柿子。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年雨水多，橘子树结出了大橘子。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他种的西红柿结出了红红的果实。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树开完花，很快就结出了小果子。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老树又结出了新的果实。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种草也能结出黄色的小果实。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "结出了", "label": "体标"}, {"form": "结出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "植物长出果实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deaa3fc3-7c1a-43a4-81dd-1b732cf27d0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27016, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "结出", "is_correct": true, "explanation": "结出（jiē chū）是本词条，指植物长出果实。"}, {"text": "接触", "is_correct": false, "explanation": "chù（第四声）与 chū（第一声）声调不同，接触的意思是碰到、联系。"}, {"text": "借出", "is_correct": false, "explanation": "jiè（第四声）与 jiē（第一声）声调不同，借出的意思是把东西借给别人。"}, {"text": "杰出", "is_correct": false, "explanation": "jié（第二声）与 jiē（第一声）声调不同，杰出的意思是才能或成绩特别突出。"}, {"text": "解除", "is_correct": false, "explanation": "jiě（第三声）与 jiē（第一声）声调不同，chú（第二声）与 chū（第一声）声调也不同，解除的意思是取消、去掉。"}], "explanations": {"结出": "结出（jiē chū）是本词条，指植物长出果实。", "接触": "chù（第四声）与 chū（第一声）声调不同，接触的意思是碰到、联系。", "借出": "jiè（第四声）与 jiē（第一声）声调不同，借出的意思是把东西借给别人。", "杰出": "jié（第二声）与 jiē（第一声）声调不同，杰出的意思是才能或成绩特别突出。", "解除": "jiě（第三声）与 jiē（第一声）声调不同，chú（第二声）与 chū（第一声）声调也不同，解除的意思是取消、去掉。"}, "sentence_index": null, "correct_answer": "结出"}, "level_3": {"options": [{"text": "结出", "is_correct": true, "explanation": "原句中的形式，苹果树长出苹果用“结出”。"}, {"text": "摘出", "is_correct": false, "explanation": "配价：“摘出”的施事应是人，苹果树不能摘出苹果。"}, {"text": "吐出", "is_correct": false, "explanation": "语义：“吐出”指从口中排出，苹果树不能吐出果实。"}, {"text": "开出", "is_correct": false, "explanation": "语义：“开出”指开花，苹果树不会开出苹果。"}], "explanations": {"结出": "原句中的形式，苹果树长出苹果用“结出”。", "摘出": "配价：“摘出”的施事应是人，苹果树不能摘出苹果。", "吐出": "语义：“吐出”指从口中排出，苹果树不能吐出果实。", "开出": "语义：“开出”指开花，苹果树不会开出苹果。"}, "sentence_index": 0, "correct_answer": "结出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春天，花园里结出了很多小草。", "explanation": "这里应该用〈长出〉。结出只用于植物结果实，小草从地里长出来要用长出。"}, {"text": "这只母猪结出了三只小猪。", "explanation": "这里应该用〈生出〉。结出只用于植物，母猪生下小猪要用生出。"}, {"text": "农民秋天结出了很多玉米。", "explanation": "这里应该用〈收获〉。结出的主语必须是植物，农民收获庄稼要用收获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结出", "is_correct": true, "explanation": "原句中的形式，植物结出果实用“结出”。"}, {"text": "收获", "is_correct": false, "explanation": "配价：“收获”的施事应是人，西红柿不能收获果实。"}, {"text": "摘下", "is_correct": false, "explanation": "配价：“摘下”的施事应是人，西红柿不能摘下果实。"}, {"text": "拧出", "is_correct": false, "explanation": "语义：“拧出”指用力扭挤使液体流出，与植物结果实无关。"}], "explanations": {"结出": "原句中的形式，植物结出果实用“结出”。", "收获": "配价：“收获”的施事应是人，西红柿不能收获果实。", "摘下": "配价：“摘下”的施事应是人，西红柿不能摘下果实。", "拧出": "语义：“拧出”指用力扭挤使液体流出，与植物结果实无关。"}, "sentence_index": 6, "correct_answer": "结出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用笔结出了一行字。", "explanation": "这里应该用〈写出〉。结出只用于植物结果实，用笔写下文字要用写出。"}, {"text": "春天到了，桃树结出了一树粉色的花。", "explanation": "这里应该用〈开出〉。结出只用于果实，花朵开放要用开出。"}, {"text": "雨后，地上结出了许多小蘑菇。", "explanation": "这里应该用〈冒出〉。结出只用于植物结果实，小蘑菇从地里钻出来要用冒出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵柚子树结出着很多大柚子。", "corrected_sentence": "这棵柚子树结出了很多大柚子。", "error_description": "“结出”后的“了”误用为“着”。“着”表示状态的持续，结果已经出现的动作应用“了”；“结出着”不成立。正确的说法是：这棵柚子树结出了很多大柚子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片菜地的南瓜藤没结出了几个大南瓜。", "corrected_sentence": "这片菜地的南瓜藤结出了几个大南瓜。", "error_description": "“没结出了”不成立：否定“结出”时，“没”与“了”不能同时出现，应去掉“没”。正确的说法是：这片菜地的南瓜藤结出了几个大南瓜。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
