INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27020, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "像花一样好看、受欢迎的人。", "primary_collocate": null, "pronunciation": "bāng huā", "ipa": "pɑŋ˥ xu̯ɑ˥", "syllable_count": 2, "sentences": [{"text": "听说新来的同学是帮花，很多人想认识她。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片里的帮花穿着白色裙子。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们班的帮花唱歌特别好听。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帮花走进教室，大家都笑着打招呼。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个小组都有一个帮花吗？", "target_word": "帮花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑起来很甜，真是我们的帮花。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当年的帮花现在已经是老师了。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们投票选出了今年的帮花。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帮花的朋友很多，电话总是响个不停。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐是村子里的帮花，大家都夸她。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幫花", "label": "繁体"}, {"form": "一位帮花", "label": "量词"}], "register": "口语", "sense_fingerprint": "帮花|名词|像花一样好看、受欢迎的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '075e48bb-16bc-4c85-a794-089c95f7240f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27020, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老鼠", "is_correct": false, "explanation": "语义：“老鼠”不是人，句子说的是新来的同学，不能这样介绍。"}, {"text": "帮花", "is_correct": true, "explanation": "正确。“帮花”指像花一样好看、受欢迎的人，与“很多人想认识她”相合。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：“杯子”是物品，不是人，不能这样介绍新同学。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”与“很多人想认识她”相矛盾，人们一般不会想认识小偷。"}], "explanations": {"老鼠": "语义：“老鼠”不是人，句子说的是新来的同学，不能这样介绍。", "帮花": "正确。“帮花”指像花一样好看、受欢迎的人，与“很多人想认识她”相合。", "杯子": "语义：“杯子”是物品，不是人，不能这样介绍新同学。", "小偷": "语义：“小偷”与“很多人想认识她”相矛盾，人们一般不会想认识小偷。"}, "sentence_index": 0, "correct_answer": "帮花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小组里有一把帮花，大家都很喜欢她。", "explanation": "这里量词应改为〈位〉或〈个〉。“把”用于有柄的物品，帮花指人，不能用“把”。"}, {"text": "班里新来的一条帮花很活泼，大家都喜欢和她玩。", "explanation": "这里量词应改为〈位〉或〈个〉。“条”用于长条形的东西，帮花指人，不能用“条”。"}, {"text": "这次运动会的帮花是一只小熊猫，大家都很喜欢它。", "explanation": "这里应该用〈吉祥物〉。帮花指人，不指动物或玩偶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会成为老师，与“已经是老师了”的语境矛盾。"}, {"text": "帮花", "is_correct": true, "explanation": "正确。“帮花”指像花一样好看、受欢迎的人，与“当年的”经历相合。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“是老师了”的主语应是人，“窗户”不能当老师。"}, {"text": "政府", "is_correct": false, "explanation": "语义：政府是机构，不会“是老师了”，句子指的是某个人。"}], "explanations": {"石头": "语义：石头不会成为老师，与“已经是老师了”的语境矛盾。", "帮花": "正确。“帮花”指像花一样好看、受欢迎的人，与“当年的”经历相合。", "窗户": "搭配：“是老师了”的主语应是人，“窗户”不能当老师。", "政府": "语义：政府是机构，不会“是老师了”，句子指的是某个人。"}, "sentence_index": 6, "correct_answer": "帮花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村子里有一张帮花，大家都夸她。", "explanation": "这里量词应改为〈位〉或〈个〉。“张”用于纸、桌子等平面的东西，不用于指人的帮花。"}, {"text": "这束花很漂亮，是我们的帮花。", "explanation": "这里应该用〈鲜花〉。帮花指人，不指花束。"}, {"text": "那个女孩是一把帮花，大家都很喜欢她。", "explanation": "这里量词应改为〈位〉或〈个〉。“把”用于有柄的物品，不能用来数指人的帮花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班里有一只帮花，大家都想认识她。", "corrected_sentence": "班里有一位帮花，大家都想认识她。", "error_description": "量词错误：“帮花”指人，应用“位”或“个”，不能用“只”。改为“一位帮花”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是村子里帮花，大家都很喜欢她。", "corrected_sentence": "她是村子里的帮花，大家都很喜欢她。", "error_description": "“的”漏掉：“村子里”修饰“帮花”时要加“的”，应说“村子里的帮花”，不能说“村子里帮花”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
