INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27024, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "手碰到东西，像水或颜料，使那上面留下一点点。", "primary_collocate": null, "pronunciation": "zhān", "ipa": "ʈʂan˥", "syllable_count": 1, "sentences": [{"text": "他用手指沾了一点水。", "target_word": "沾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用手指沾了一点红颜料，涂在纸上。", "target_word": "沾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈用手沾了点水，把头发弄顺。", "target_word": "沾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数钱前，他先沾点口水。", "target_word": "沾", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的手沾点水，就不会粘手了。", "target_word": "沾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用手沾了沾水，试试水热不热。", "target_word": "沾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩用手指沾着果酱，放进嘴里。", "target_word": "沾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻书时，他喜欢用手指沾一点口水。", "target_word": "沾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用手指沾了点醋，尝尝咸淡。", "target_word": "沾", "complexity_tier": "T3", "furigana": "zhān", "sentence_source": "generated"}, {"text": "用抹布先沾一点水，再擦桌子。", "target_word": "沾", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "沾了", "label": "体标（了）"}, {"form": "沾着", "label": "体标（着）"}, {"form": "沾沾", "label": "重叠"}, {"form": "沾上", "label": "复合"}], "register": "口语", "sense_fingerprint": "用手或工具轻碰水、颜料等，带上一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '774c926e-fb1f-4488-8915-497812d93261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27024, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "沾", "is_correct": true, "explanation": "正确：「沾」指用手或工具轻碰水、颜料等，带上一点，与句意相符。"}, {"text": "站", "is_correct": false, "explanation": "zhàn（第四声）与 zhān（第一声）声调不同，意思是站立。"}, {"text": "针", "is_correct": false, "explanation": "zhēn 与 zhān 韵母不同（ēn 与 ān），意思是针。"}, {"text": "山", "is_correct": false, "explanation": "shān 与 zhān 声母不同（sh 与 zh），意思是山。"}, {"text": "展", "is_correct": false, "explanation": "zhǎn（第三声）与 zhān（第一声）声调不同，意思是展开。"}, {"text": "张", "is_correct": false, "explanation": "zhāng 与 zhān 韵母不同（āng 与 ān），意思是张开。"}], "explanations": {"沾": "正确：「沾」指用手或工具轻碰水、颜料等，带上一点，与句意相符。", "站": "zhàn（第四声）与 zhān（第一声）声调不同，意思是站立。", "针": "zhēn 与 zhān 韵母不同（ēn 与 ān），意思是针。", "山": "shān 与 zhān 声母不同（sh 与 zh），意思是山。", "展": "zhǎn（第三声）与 zhān（第一声）声调不同，意思是展开。", "张": "zhāng 与 zhān 韵母不同（āng 与 ān），意思是张开。"}, "sentence_index": null, "correct_answer": "沾"}, "level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语义：「扔」指抛掷，与手指碰一点水的动作不符。"}, {"text": "切", "is_correct": false, "explanation": "语义：「切」指切开物体，用手指切水没有意义。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：「咬」的对象需要是可咬之物，水不能咬。"}, {"text": "沾", "is_correct": true, "explanation": "正确：「沾了一点水」指手指轻碰留下一点，与句意相符。"}], "explanations": {"扔": "语义：「扔」指抛掷，与手指碰一点水的动作不符。", "切": "语义：「切」指切开物体，用手指切水没有意义。", "咬": "搭配：「咬」的对象需要是可咬之物，水不能咬。", "沾": "正确：「沾了一点水」指手指轻碰留下一点，与句意相符。"}, "sentence_index": 0, "correct_answer": "沾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手指沾了一大缸水，洗了手。", "explanation": "这里不应该用沾。沾只表示碰到一点点，一大缸水要说〈倒〉或〈舀〉。"}, {"text": "妈妈用抹布沾了桌子。", "explanation": "这里应该用〈擦〉。沾只表示轻轻碰到留下一点，擦桌子要用〈擦〉。"}, {"text": "他不小心把整盆水沾在地上了。", "explanation": "这里应该用〈泼〉。沾只表示手碰到东西后留下一点点，整盆水倾倒出来要用〈泼〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27024, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "沾", "is_correct": true, "explanation": "正确：「沾」指用手或工具轻碰水、颜料等，带上一点，与句意相符。"}, {"text": "占", "is_correct": false, "explanation": "zhàn（第四声）与 zhān（第一声）声调不同，意思是占据。"}, {"text": "真", "is_correct": false, "explanation": "zhēn 与 zhān 韵母不同（ēn 与 ān），意思是真实。"}, {"text": "章", "is_correct": false, "explanation": "zhāng 与 zhān 韵母不同（āng 与 ān），意思是文章。"}], "explanations": {"沾": "正确：「沾」指用手或工具轻碰水、颜料等，带上一点，与句意相符。", "占": "zhàn（第四声）与 zhān（第一声）声调不同，意思是占据。", "真": "zhēn 与 zhān 韵母不同（ēn 与 ān），意思是真实。", "章": "zhāng 与 zhān 韵母不同（āng 与 ān），意思是文章。"}, "sentence_index": null, "correct_answer": "沾"}, "level_3": {"options": [{"text": "踩", "is_correct": false, "explanation": "语义：「踩」指用脚压，用手指不能踩果酱。"}, {"text": "推", "is_correct": false, "explanation": "搭配：「推」需要推动物体，「推着果酱」不符合蘸取后放进嘴里的语境。"}, {"text": "沾", "is_correct": true, "explanation": "正确：「沾着果酱」指手指蘸上果酱，与「放进嘴里」相承。"}, {"text": "盖", "is_correct": false, "explanation": "语义：「盖」指覆盖，与用手指蘸取果酱不符。"}], "explanations": {"踩": "语义：「踩」指用脚压，用手指不能踩果酱。", "推": "搭配：「推」需要推动物体，「推着果酱」不符合蘸取后放进嘴里的语境。", "沾": "正确：「沾着果酱」指手指蘸上果酱，与「放进嘴里」相承。", "盖": "语义：「盖」指覆盖，与用手指蘸取果酱不符。"}, "sentence_index": 6, "correct_answer": "沾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他沾了朋友的光，才拿到了好成绩。", "explanation": "这里的沾是〈沾光〉的意思，指得到别人带来的好处，与本条「手碰到东西，留下一点点」的意思不同。"}, {"text": "他把水沾进杯子里。", "explanation": "这里应该用〈倒〉。沾只表示碰到一点，把水倒进杯子要用〈倒〉。"}, {"text": "这件事跟我一点都不沾边。", "explanation": "这里的沾是〈沾边〉的意思，指挨上关系，与本条「手碰到东西，留下一点点」的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈用手指了沾一点奶油。", "corrected_sentence": "妈妈用手指沾了一点奶油。", "error_description": "「了」位置错误：「了」应紧跟动词「沾」，应说「沾了一点奶油」，不能放在「沾」之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他先用手指沾成一点糖浆，尝尝甜不甜。", "corrected_sentence": "他先用手指沾上一点糖浆，尝尝甜不甜。", "error_description": "补语错误：表示附着的补语应用「上」，「沾成」不成立，应说「沾上一点糖浆」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
