INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27026, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动植物就是动物和植物，比如小猫和小花。", "primary_collocate": null, "pronunciation": "dòng zhí wù", "ipa": "tʊŋ˥˩ ʈʂɨ˧˥ u˥˩", "syllable_count": 3, "sentences": [{"text": "小猫和小花都是动植物。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书店买了一本介绍动植物的书。", "target_word": "动植物", "complexity_tier": "T3", "furigana": "tā zài shūdiàn mǎi le yì běn jièshào dòng zhí wù de shū", "sentence_source": "generated"}, {"text": "我家的院子里有不少动植物。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上学习动植物。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些动植物的名字我都不知道。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的动植物都有名牌。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍了很多动植物的照片。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动植物都需要水。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，动植物都醒了。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海里也有很多动植物。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种动植物", "label": "量词"}, {"form": "動植物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动物和植物，如小猫和小花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e245a58-1dc2-40c3-b6f0-b46e940614ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27026, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "植物", "is_correct": false, "explanation": "语义：“植物”不包括小猫，“小猫和小花都是植物”与“小猫”的所指不符。"}, {"text": "动植物", "is_correct": true, "explanation": "正确：“动植物”指动物和植物，小猫是动物，小花是植物，句意相符。"}, {"text": "动物", "is_correct": false, "explanation": "语义：“动物”不包括小花，“小猫和小花都是动物”与“小花”的所指不符。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：“宠物”指供人饲养观赏的动物，小花不是宠物，与句意不符。"}], "explanations": {"植物": "语义：“植物”不包括小猫，“小猫和小花都是植物”与“小猫”的所指不符。", "动植物": "正确：“动植物”指动物和植物，小猫是动物，小花是植物，句意相符。", "动物": "语义：“动物”不包括小花，“小猫和小花都是动物”与“小花”的所指不符。", "宠物": "语义：“宠物”指供人饲养观赏的动物，小花不是宠物，与句意不符。"}, "sentence_index": 0, "correct_answer": "动植物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家院子里养着一只动植物。", "explanation": "这里应该用〈种〉。动植物是总称，“只”只用于单个动物，要说“一种动植物”。"}, {"text": "农场主每天喂养农场里的动植物。", "explanation": "这里应该用〈动物〉。喂养的是动物，“动植物”包括植物，植物不需要喂养。"}, {"text": "院子里种了很多动植物。", "explanation": "这里应该用〈花〉。“种”说的是植物，动植物里有动物，动物不能种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思想", "is_correct": false, "explanation": "语义：“思想”是抽象的想法，无法拍成照片，“拍了很多思想的照片”不成立。"}, {"text": "动植物", "is_correct": true, "explanation": "正确：“动植物”指可以拍摄的动物和植物，与“拍了很多动植物的照片”相符。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”是听的作品，不能像人或物那样被拍成照片。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“拍”搭配可见的人或物，不说“拍心情”。"}], "explanations": {"思想": "语义：“思想”是抽象的想法，无法拍成照片，“拍了很多思想的照片”不成立。", "动植物": "正确：“动植物”指可以拍摄的动物和植物，与“拍了很多动植物的照片”相符。", "歌曲": "语义：“歌曲”是听的作品，不能像人或物那样被拍成照片。", "心情": "搭配：“拍”搭配可见的人或物，不说“拍心情”。"}, "sentence_index": 6, "correct_answer": "动植物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家门口种着一棵动植物。", "explanation": "这里应该用〈种〉。“棵”用于树木，动植物是总称，应说“一种动植物”。"}, {"text": "我的电脑坏了，动植物打不开了。", "explanation": "这里应该用〈文件〉。“动植物”指动物和植物，不是可以打开的东西，应说“文件打不开”。"}, {"text": "他是一个很有趣的动植物。", "explanation": "这里应该用〈人〉。“动植物”指动物和植物，不用来指人，应说“他是一个很有趣的人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在书里认识了一个动植物。", "corrected_sentence": "我在书里认识了一种动植物。", "error_description": "“个”用于单个事物，动植物是总称，应该用“种”，说“一种动植物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在海里发现了一条动植物。", "corrected_sentence": "我们在海里发现了一种动植物。", "error_description": "“条”多用于细长的东西，动植物是总称，应该用“种”，说“一种动植物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27028, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "增多", "is_correct": true, "explanation": "增多与减少相反，“变少”指东西的数量比原来少，其反义是增多。"}, {"text": "摇动", "is_correct": false, "explanation": "摇动指来回晃动，与数量变化无关。"}, {"text": "研究", "is_correct": false, "explanation": "研究指钻研探讨，与“变少”没有反义关系。"}, {"text": "停留", "is_correct": false, "explanation": "停留指暂时待在某处，与数量的增减无关。"}], "correct_answer": "增多", "explanations": {"增多": "增多与减少相反，“变少”指东西的数量比原来少，其反义是增多。", "摇动": "摇动指来回晃动，与数量变化无关。", "研究": "研究指钻研探讨，与“变少”没有反义关系。", "停留": "停留指暂时待在某处，与数量的增减无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27028, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "增加", "is_correct": true, "explanation": "增加与减少相对，“变少”的反义是增加。"}, {"text": "出发", "is_correct": false, "explanation": "出发指动身离开，与数量的增减无关。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论指交换意见，与“变少”没有反义关系。"}, {"text": "保留", "is_correct": false, "explanation": "保留指留下不动，与“变少”不构成反义。"}], "correct_answer": "增加", "explanations": {"增加": "增加与减少相对，“变少”的反义是增加。", "出发": "出发指动身离开，与数量的增减无关。", "讨论": "讨论指交换意见，与“变少”没有反义关系。", "保留": "保留指留下不动，与“变少”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27028, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西的数量比原来少。", "primary_collocate": null, "pronunciation": "biàn shǎo", "ipa": "pjɛn˥˩ ʂau˨˩˦", "syllable_count": 2, "sentences": [{"text": "盒子里的糖变少了，只剩两块。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年下雨少，河里的水变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的菜变少了，大家都吃饱了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我搬家以后，身边的朋友变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个月花钱太多，银行里的钱变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们砍了很多树，山上的树变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上的小店变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在用现金的人变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，公园里的花变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我送了朋友几本，书架上的书变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变少了", "label": "体标"}, {"form": "变少过", "label": "体标"}], "register": "中性", "sense_fingerprint": "东西的数量比原来少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deaa3fc3-7c1a-43a4-81dd-1b732cf27d0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变少", "is_correct": true, "explanation": "原句中的形式，表示糖的数量比原来少。"}, {"text": "变甜", "is_correct": false, "explanation": "语义：“变甜”说味道的变化，糖的数量减少不能说变甜。"}, {"text": "增多", "is_correct": false, "explanation": "语义：“增多”与后句“只剩两块”矛盾，句子无法成立。"}, {"text": "变长", "is_correct": false, "explanation": "体貌：“变长”说外形的长度，与糖的数量无关。"}], "explanations": {"变少": "原句中的形式，表示糖的数量比原来少。", "变甜": "语义：“变甜”说味道的变化，糖的数量减少不能说变甜。", "增多": "语义：“增多”与后句“只剩两块”矛盾，句子无法成立。", "变长": "体貌：“变长”说外形的长度，与糖的数量无关。"}, "sentence_index": 0, "correct_answer": "变少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的体温变少了。", "explanation": "这里应该用〈下降〉。变少只说数量减少，体温这类数值的下降要用下降。"}, {"text": "这架飞机的高度变少了。", "explanation": "这里应该用〈降低〉。变少说数量减少，飞机高度这类数值的降低要用降低。"}, {"text": "这条河的流速变少了。", "explanation": "这里应该用〈减慢〉。变少指数量减少，流速的降低要用减慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变少", "is_correct": true, "explanation": "原句中的形式，表示小店的数量减少。"}, {"text": "变快", "is_correct": false, "explanation": "语义：“变快”说速度，小店的数量不能说变快。"}, {"text": "变窄", "is_correct": false, "explanation": "体貌：“变窄”说空间的宽度，不能用来描述小店数量。"}, {"text": "变高", "is_correct": false, "explanation": "体貌：“变高”说高度，小店数量减少不能用变高。"}], "explanations": {"变少": "原句中的形式，表示小店的数量减少。", "变快": "语义：“变快”说速度，小店的数量不能说变快。", "变窄": "体貌：“变窄”说空间的宽度，不能用来描述小店数量。", "变高": "体貌：“变高”说高度，小店数量减少不能用变高。"}, "sentence_index": 6, "correct_answer": "变少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布的面积变少了。", "explanation": "这里应该用〈缩小〉。变少说数量减少，面积的缩减要用缩小。"}, {"text": "照片的清晰度变少了。", "explanation": "这里应该用〈变模糊〉。变少只说数量减少，清晰度降低时要说变模糊。"}, {"text": "音量变少了。", "explanation": "这里应该用〈调小〉。变少说数量减少，音量的降低要用调小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个学期班里的学生变少地了。", "corrected_sentence": "这个学期班里的学生变少了。", "error_description": "“变少”是动词，后面不能加“地”。错误形式是“变少地了”，正确形式是“变少了”，“了”直接放在“变少”之后。正确的说法是：这个学期班里的学生变少了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区的超市变少着。", "corrected_sentence": "这个小区的超市变少了。", "error_description": "“变少”表示数量已经减少，变化完成要用“了”；“变少着”不成立。正确的说法是：这个小区的超市变少了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
