INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27038, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "花粉从雄蕊传到雌蕊柱头上，是花结出果实的前提。", "primary_collocate": null, "pronunciation": "shòu fěn", "ipa": "ʂoʊ˥˩ fən˨˩˦", "syllable_count": 2, "sentences": [{"text": "苹果花需要授粉，才能结出苹果。", "target_word": "授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂在花上飞来飞去，帮花授粉。", "target_word": "授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有蜜蜂，很多花就不能授粉。", "target_word": "授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用小刷子给梨花授粉。", "target_word": "授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下雨，蜜蜂不出来，花没法授粉。", "target_word": "授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花授粉以后，就会慢慢长出果实。", "target_word": "授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西瓜花授粉了，过几天就会长出小西瓜。", "target_word": "授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风也可以帮助有些花授粉。", "target_word": "授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "果园里的人每年春天都要给果树授粉。", "target_word": "授粉", "complexity_tier": "T3", "furigana": "guǒ yuán lǐ de rén měi nián chūn tiān dōu yào gěi guǒ shù shòufěn。", "sentence_source": "generated"}, {"text": "我们看到蜜蜂正在给向日葵授粉。", "target_word": "授粉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "授粉了", "label": "体标"}, {"form": "人工授粉", "label": "复合"}], "register": "中性", "sense_fingerprint": "授粉：花粉传到雌蕊柱头，花才能结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43fcd651-f37e-4c54-87ee-af7602635d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27038, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "授粉", "is_correct": true, "explanation": "正确：花需要传粉才能结果，符合“才能结出苹果”的因果关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：花不会唱歌，与结出果实没有关系。"}, {"text": "拍照", "is_correct": false, "explanation": "语义：拍照不能帮助花结出果实，与句意相悖。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：散步的主体是人或动物，花不能散步。"}], "explanations": {"授粉": "正确：花需要传粉才能结果，符合“才能结出苹果”的因果关系。", "唱歌": "语义：花不会唱歌，与结出果实没有关系。", "拍照": "语义：拍照不能帮助花结出果实，与句意相悖。", "散步": "搭配：散步的主体是人或动物，花不能散步。"}, "sentence_index": 0, "correct_answer": "授粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师每天在教室里给学生授粉。", "explanation": "这里应该用〈授课〉。授粉指花粉传到雌蕊柱头，只用于植物；老师给学生讲课要说授课。"}, {"text": "我昨天给新买的椅子授粉了。", "explanation": "这里应该用〈上漆〉。授粉只用于植物的花；给椅子涂漆要说上漆。"}, {"text": "我们班的同学每天都给老师授粉。", "explanation": "这里应该用〈帮助〉。授粉只用于植物的雌蕊；同学为老师做事要说帮助。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "授粉", "is_correct": true, "explanation": "正确：“西瓜花……了”后接“过几天就会长出小西瓜”，指传粉后结果。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：哭泣与开花、结果没有关系，句意不通。"}, {"text": "上学", "is_correct": false, "explanation": "搭配：上学的主体是学生，西瓜花不能上学。"}, {"text": "画画", "is_correct": false, "explanation": "语义：画画不能使西瓜花长出小西瓜，与句意相悖。"}], "explanations": {"授粉": "正确：“西瓜花……了”后接“过几天就会长出小西瓜”，指传粉后结果。", "哭泣": "语义：哭泣与开花、结果没有关系，句意不通。", "上学": "搭配：上学的主体是学生，西瓜花不能上学。", "画画": "语义：画画不能使西瓜花长出小西瓜，与句意相悖。"}, "sentence_index": 6, "correct_answer": "授粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑昨天一直在授粉。", "explanation": "这里应该用〈运行〉。授粉的主体是传粉的花或昆虫；电脑开着、工作要说运行。"}, {"text": "农民用棍子给小猪授粉。", "explanation": "这里应该用〈赶〉。授粉只用于植物的雌蕊；用棍子赶小猪要说赶。"}, {"text": "他很想给梦想授粉。", "explanation": "这里应该用〈实现〉。授粉只用于植物的花；让梦想变成现实要说实现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民每年都被果树授粉。", "corrected_sentence": "农民每年都给果树授粉。", "error_description": "介词错误：引出授粉对象“果树”要用“给”，不能用“被”；“被果树授粉”会使果树变成施动者，与句意相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵果树春天授粉了两个。", "corrected_sentence": "这棵果树春天授粉了两次。", "error_description": "错误形式：“授粉了两个”；正确形式：“授粉了两次”。“授粉”是动作，计量要用“次”，量词“个”用于事物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
