INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27044, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "带人或东西去一个地方。", "primary_collocate": null, "pronunciation": "dài dào", "ipa": "tai˥˩ tau˥˩", "syllable_count": 2, "sentences": [{"text": "明天请把雨伞带到学校。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把小狗带到公园玩。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把我带到北京看奶奶。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别忘了把作业带到教室。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把新朋友带到我们家吃饭。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门时请把钥匙带到办公室。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游把我们带到一个很大的商店。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这些水果带到公司给同事。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把女儿带到医院看医生。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥要把我的书带到宿舍。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带到了", "label": "体标"}, {"form": "带到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "带到：带人或东西去一个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70f80afb-2f40-4b32-8524-5af00f94cd49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27044, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带到", "is_correct": true, "explanation": "正确：带到，dài dào，意思是把人或东西带往某处。"}, {"text": "带刀", "is_correct": false, "explanation": "dāo（第一声）与 dào（第四声）声调不同，“带刀”的意思是携带刀子，与“带到”的第二个音节不同。"}, {"text": "逮到", "is_correct": false, "explanation": "dǎi（第三声）与 dài（第四声）声调不同，“逮到”的意思是抓住，与“带到”的第一个音节不同。"}, {"text": "大道", "is_correct": false, "explanation": "dà 与 dài 的韵母不同（a 与 ai），“大道”的意思是大路，与“带到”的第一个音节不同。"}], "explanations": {"带到": "正确：带到，dài dào，意思是把人或东西带往某处。", "带刀": "dāo（第一声）与 dào（第四声）声调不同，“带刀”的意思是携带刀子，与“带到”的第二个音节不同。", "逮到": "dǎi（第三声）与 dài（第四声）声调不同，“逮到”的意思是抓住，与“带到”的第一个音节不同。", "大道": "dà 与 dài 的韵母不同（a 与 ai），“大道”的意思是大路，与“带到”的第一个音节不同。"}, "sentence_index": null, "correct_answer": "带到"}, "level_3": {"options": [{"text": "带到", "is_correct": true, "explanation": "正确：“明天请把雨伞带到学校”，表示把雨伞携带到学校。"}, {"text": "抛到", "is_correct": false, "explanation": "语义：“抛”是用力扔出去，不能用来说把雨伞抛到学校。"}, {"text": "踢到", "is_correct": false, "explanation": "语义：“踢”是用脚发力，不能用来说把雨伞踢到学校。"}, {"text": "跑到", "is_correct": false, "explanation": "配价：“跑”是不及物动词，不能带“把”字宾语，不能说“把雨伞跑到学校”。"}], "explanations": {"带到": "正确：“明天请把雨伞带到学校”，表示把雨伞携带到学校。", "抛到": "语义：“抛”是用力扔出去，不能用来说把雨伞抛到学校。", "踢到": "语义：“踢”是用脚发力，不能用来说把雨伞踢到学校。", "跑到": "配价：“跑”是不及物动词，不能带“把”字宾语，不能说“把雨伞跑到学校”。"}, "sentence_index": 0, "correct_answer": "带到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次改革带到了明显的变化。", "explanation": "这里应该用〈带来〉。带到指把人或东西送往某处，引起变化要用〈带来〉。"}, {"text": "我终于带到了那份录取通知。", "explanation": "这里应该用〈拿到〉。带到表示携带到某处，获得录取通知要用〈拿到〉。"}, {"text": "这场台风带到了严重的破坏。", "explanation": "这里应该用〈造成〉。带到不能引出“破坏”这类结果，产生破坏要用〈造成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带到", "is_correct": true, "explanation": "正确：“导游把我们带到一个很大的商店”，表示导游引领游客前往商店。"}, {"text": "推到", "is_correct": false, "explanation": "语义：“推”是用力使物体移动，不能用来说导游引领游客。"}, {"text": "抬到", "is_correct": false, "explanation": "语义：“抬”指用手或肩承托较重的东西，不能用来说导游把游客抬到商店。"}, {"text": "跳到", "is_correct": false, "explanation": "配价：“跳”是不及物动词，不能带“把”字宾语，不能说“把我们跳到”。"}], "explanations": {"带到": "正确：“导游把我们带到一个很大的商店”，表示导游引领游客前往商店。", "推到": "语义：“推”是用力使物体移动，不能用来说导游引领游客。", "抬到": "语义：“抬”指用手或肩承托较重的东西，不能用来说导游把游客抬到商店。", "跳到": "配价：“跳”是不及物动词，不能带“把”字宾语，不能说“把我们跳到”。"}, "sentence_index": 6, "correct_answer": "带到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消息带到了大家的关注。", "explanation": "这里应该用〈引起〉。带到表示携带到某处，引发关注要用〈引起〉。"}, {"text": "这份坚持带到了应有的回报。", "explanation": "这里应该用〈得到〉。带到不用于获得回报，获得回报要用〈得到〉。"}, {"text": "这次演出带到了不错的成绩。", "explanation": "这里应该用〈取得〉。带到表示携带，不表示获得成绩，取得成绩要用〈取得〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下午我要把水杯带到了会议室。", "corrected_sentence": "下午我要把水杯带到会议室。", "error_description": "错误在于“带到”后面多加了“了”。“要”表示尚未发生的打算，“了”表示动作已经完成，二者矛盾；应说“下午我要把水杯带到会议室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上个月我他带到了动物园。", "corrected_sentence": "上个月我把他带到了动物园。", "error_description": "错误在于漏掉“把”：把字句中“把”须放在宾语“他”前，漏掉后“我他带到了动物园”不成句，应为“上个月我把他带到了动物园”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
