INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27056, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想找到一个人或一样东西。", "primary_collocate": null, "pronunciation": "xún zhǎo", "ipa": "ɕyn˧˥ ʈʂɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我正在寻找我的手机。", "target_word": "寻找", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他到处寻找他的眼镜。", "target_word": "寻找", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明在公园里寻找他的小狗。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在厨房里寻找盐。", "target_word": "寻找", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "同学们在草地上寻找四叶草。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在网上寻找便宜的机票。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在寻找藏起来的玩具。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他寻找了一个下午，还是没找到那本书。", "target_word": "寻找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们在地图上寻找去博物馆的路。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想寻找一家安静的咖啡店。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "寻找了", "label": "完成体"}, {"form": "寻找着", "label": "持续体"}, {"form": "寻找过", "label": "经历体"}, {"form": "尋找", "label": "繁体"}], "register": "中性", "sense_fingerprint": "想找到人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70f80afb-2f40-4b32-8524-5af00f94cd49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27056, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“手机”作宾语。"}, {"text": "寻找", "is_correct": true, "explanation": "“寻找”指努力去找，与“我正在”搭配，表示正在找手机。"}, {"text": "充电", "is_correct": false, "explanation": "配价：“充电”是离合词，不能直接带宾语，不能说“充电我的手机”。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”是失去东西的结果，不是“我”主动去做的动作，不合语境。"}], "explanations": {"吃": "搭配：“吃”不能带“手机”作宾语。", "寻找": "“寻找”指努力去找，与“我正在”搭配，表示正在找手机。", "充电": "配价：“充电”是离合词，不能直接带宾语，不能说“充电我的手机”。", "丢失": "语义：“丢失”是失去东西的结果，不是“我”主动去做的动作，不合语境。"}, "sentence_index": 0, "correct_answer": "寻找"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子寻找了一声尖叫。", "explanation": "这里应该用〈发出〉。寻找的对象是能找到的人或东西，尖叫是发出的声音，应说“发出尖叫”。"}, {"text": "孩子们在学校里寻找了一个好成绩。", "explanation": "这里应该用〈取得〉。寻找的对象是能找到的人或东西，成绩是要取得的结果，应说“取得好成绩”。"}, {"text": "这个孩子寻找了一场考试。", "explanation": "这里应该用〈参加〉。寻找的对象是能找到的人或东西，考试是要参加的活动，应说“参加考试”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“玩具”作宾语。"}, {"text": "帮助", "is_correct": false, "explanation": "配价：“帮助”要求带人作宾语，不能说“帮助玩具”。"}, {"text": "寻找", "is_correct": true, "explanation": "“寻找”指努力去找藏起来的东西，与语境相符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物等，不能说“穿玩具”。"}], "explanations": {"唱": "搭配：“唱”不能带“玩具”作宾语。", "帮助": "配价：“帮助”要求带人作宾语，不能说“帮助玩具”。", "寻找": "“寻找”指努力去找藏起来的东西，与语境相符。", "穿": "搭配：“穿”的宾语是衣物等，不能说“穿玩具”。"}, "sentence_index": 6, "correct_answer": "寻找"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈寻找了一次锻炼。", "explanation": "这里应该用〈进行〉。寻找的对象是能找到的人或东西，锻炼是要进行的活动，应说“进行锻炼”。"}, {"text": "他寻找了一个小时的怒气。", "explanation": "这里应该用〈生〉。寻找的对象是能找到的人或东西，怒气是要生出的情绪，应说“生气”。"}, {"text": "我们寻找了一个寒假的长度。", "explanation": "这里应该用〈测量〉。寻找的对象是能找到的人或东西，长度要用“测量”来确定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在书桌上寻找了过一把钥匙。", "corrected_sentence": "我在书桌上寻找过一把钥匙。", "error_description": "错误在于体标叠加：经历体“过”要直接跟在动词“寻找”后，“了”和“过”不能同时用，应说“寻找过一把钥匙”，不能说“寻找了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他寻找很仔细。", "corrected_sentence": "他寻找得很仔细。", "error_description": "错误在于漏掉补语标记“得”：动词“寻找”后带程度补语要用“得”，应说“寻找得很仔细”，不能直接说“寻找很仔细”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
