INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27060, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "农民用来杀死害虫、让庄稼长好的药水。", "primary_collocate": null, "pronunciation": "nóng yào", "ipa": "nʊŋ˧˥ jaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "农民把农药倒进水桶里。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩不能碰农药，因为它有毒。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶农药是用来杀菜虫的。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷拿着农药去菜地喷虫。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，菜叶上的农药会少一些。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买农药的时候，要看清楚说明。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农药放在高处，小朋友拿不到。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "田里的虫太多，农民只好买农药。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喷了农药以后，菜地里的虫少多了。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把农药和水果放在一起。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一瓶农药", "label": "量词"}, {"form": "化学农药", "label": "复合"}, {"form": "農藥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "农药：农民用来杀害虫的药水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43fcd651-f37e-4c54-87ee-af7602635d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27060, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不能被“倒进水桶”，句中要的是液态的药剂。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是整体的机械，不能被“倒进水桶”。"}, {"text": "农药", "is_correct": true, "explanation": "农药：防治病虫害的化学药剂。这里是农民倒进水桶里配制的药水。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本不会被倒进水桶，句中要的是液态的药剂。"}], "explanations": {"电脑": "语义：电脑是机器，不能被“倒进水桶”，句中要的是液态的药剂。", "汽车": "语义：汽车是整体的机械，不能被“倒进水桶”。", "农药": "农药：防治病虫害的化学药剂。这里是农民倒进水桶里配制的药水。", "书本": "语义：书本不会被倒进水桶，句中要的是液态的药剂。"}, "sentence_index": 0, "correct_answer": "农药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都喝农药，身体很健康。", "explanation": "这里应该用〈牛奶〉。农药有毒，不能喝，与“身体很健康”也不相符。"}, {"text": "这种农药可以去油污，洗碗很好用。", "explanation": "这里应该用〈洗洁精〉。农药是用来杀虫的，不能用来去油污、洗碗。"}, {"text": "每天吃一点农药，对身体有好处。", "explanation": "这里应该用〈维生素〉。农药有毒，不能当营养品吃，更谈不上对身体有好处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妈妈", "is_correct": false, "explanation": "语义：人不能被“放在高处”，句中指的是化学药剂。"}, {"text": "农药", "is_correct": true, "explanation": "农药：防治病虫害的化学药剂。放在高处是为了不让小朋友误碰。"}, {"text": "白云", "is_correct": false, "explanation": "语义：白云在天上，不能被人“放在高处”，句中要的是可以拿取的物品。"}, {"text": "海风", "is_correct": false, "explanation": "搭配：“放”的对象是具体物品，风不能被“放在高处”。"}], "explanations": {"妈妈": "语义：人不能被“放在高处”，句中指的是化学药剂。", "农药": "农药：防治病虫害的化学药剂。放在高处是为了不让小朋友误碰。", "白云": "语义：白云在天上，不能被人“放在高处”，句中要的是可以拿取的物品。", "海风": "搭配：“放”的对象是具体物品，风不能被“放在高处”。"}, "sentence_index": 6, "correct_answer": "农药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民每年都往地里多撒一些农药，让土地变得更肥沃。", "explanation": "这里应该用〈化肥〉。农药是用来杀死害虫的，不能让土地变肥沃；使土地变肥沃要用化肥。"}, {"text": "农民每天用农药喂养家里的鸡，希望鸡下蛋更多。", "explanation": "这里应该用〈饲料〉。农药有毒，不能用来喂鸡；喂鸡要用饲料。"}, {"text": "厨房里的案板用农药消毒，擦完就可以切菜了。", "explanation": "这里应该用〈消毒剂〉。农药有毒，不能用来消毒案板和餐具；消毒要用消毒剂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只农药要放在干燥的地方。", "corrected_sentence": "这袋农药要放在干燥的地方。", "error_description": "量词错误：“农药”应用“袋”“瓶”等计量，“只”多用于动物，“这只农药”不说，应为“这袋农药”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民去年买着农药，效果很好。", "corrected_sentence": "农民去年买过农药，效果很好。", "error_description": "体标误用：表示经历的时态标记应为“过”，此处用“着”表示持续状态，与“去年”已完成的经历不符；应为“买过农药”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
