INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27062, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27062, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来杀死害虫和杂草的药，农民用它保护庄稼。", "primary_collocate": null, "pronunciation": "huà xué nóng yào", "ipa": "xua˥˩ ɕɥe˧˥ noŋ˧˥ jɑʊ˥˩", "syllable_count": 4, "sentences": [{"text": "地里虫子太多，农民喷了化学农药。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把化学农药放在孩子拿不到的地方。", "target_word": "化学农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋化学农药是用来杀草的。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "庄稼上有虫，农民就用化学农药。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人说吃的菜里不该有化学农药。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷种了一辈子菜，从不用化学农药。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人戴着口罩，往田里撒化学农药。", "target_word": "化学农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种化学农药的味道很难闻。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，化学农药会流进小河。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了多收粮食，他们每年都买化学农药。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "农药", "label": "简称"}, {"form": "种", "label": "量词"}, {"form": "袋", "label": "量词"}], "register": "中性", "sense_fingerprint": "农民用来杀虫、除草、保护庄稼的化学药剂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b8871e-37c6-4207-918f-20fe6c25658f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27062, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "化学农药", "is_correct": true, "explanation": "正确：农民喷洒它来杀虫，与“地里虫子太多”的语境一致。"}, {"text": "香水", "is_correct": false, "explanation": "语义：香水是化妆品，喷洒它不能杀虫，与“虫子太多”的语境矛盾。"}, {"text": "瓜子", "is_correct": false, "explanation": "搭配：“喷瓜子”不是常见说法，与“喷”的搭配不当。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是饮品，不能用来杀虫，与“虫子太多”的语境矛盾。"}], "explanations": {"化学农药": "正确：农民喷洒它来杀虫，与“地里虫子太多”的语境一致。", "香水": "语义：香水是化妆品，喷洒它不能杀虫，与“虫子太多”的语境矛盾。", "瓜子": "搭配：“喷瓜子”不是常见说法，与“喷”的搭配不当。", "牛奶": "语义：牛奶是饮品，不能用来杀虫，与“虫子太多”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "化学农药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民买了一棵化学农药。", "explanation": "这里应该用〈瓶〉或〈袋〉。农药不用“棵”计量，“棵”多用于植物。"}, {"text": "农民就用化学农药给庄稼施肥。", "explanation": "这里应该用〈化肥〉。化学农药是用来杀虫的，不能用来施肥。"}, {"text": "农民就用化学农药来炒菜。", "explanation": "这里应该用〈食用油〉。化学农药不能用于烹饪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "化学农药", "is_correct": true, "explanation": "正确：工人戴着口罩撒的是有毒的化学农药，与“戴口罩”的语境一致。"}, {"text": "糖果", "is_correct": false, "explanation": "语义：撒糖果不需要戴口罩，糖果也不是田里的用料，与语境矛盾。"}, {"text": "白糖", "is_correct": false, "explanation": "语义：撒白糖不需要防护，与“戴着口罩”的语境矛盾。"}, {"text": "灰尘", "is_correct": false, "explanation": "搭配：“撒灰尘”不是常见说法，一般说“扬起灰尘”。"}], "explanations": {"化学农药": "正确：工人戴着口罩撒的是有毒的化学农药，与“戴口罩”的语境一致。", "糖果": "语义：撒糖果不需要戴口罩，糖果也不是田里的用料，与语境矛盾。", "白糖": "语义：撒白糖不需要防护，与“戴着口罩”的语境矛盾。", "灰尘": "搭配：“撒灰尘”不是常见说法，一般说“扬起灰尘”。"}, "sentence_index": 6, "correct_answer": "化学农药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了多收粮食，他们每年都种化学农药。", "explanation": "这里应该用〈喷〉。化学农药是喷洒使用的，不能说“种”。"}, {"text": "为了多收粮食，他们每年都吃化学农药。", "explanation": "这里应该用〈使用〉。化学农药不能食用，“吃”的用法不对。"}, {"text": "为了多收粮食，他们每年都给化学农药浇水。", "explanation": "这里应该用〈喷洒〉。化学农药要喷洒使用，不能说“浇水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民正在喷了化学农药。", "corrected_sentence": "农民正在喷化学农药。", "error_description": "错误：“正在”表示动作进行中，后面又加了“了”表示完成，两者矛盾。正确：表示进行时只用“正在”，不加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只化学农药太贵了。", "corrected_sentence": "这瓶化学农药太贵了。", "error_description": "量词错误：“只”多用于动物或成对物件中的单件，不能用来计量“化学农药”。正确：农药多以瓶、袋计量，应说“这瓶化学农药”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27064, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
