INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27070, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "我们住的地方，有空气、水和食物，这就是生存环境。", "primary_collocate": null, "pronunciation": "shēng cún huán jìng", "ipa": "ʂɤŋ˥ tsʰwən˧˥ xwan˧˥ tɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "空气、水和食物是生存环境的一部分。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟的生存环境是树林。", "target_word": "生存环境", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "鱼的生存环境是河里和海里。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙漠的生存环境很差，水很少。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里有水有树，是动物很好的生存环境。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要爱护自己的生存环境。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方冬天很冷，那里的生存环境不好。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们看了海边动物的生存环境。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "熊猫的生存环境在山上的竹林里。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有水和食物，就没有好的生存环境。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "生存環境", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生活的地方，有空气、水和食物（日常说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048066ef-e0c6-43cd-971f-4df52a6c6dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生存环境", "is_correct": true, "explanation": "正确：“生存环境”指我们住的地方，有空气、水和食物，符合句意。"}, {"text": "收入", "is_correct": false, "explanation": "语义：收入是钱的来源，空气、水和食物不是收入的一部分。"}, {"text": "体貌", "is_correct": false, "explanation": "体貌：体貌指人的外形，与空气、水和食物无关，不能作“一部分”。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是受教育的记录，不是空气和食物的一部分。"}], "explanations": {"生存环境": "正确：“生存环境”指我们住的地方，有空气、水和食物，符合句意。", "收入": "语义：收入是钱的来源，空气、水和食物不是收入的一部分。", "体貌": "体貌：体貌指人的外形，与空气、水和食物无关，不能作“一部分”。", "学历": "语义：学历是受教育的记录，不是空气和食物的一部分。"}, "sentence_index": 0, "correct_answer": "生存环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张沙发的生存环境很好，放在客厅里很舒服。", "explanation": "这里应该用〈摆放位置〉。生存环境指我们住的地方，有空气、水和食物，沙发是家具，谈它放在哪里要用〈摆放位置〉。"}, {"text": "这把吉他的生存环境很干燥，琴弦不容易生锈。", "explanation": "这里应该用〈保存环境〉。生存环境指我们住的地方，有空气、水和食物，吉他不是生物，谈存放条件要用〈保存环境〉。"}, {"text": "这台电脑的生存环境很稳定，运行速度很快。", "explanation": "〈生存环境〉指生物的生存条件，电脑不是生物，不能说它有生存环境，这里应该用〈运行环境〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生存环境", "is_correct": true, "explanation": "正确：“生存环境”指生物生存的外界条件，“那里的生存环境不好”成立。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：嗓音是人或动物发出的声音，不能用来评价一个地方的好坏。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人或生物的高矮，不能用来说“那里的身高不好”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人或事物存在的时长，不能用来评价地方的生存条件。"}], "explanations": {"生存环境": "正确：“生存环境”指生物生存的外界条件，“那里的生存环境不好”成立。", "嗓音": "语义：嗓音是人或动物发出的声音，不能用来评价一个地方的好坏。", "身高": "体貌：身高指人或生物的高矮，不能用来说“那里的身高不好”。", "年龄": "语义：年龄指人或事物存在的时长，不能用来评价地方的生存条件。"}, "sentence_index": 6, "correct_answer": "生存环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支钢笔的生存环境很好，写字很顺。", "explanation": "这里应该用〈使用环境〉。生存环境指我们住的地方，有空气、水和食物，钢笔不是生物，谈使用条件要用〈使用环境〉。"}, {"text": "这台收音机的生存环境很好，声音很清楚。", "explanation": "这里应该用〈工作环境〉。生存环境指我们住的地方，有空气、水和食物，收音机不是生物，谈设备的运行条件要用〈工作环境〉。"}, {"text": "这台复印机的生存环境很好，纸张不容易卡住。", "explanation": "这里应该用〈运行环境〉。生存环境指我们住的地方，有空气、水和食物，复印机不是生物，谈运行条件要用〈运行环境〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片草原的生存环境好很。", "corrected_sentence": "这片草原的生存环境很好。", "error_description": "错误：语序。程度副词“很”应放在形容词“好”之前，应说“很好”，不能说“好很”。错误形式“生存环境好很”，正确形式“生存环境很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里有一只很好的生存环境，适合很多鸟。", "corrected_sentence": "这里有一种很好的生存环境，适合很多鸟。", "error_description": "错误：量词。“生存环境”是抽象名词，应用量词“种”或“个”，“只”用于动物或成对的东西。错误形式“一只很好的生存环境”，正确形式“一种很好的生存环境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
