INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27074, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6613ce0-ba69-401c-9059-36a04fcd6251') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27074, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "花粉从一朵花跑到另一朵花上。", "primary_collocate": null, "pronunciation": "chuán fěn", "ipa": "tʂʰwan˧˥ fən˨˩˦", "syllable_count": 2, "sentences": [{"text": "蜜蜂帮花传粉。", "target_word": "传粉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "花开了，蜜蜂来传粉。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风来了，花就开始传粉。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有蜜蜂，苹果树很难传粉。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些花靠小鸟传粉。", "target_word": "传粉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天花多，蜜蜂每天忙着传粉。", "target_word": "传粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶飞过花园，也帮忙传粉。", "target_word": "传粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂传粉后，花才能结果。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白天蜜蜂传粉，晚上有的花靠蛾子传粉。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花不能自己走，所以要靠动物或风来传粉。", "target_word": "传粉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传粉者", "label": "复合"}, {"form": "傳粉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "通俗说法：花粉从一朵花到另一朵花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e78e7629-b941-480b-9bbb-59f93d1c33f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传粉", "is_correct": true, "explanation": "正确：“蜜蜂帮花传粉”指蜜蜂帮助花把花粉转移到另一朵花上，“传粉”符合句意。"}, {"text": "采蜜", "is_correct": false, "explanation": "配价：“采蜜”的施事是蜜蜂，“帮花采蜜”的意思是替花去采蜜，不合事理。"}, {"text": "冬眠", "is_correct": false, "explanation": "语义：“冬眠”指动物冬季休眠，蜜蜂不能帮花冬眠，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”指人悠闲地行走，与蜜蜂帮花的动作无关。"}], "explanations": {"传粉": "正确：“蜜蜂帮花传粉”指蜜蜂帮助花把花粉转移到另一朵花上，“传粉”符合句意。", "采蜜": "配价：“采蜜”的施事是蜜蜂，“帮花采蜜”的意思是替花去采蜜，不合事理。", "冬眠": "语义：“冬眠”指动物冬季休眠，蜜蜂不能帮花冬眠，句意不通。", "散步": "语义：“散步”指人悠闲地行走，与蜜蜂帮花的动作无关。"}, "sentence_index": 0, "correct_answer": "传粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种鱼一到春天就开始传粉。", "explanation": "这里应该用〈繁殖〉。传粉只指花粉的转移，鱼类产卵、生育后代要用繁殖。"}, {"text": "这门手艺一代代传粉下来。", "explanation": "这里应该用〈传承〉。传粉指花粉的转移，不用于技艺、文化的承继。"}, {"text": "这台机器把数据传粉到了服务器。", "explanation": "这里应该用〈传送〉。传粉只指植物花粉的转移，不用于数据、信号的发送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6613ce0-ba69-401c-9059-36a04fcd6251') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传粉", "is_correct": true, "explanation": "正确：蝴蝶飞过花园时帮忙把花粉转移到花上，“传粉”符合句意。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”需要发声和表演，与蝴蝶飞过花园的语境不符，“也帮忙唱歌”句意不通。"}, {"text": "下棋", "is_correct": false, "explanation": "配价：“下棋”的施事必须是人，蝴蝶不能下棋。"}, {"text": "作画", "is_correct": false, "explanation": "语义：“作画”指人的艺术创作，与蝴蝶帮忙的动作无关。"}], "explanations": {"传粉": "正确：蝴蝶飞过花园时帮忙把花粉转移到花上，“传粉”符合句意。", "唱歌": "语义：“唱歌”需要发声和表演，与蝴蝶飞过花园的语境不符，“也帮忙唱歌”句意不通。", "下棋": "配价：“下棋”的施事必须是人，蝴蝶不能下棋。", "作画": "语义：“作画”指人的艺术创作，与蝴蝶帮忙的动作无关。"}, "sentence_index": 6, "correct_answer": "传粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆汽车很快就在路上传粉了。", "explanation": "这里的“传粉”被误用为“行驶、移动”的意思。传粉指花粉从一朵花跑到另一朵花上，汽车在路上行驶不能用传粉。"}, {"text": "这块石头很快就在河底传粉了。", "explanation": "这里的“传粉”被误用为“滚动、移动”的意思。传粉只指花粉从一朵花传到另一朵花，石头在河底滚动不能用传粉。"}, {"text": "这支乐曲很快就在城市里传粉了。", "explanation": "乐曲不是花粉，传粉只指花粉的传递，不能用于音乐的流传。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6613ce0-ba69-401c-9059-36a04fcd6251') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一带的花大多靠蜜蜂了传粉。", "corrected_sentence": "这一带的花大多靠蜜蜂传粉。", "error_description": "“了”误加在动词“传粉”之前。“靠蜜蜂传粉”表示习惯性的方式，不需要“了”，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6613ce0-ba69-401c-9059-36a04fcd6251') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蝴蝶总在花丛间把花传粉。", "corrected_sentence": "蝴蝶总在花丛间给花传粉。", "error_description": "介词误用：“传粉”是不及物动词，不能用“把”带宾语，应改为“给花传粉”，用介词“给”引出受益的花。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6613ce0-ba69-401c-9059-36a04fcd6251') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27076, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27076, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27076, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西最外面的一层。", "primary_collocate": null, "pronunciation": "biǎo céng", "ipa": "pjɑʊ˨˩˦ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他用刀削掉了萝卜的表层。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛋糕的表层有一层巧克力。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这面墙的表层掉了一块。", "target_word": "表层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大雪盖住了山坡的表层。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "铁锅的表层有点生锈了。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先把面包的表层烤脆，再放进盘子里。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地毯的表层很软，踩上去很舒服。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种油漆干得快，表层一小时就干了。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只擦了桌子的表层，里面还是很脏。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗衣服时，水只能湿到衣服的表层。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "表層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西最外面的一层，是看得见、摸得到的外层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d3adfa-528b-4034-a494-9783488f8294') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27076, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表层", "is_correct": true, "explanation": "正确：“表层”指萝卜最外面的一层，可以被刀削掉。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色不是可以被削掉的部分，与“削掉”不搭配。"}, {"text": "汁水", "is_correct": false, "explanation": "语义：汁水是液体，不是可以被刀削掉的外层。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”不能被“削掉”，削掉的是有形的部分。"}], "explanations": {"表层": "正确：“表层”指萝卜最外面的一层，可以被刀削掉。", "颜色": "体貌：颜色不是可以被削掉的部分，与“削掉”不搭配。", "汁水": "语义：汁水是液体，不是可以被刀削掉的外层。", "重量": "搭配：“重量”不能被“削掉”，削掉的是有形的部分。"}, "sentence_index": 0, "correct_answer": "表层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的表层很冷淡，不太爱说话。", "explanation": "这里应该用〈性格〉。表层指东西的外侧，形容人的态度要用性格，不说表层。"}, {"text": "这份报告的表层很长，足足有五十页。", "explanation": "这里应该用〈篇幅〉。表层指东西外侧的一层，说文章的长短要用篇幅，不说表层。"}, {"text": "这个小区的表层很安静，住户很少出门。", "explanation": "这里应该用〈外围〉。表层指物体的外侧，说小区的边缘地带要用外围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表层", "is_correct": true, "explanation": "正确：“表层”指地毯的外侧，“软”形容的正是这一层的质地。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“软”形容质地，不能说价格很软。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味没有软硬之分，与句中描述的触感不符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不能用“软”来形容，地毯的软硬指的是触感。"}], "explanations": {"表层": "正确：“表层”指地毯的外侧，“软”形容的正是这一层的质地。", "价格": "搭配：“软”形容质地，不能说价格很软。", "气味": "语义：气味没有软硬之分，与句中描述的触感不符。", "温度": "语义：温度不能用“软”来形容，地毯的软硬指的是触感。"}, "sentence_index": 6, "correct_answer": "表层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的表层很懂事，从不让父母操心。", "explanation": "这里应该用〈表现〉。表层指东西最外面的一层，不能用来说人的行为，应该用表现。"}, {"text": "这个歌手的表层很火，粉丝越来越多。", "explanation": "这里应该用〈人气〉。表层指物体的外侧，不能用来说人的知名度。"}, {"text": "这幅画的表层很贵，一共卖了一百万。", "explanation": "这里应该用〈价格〉。表层指物体的外侧，说作品值多少钱要用价格，不说表层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨水先湿了山坡的很表层。", "corrected_sentence": "雨水先湿了山坡的表层。", "error_description": "错误：“表层”是名词，前面不能加程度副词“很”修饰，应去掉“很”，改为“山坡的表层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这层油漆的表层透干了。", "corrected_sentence": "这层油漆的表层干透了。", "error_description": "错误：结果补语“透”应放在动词“干”之后，构成“干透”，不能说“透干”。正确：“表层干透了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
