INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27080, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "田里种植的各类作物，如粮食、蔬菜、棉花等。", "primary_collocate": null, "pronunciation": "nóng zuò wù", "ipa": "nʊŋ˧˥ tswo˥˩ u˥˩", "syllable_count": 3, "sentences": [{"text": "农民把田里的农作物卖到城里。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到了，田里的农作物都成熟了。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米是一种常见的农作物。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片田种着很多农作物。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，田里的农作物都泡在水里。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在地里收农作物，我去帮忙。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农作物长大以前，要常常浇水。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近的田里种过很多农作物。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些农作物是农民自己种的，很新鲜。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，农民开始在田里种农作物。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "農作物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "田里种植的粮食、蔬菜、棉花等作物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d3adfa-528b-4034-a494-9783488f8294') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27080, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农作物", "is_correct": true, "explanation": "正确：“农作物”是田里种出来、能卖到城里的东西，与句意相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：田里不会长出汽车，句中卖的应是种出来的东西。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具不是田里种出来的，与句中的“田里”不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“田里的冰箱”不是常见搭配，冰箱不会出现在田里。"}], "explanations": {"农作物": "正确：“农作物”是田里种出来、能卖到城里的东西，与句意相符。", "汽车": "语义：田里不会长出汽车，句中卖的应是种出来的东西。", "家具": "语义：家具不是田里种出来的，与句中的“田里”不符。", "冰箱": "搭配：“田里的冰箱”不是常见搭配，冰箱不会出现在田里。"}, "sentence_index": 0, "correct_answer": "农作物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民在猪圈里养了很多农作物。", "explanation": "这里应该用〈牲畜〉。农作物是田里种出来的植物，不能在猪圈里养。"}, {"text": "渔船上装满了农作物。", "explanation": "这里应该用〈鱼虾〉。农作物指栽培的植物，渔船装的是鱼虾。"}, {"text": "这一台农作物长得很好。", "explanation": "这里应该用〈种〉。农作物的量词是“种”，不用“台”，“台”多用于机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "农作物", "is_correct": true, "explanation": "正确：“农作物”是生物，长大以前需要常常浇水，与句意相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会长大，也不需要浇水。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“长大”不用于电脑，电脑不需要浇水。"}, {"text": "小说", "is_correct": false, "explanation": "配价：“长大”的主语需是生物，“小说”不能作主语。"}], "explanations": {"农作物": "正确：“农作物”是生物，长大以前需要常常浇水，与句意相符。", "房子": "语义：房子不会长大，也不需要浇水。", "电脑": "搭配：“长大”不用于电脑，电脑不需要浇水。", "小说": "配价：“长大”的主语需是生物，“小说”不能作主语。"}, "sentence_index": 6, "correct_answer": "农作物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在厨房里做了很多农作物。", "explanation": "这里应该用〈饭菜〉。农作物是种出来的，不是做出来的，做的应是饭菜。"}, {"text": "他买了一头农作物。", "explanation": "这里应该用〈种〉。农作物的量词是“种”，不用“头”。"}, {"text": "他去医院探望了农作物。", "explanation": "这里应该用〈病人〉。探望的对象是人，农作物是植物，不能探望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家今年种了一个新农作物。", "corrected_sentence": "我家今年种了一种新农作物。", "error_description": "错误：量词用错。正确：“一种新农作物”，农作物的量词是“种”，不用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏天雨多，农作物们长得很快。", "corrected_sentence": "夏天雨多，农作物长得很快。", "error_description": "错误：“农作物”指植物，不能加复数词尾“们”。正确：去掉“们”，说“农作物长得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
