INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27090, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蜂类是一种会飞的小虫子，它们会采花蜜。", "primary_collocate": null, "pronunciation": "fēng lèi", "ipa": "fɤŋ˥ leɪ˥˩", "syllable_count": 2, "sentences": [{"text": "蜂类会飞，也会采花蜜。", "target_word": "蜂类", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "花园里来了很多蜂类。", "target_word": "蜂类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多蜂类身体很小，有的还有刺。", "target_word": "蜂类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜂类喜欢在花上飞来飞去。", "target_word": "蜂类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，蜂类的刺会让人很疼。", "target_word": "蜂类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂是一种常见的蜂类。", "target_word": "蜂类", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我弟弟不怕蜂类，还敢靠近蜂巢看。", "target_word": "蜂类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天院子里的蜂类特别多，大家都不敢出去。", "target_word": "蜂类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人对蜂类过敏，叮一下就会很危险。", "target_word": "蜂类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带我们去看了花园里的蜂类，还拍了照片。", "target_word": "蜂类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜂類", "label": "繁体"}], "register": "中性", "sense_fingerprint": "会飞、会采花蜜、多有刺的小虫子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '703145e0-38ab-495d-a56f-5eaa17780ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27090, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜂类", "is_correct": true, "explanation": "正确：「蜂类」会飞，也会采花蜜，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会飞，也不采花蜜，句意不通。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象身体太大，不会飞，与句中的飞行能力相矛盾。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠不采花蜜，也不会这样飞，句子不成立。"}], "explanations": {"蜂类": "正确：「蜂类」会飞，也会采花蜜，与句意相符。", "石头": "语义：石头不会飞，也不采花蜜，句意不通。", "大象": "体貌：大象身体太大，不会飞，与句中的飞行能力相矛盾。", "老鼠": "语义：老鼠不采花蜜，也不会这样飞，句子不成立。"}, "sentence_index": 0, "correct_answer": "蜂类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花园里飞来了一朵蜂类。", "explanation": "这里应该用〈种〉。「朵」用于花，蜂类是昆虫，不能用「朵」来计量。"}, {"text": "蜂类会吸人的血，夏天特别讨厌。", "explanation": "这里应该用〈蚊子〉。蜂类采花蜜，不吸血；吸人血、让人夏天讨厌的是蚊子。"}, {"text": "这种蜂类很甜，孩子们都爱吃。", "explanation": "这里应该用〈水果〉。蜂类是昆虫，不是食物，不能说「很甜，孩子们都爱吃」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜂类", "is_correct": true, "explanation": "正确：「蜂类」是会飞、有的会蜇人的昆虫，与「不怕……还敢靠近蜂巢看」相符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「不怕」的对象是事物或动物，「体重」不能被「不怕」。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典不会蜇人，也不会在蜂巢旁边，句意荒谬。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不是会蜇人的东西，与「靠近蜂巢」的语境不符。"}], "explanations": {"蜂类": "正确：「蜂类」是会飞、有的会蜇人的昆虫，与「不怕……还敢靠近蜂巢看」相符。", "体重": "搭配：「不怕」的对象是事物或动物，「体重」不能被「不怕」。", "字典": "语义：字典不会蜇人，也不会在蜂巢旁边，句意荒谬。", "电视": "语义：电视不是会蜇人的东西，与「靠近蜂巢」的语境不符。"}, "sentence_index": 6, "correct_answer": "蜂类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上喝一杯蜂类水。", "explanation": "这里应该用〈蜂蜜水〉。蜂类是昆虫，不能用来做饮料。"}, {"text": "早餐我吃了两个蜂类。", "explanation": "这里应该用〈鸡蛋〉。「吃」和「个」用于食物，蜂类是昆虫，不能当作食物。"}, {"text": "我们在蜂类里玩耍。", "explanation": "这里应该用〈花园〉。「在……里」后面要接地点，蜂类不是地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只蜂类，平时在花园里采蜜。", "corrected_sentence": "这是一种蜂类，平时在花园里采蜜。", "error_description": "量词错误：「只」用于单个动物，「蜂类」是一类昆虫的统称，应说「一种蜂类」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在院子里发现了很多蜂类们。", "corrected_sentence": "我们在院子里发现了很多蜂类。", "error_description": "错误形式：“蜂类们”；正确形式：“蜂类”。“蜂类”是昆虫的统称，属于类别名词，不能再加“们”表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
