INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27098, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "敌人或坏人进入别人的地方做坏事。", "primary_collocate": null, "pronunciation": "rù qīn", "ipa": "ʐu˥˩ tɕʰin˥", "syllable_count": 2, "sentences": [{"text": "坏人入侵了我们的村子，大家都很害怕。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人想入侵我们的国家。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个坏人入侵别人的院子，想偷东西。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵守在城门口，不让敌人入侵。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里，坏巨人入侵小镇，抢走了粮食。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了不让坏人入侵，他们在门口加了锁。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海盗入侵小岛，岛上的人逃进了山里。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城墙是为了挡住外族入侵而修的。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人入侵的那天晚上，下着大雨。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小偷入侵了他的家，拿走了很多东西。", "target_word": "入侵", "complexity_tier": "T3", "furigana": "rù qīn", "sentence_source": "generated"}], "morphological_forms": [{"form": "入侵了", "label": "完成体"}, {"form": "入侵过", "label": "经历体"}, {"form": "入侵者", "label": "复合"}], "register": "中性", "sense_fingerprint": "敌人或坏人闯进别人的地方做坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '703145e0-38ab-495d-a56f-5eaa17780ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27098, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保护", "is_correct": false, "explanation": "语义：保护是爱护、守护的行为，坏人不会保护村子，句中大家却很害怕。"}, {"text": "投降", "is_correct": false, "explanation": "配价：“投降”是不及物动词，后面不能直接带“村子”作宾语。"}, {"text": "入侵", "is_correct": true, "explanation": "坏人闯进村子做坏事，与“大家都很害怕”相符。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：夸奖是表扬，坏人夸奖村子与“大家都很害怕”的语境矛盾。"}], "explanations": {"保护": "语义：保护是爱护、守护的行为，坏人不会保护村子，句中大家却很害怕。", "投降": "配价：“投降”是不及物动词，后面不能直接带“村子”作宾语。", "入侵": "坏人闯进村子做坏事，与“大家都很害怕”相符。", "夸奖": "语义：夸奖是表扬，坏人夸奖村子与“大家都很害怕”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "入侵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们入侵了博物馆，看到了很多画。", "explanation": "这里应该用〈参观〉。入侵指坏人或敌人闯进别处做坏事，正常参观不能用入侵。"}, {"text": "我们入侵了一家旅馆，房间很干净。", "explanation": "这里应该用〈入住〉。入侵含有敌对和破坏的意思，住进旅馆要用入住。"}, {"text": "他们入侵了这个难题，大家都很高兴。", "explanation": "这里应该用〈攻克〉。入侵只用于闯入地区或系统，难题要用攻克。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27098, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赞美", "is_correct": false, "explanation": "语义：赞美是称赞，与“海盗入侵小岛，岛上的人逃进了山里”的语境矛盾。"}, {"text": "入侵", "is_correct": true, "explanation": "海盗闯进小岛做坏事，岛上的人被迫逃走，符合句意。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是房屋、道路等人造物，不能说修建小岛。"}, {"text": "投靠", "is_correct": false, "explanation": "配价：“投靠”的对象是人，不能说投靠小岛。"}], "explanations": {"赞美": "语义：赞美是称赞，与“海盗入侵小岛，岛上的人逃进了山里”的语境矛盾。", "入侵": "海盗闯进小岛做坏事，岛上的人被迫逃走，符合句意。", "修建": "搭配：“修建”的对象是房屋、道路等人造物，不能说修建小岛。", "投靠": "配价：“投靠”的对象是人，不能说投靠小岛。"}, "sentence_index": 6, "correct_answer": "入侵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生入侵了教室，然后认真听课。", "explanation": "这里应该用〈进入〉。入侵指坏人或敌人未经允许闯入并做坏事，学生正常走进教室不能用入侵。"}, {"text": "他入侵了公司的钱，然后存进了银行。", "explanation": "这里应该用〈侵占〉。入侵指闯入地方做坏事，财物被非法据为己有要用侵占。"}, {"text": "他入侵了前排的座位，大家都没意见。", "explanation": "这里应该用〈占据〉。入侵含有破坏、威胁的意思，占座位只说占据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一伙强盗在入侵了北边的小镇。", "corrected_sentence": "一伙强盗入侵了北边的小镇。", "error_description": "错误形式：“在入侵了”；正确形式：“入侵了”。“在”表示动作正在进行，与表示完成的“了”不能同时用于同一动作，句中是已经完成的入侵，应去掉“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "强盗入侵的了他的店铺，拿走了现金。", "corrected_sentence": "强盗入侵了他的店铺，拿走了现金。", "error_description": "错误形式：“入侵的了”；正确形式：“入侵了”。表示动作完成要在动词后用“了”，“的”不能放在动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
