INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27106, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27106, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "太多地使用，不珍惜地使用。", "primary_collocate": null, "pronunciation": "làn yòng", "ipa": "lan˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们不能滥用水资源，要节约用水。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子滥用零花钱，月底一分也没有了。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要滥用纸巾，大家都要爱惜资源。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他滥用电力，房间的灯一整天都开着。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好东西不要滥用，用完就没有了。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里不能滥用纸张，两面都要用。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是滥用朋友的信任，从不珍惜。", "target_word": "滥用", "complexity_tier": "T3", "furigana": "làn yòng", "sentence_source": "generated"}, {"text": "弟弟滥用塑料袋，一次拿了十几个。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有水的时候也不能滥用，因为水很珍贵。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里缺水，村民从不滥用每一滴水。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "滥用了", "label": "完成体"}, {"form": "滥用过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "不珍惜、用得太多，指浪费水、纸张、钱、好意等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '703145e0-38ab-495d-a56f-5eaa17780ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "滥用", "is_correct": true, "explanation": "正确：“滥用”指不珍惜地过度使用，与后半句“要节约用水”形成对照。"}, {"text": "节约", "is_correct": false, "explanation": "语义：“不能节约水资源”与后半句“要节约用水”的要求相反。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”的对象是植物或土地，不能搭配“水资源”这类资源概念。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“不能保护水资源”与“要节约用水”的主旨相悖，句意不通。"}], "explanations": {"滥用": "正确：“滥用”指不珍惜地过度使用，与后半句“要节约用水”形成对照。", "节约": "语义：“不能节约水资源”与后半句“要节约用水”的要求相反。", "浇灌": "搭配：“浇灌”的对象是植物或土地，不能搭配“水资源”这类资源概念。", "保护": "语义：“不能保护水资源”与“要节约用水”的主旨相悖，句意不通。"}, "sentence_index": 0, "correct_answer": "滥用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校鼓励大家滥用纸张。", "explanation": "这里应该用〈节约〉。“滥用”指用得太多、不珍惜，与“鼓励”的意思相反，应说“节约纸张”。"}, {"text": "我们要滥用每一粒粮食。", "explanation": "这里应该用〈珍惜〉。“滥用”与“珍惜”意思相反，应说“珍惜每一粒粮食”。"}, {"text": "我每天都滥用零用钱，攒着买书。", "explanation": "这里应该用〈节省〉。“滥用”指太多地使用，与“攒着买书”的节俭意思相反，应说“节省零用钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滥用", "is_correct": true, "explanation": "正确：“他总是滥用朋友的信任”指不珍惜地消耗信任，与“从不珍惜”一致。"}, {"text": "珍惜", "is_correct": false, "explanation": "语义：“珍惜朋友的信任”与后半句“从不珍惜”直接矛盾。"}, {"text": "珍视", "is_correct": false, "explanation": "语义：「珍视朋友的信任」与后半句「从不珍惜」直接矛盾。"}, {"text": "维护", "is_correct": false, "explanation": "语义：“维护信任”与“从不珍惜”相矛盾。"}], "explanations": {"滥用": "正确：“他总是滥用朋友的信任”指不珍惜地消耗信任，与“从不珍惜”一致。", "珍惜": "语义：“珍惜朋友的信任”与后半句“从不珍惜”直接矛盾。", "珍视": "语义：「珍视朋友的信任」与后半句「从不珍惜」直接矛盾。", "维护": "语义：“维护信任”与“从不珍惜”相矛盾。"}, "sentence_index": 6, "correct_answer": "滥用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂一直滥用电，成本很低。", "explanation": "这里应该用〈节电〉。“滥用”指太多地使用，与“成本很低”的结果矛盾，应说“一直节电”。"}, {"text": "农民要合理滥用化肥。", "explanation": "这里应该用〈使用〉。“滥用”含贬义，不能与“合理”搭配，应说“合理使用化肥”。"}, {"text": "我们要滥用公共财产。", "explanation": "这里应该用〈维护〉。“滥用”指过度不珍惜地使用，与“维护公共财产”的要求相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校要求大家不要滥用了空调。", "corrected_sentence": "学校要求大家不要滥用空调。", "error_description": "体标错误：“不要”后不能加完成体“了”。应为“不要滥用空调”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从不滥用过学校的资源。", "corrected_sentence": "他从没滥用过学校的资源。", "error_description": "否定词错误：表示“从来没有”的经历要用“从没”，“从不”只用于习惯，不能与“过”同用。应为“从没滥用过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
