INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27110, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "小动物出去找吃的。", "primary_collocate": null, "pronunciation": "mì shí", "ipa": "mi˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "小鸟一早就飞出去觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小松鼠在树下觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小老鼠趁着夜里出来觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，小蜜蜂出门觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸡跟着妈妈在地上觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，小青蛙爬出来觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跑到院子里觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸭子排着队去河边觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷了，小麻雀到处觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小蚂蚁一大早就出门觅食了。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "觅食了", "label": "体标"}, {"form": "觅食过", "label": "体标"}], "register": "中性", "sense_fingerprint": "小动物外出找吃的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ca8de9-da7d-4909-9408-983c1c2cb8f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27110, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "觅食", "is_correct": true, "explanation": "正确：觅食（mì shí），指小动物出去找吃的。"}, {"text": "密室", "is_correct": false, "explanation": "mì shì（第四声）与 mì shí（第二声）声调不同，意思是秘密的房间。"}, {"text": "迷失", "is_correct": false, "explanation": "mí shī（第二、第一声）与 mì shí（第四、第二声）声调不同，意思是迷路、找不到。"}, {"text": "米食", "is_correct": false, "explanation": "mǐ shí（第三声）与 mì shí（第四声）声调不同，意思是用米做的食物。"}], "explanations": {"觅食": "正确：觅食（mì shí），指小动物出去找吃的。", "密室": "mì shì（第四声）与 mì shí（第二声）声调不同，意思是秘密的房间。", "迷失": "mí shī（第二、第一声）与 mì shí（第四、第二声）声调不同，意思是迷路、找不到。", "米食": "mǐ shí（第三声）与 mì shí（第四声）声调不同，意思是用米做的食物。"}, "sentence_index": null, "correct_answer": "觅食"}, "level_3": {"options": [{"text": "上学", "is_correct": false, "explanation": "语义：小鸟不上学，与“一早就飞出去”的动物行为不符。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：小鸟不下棋，句子说的是它出去找吃的。"}, {"text": "觅食", "is_correct": true, "explanation": "正确：作谓语，说明小鸟一早出去找吃的。"}, {"text": "梳妆", "is_correct": false, "explanation": "体貌：“梳妆”说的是人的打扮，不用于小鸟外出的行为。"}], "explanations": {"上学": "语义：小鸟不上学，与“一早就飞出去”的动物行为不符。", "下棋": "语义：小鸟不下棋，句子说的是它出去找吃的。", "觅食": "正确：作谓语，说明小鸟一早出去找吃的。", "梳妆": "体貌：“梳妆”说的是人的打扮，不用于小鸟外出的行为。"}, "sentence_index": 0, "correct_answer": "觅食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房里觅食。", "explanation": "这里应该用〈做饭〉。觅食只说动物找吃的，人在厨房用〈做饭〉。"}, {"text": "病人只能觅食。", "explanation": "这里应该用〈进食〉。人吃东西说〈进食〉，觅食只用于动物寻找食物。"}, {"text": "学生们在教室里觅食。", "explanation": "这里应该用〈学习〉。学生在教室里说〈学习〉，觅食只用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做饭", "is_correct": false, "explanation": "语义：小猫不做饭，与“跑到院子里”的行为不符。"}, {"text": "觅食", "is_correct": true, "explanation": "正确：作谓语，说明小猫跑到院子里找吃的。"}, {"text": "写字", "is_correct": false, "explanation": "语义：小猫不会写字，“跑到院子里”与写字无关。"}, {"text": "上班", "is_correct": false, "explanation": "语义：小猫不上班，这与“跑到院子里”的行为不符。"}], "explanations": {"做饭": "语义：小猫不做饭，与“跑到院子里”的行为不符。", "觅食": "正确：作谓语，说明小猫跑到院子里找吃的。", "写字": "语义：小猫不会写字，“跑到院子里”与写字无关。", "上班": "语义：小猫不上班，这与“跑到院子里”的行为不符。"}, "sentence_index": 6, "correct_answer": "觅食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在档案室觅食旧文件。", "explanation": "这里应该用〈查找〉。查找用于找文件、资料，觅食只指动物找吃的。"}, {"text": "工人在工地上觅食。", "explanation": "这里应该用〈干活〉。工人在工地是干活，觅食只用于动物找吃的。"}, {"text": "我的手机每天都在觅食。", "explanation": "这里是把〈觅食〉当成手机搜寻信息、数据来用。觅食只指动物寻找食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小松鼠在树下在觅食了一会儿。", "corrected_sentence": "小松鼠在树下觅食了一会儿。", "error_description": "错误在多加了一个“在”：“在树下”已表示地点，动词“觅食”前不应再加“在”，应为“在树下觅食了一会儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸡跟着妈妈去院子里很觅食。", "corrected_sentence": "小鸡跟着妈妈去院子里觅食。", "error_description": "错误在多加了程度副词“很”：“觅食”是动词，不能受“很”修饰；删去“很”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
