INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27118, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体内有脊椎骨（脊柱）的动物，比如鱼、鸟、狗。", "primary_collocate": null, "pronunciation": "jǐ zhuī dòng wù", "ipa": "tɕi˨˩ ʈʂweɪ˥ tʊŋ˥˩ wu˥˩", "syllable_count": 4, "sentences": [{"text": "鱼是脊椎动物。", "target_word": "脊椎动物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "狗和鸟都是脊椎动物。", "target_word": "脊椎动物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "脊椎动物身体里有脊柱。", "target_word": "脊椎动物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小猫是脊椎动物，虫子不是。", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的小狗也是脊椎动物。", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上说，青蛙是脊椎动物。", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "脊椎动物有的住在水里，有的住在地上。", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道哪些动物是脊椎动物吗？", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，有骨头的动物叫脊椎动物。", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛇没有腿，但它也是脊椎动物。", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "无脊椎动物", "label": "复合"}, {"form": "脊椎動物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有脊椎骨的动物，如鱼、鸟、狗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2009d73c-bf4e-4a49-ada1-b6ff159c7f51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27118, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脊椎动物", "is_correct": true, "explanation": "正确。鱼有脊柱（骨头），属于脊椎动物。"}, {"text": "植物", "is_correct": false, "explanation": "语义：鱼是动物，不是植物。"}, {"text": "昆虫", "is_correct": false, "explanation": "语义：鱼不是昆虫，昆虫没有脊柱而鱼有。"}, {"text": "哺乳动物", "is_correct": false, "explanation": "搭配：鱼不哺乳，“鱼是哺乳动物”不成立。"}], "explanations": {"脊椎动物": "正确。鱼有脊柱（骨头），属于脊椎动物。", "植物": "语义：鱼是动物，不是植物。", "昆虫": "语义：鱼不是昆虫，昆虫没有脊柱而鱼有。", "哺乳动物": "搭配：鱼不哺乳，“鱼是哺乳动物”不成立。"}, "sentence_index": 0, "correct_answer": "脊椎动物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脊椎动物摔断了，得马上去医院。", "explanation": "用错义项：这里指人的脊柱，但“脊椎动物”是动物类群的名称，不能用来指身体的部位。"}, {"text": "这个池塘里住着一朵脊椎动物。", "explanation": "量词用错：这里应该用〈种〉。“朵”用于花，不能用来数动物；“脊椎动物”作类别时量词用“种”。"}, {"text": "蚯蚓属于脊椎动物，身体里没有骨头。", "explanation": "这里应该用〈无脊椎动物〉。脊椎动物是有骨头（脊柱）的动物，蚯蚓没有骨头，不能归入这一类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脊椎动物", "is_correct": true, "explanation": "正确。脊椎动物有的住在水里，有的住在地上。"}, {"text": "植物", "is_correct": false, "explanation": "搭配：“住”用于人和动物，植物不能“住”。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：石头不会“住”在水里或地上。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是人居住的地方，不会“住在水里”。"}], "explanations": {"脊椎动物": "正确。脊椎动物有的住在水里，有的住在地上。", "植物": "搭配：“住”用于人和动物，植物不能“住”。", "石头": "搭配：石头不会“住”在水里或地上。", "房子": "语义：房子是人居住的地方，不会“住在水里”。"}, "sentence_index": 6, "correct_answer": "脊椎动物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蜜蜂是一种脊椎动物，身体里没有骨头。", "explanation": "这里应该用〈昆虫〉。脊椎动物是有骨头（脊柱）的动物，蜜蜂没有骨头，不能归入这一类。"}, {"text": "我家的小狗是一座脊椎动物。", "explanation": "量词用错：“座”用于山、楼等大型固定物，不能用来数动物；这里指类别时要用“种”。"}, {"text": "他的脊椎动物疼得厉害，只能躺着。", "explanation": "用错义项：这里指人的脊柱，但“脊椎动物”是动物类群，不能用来指身体的部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鱼是一座脊椎动物。", "corrected_sentence": "鱼是一种脊椎动物。", "error_description": "量词错误：应把“座”改为“种”。“座”用于大型固定物，不能数动物；表示类别时要用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "狗属于的脊椎动物，它身体里有骨头。", "corrected_sentence": "狗属于脊椎动物，它身体里有骨头。", "error_description": "错误在“属于”后多加了“的”：“属于”后应直接接宾语“脊椎动物”，即“狗属于脊椎动物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
