INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27124, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里很难过，觉得受不了了。", "primary_collocate": null, "pronunciation": "bēng kuì", "ipa": "pəŋ˥ kʰweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我真的崩溃了！", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到成绩，我当场就崩溃了。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一说分手，她就崩溃了。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈生病了，我真的快崩溃了。", "target_word": "崩溃", "complexity_tier": "T3", "furigana": "bēng kuì", "sentence_source": "generated"}, {"text": "手机丢了，我整个人都崩溃了。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到这个消息，她难过得崩溃了。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作业太多了，同学们都要崩溃了。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他哭着说：“我真的受不了，我崩溃了。”", "target_word": "崩溃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，队员们都崩溃了，坐在地上哭。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别说了，再说我就要崩溃了。", "target_word": "崩溃", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "崩溃了", "label": "体标"}, {"form": "崩溃过", "label": "体标"}, {"form": "崩潰", "label": "繁体"}], "register": "口语", "sense_fingerprint": "心里非常难过，觉得再也受不了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2009d73c-bf4e-4a49-ada1-b6ff159c7f51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "崩溃", "is_correct": true, "explanation": "“我真的崩溃了”表达难过到受不了，与语境一致。"}, {"text": "沸腾", "is_correct": false, "explanation": "搭配：“沸腾”多用于水、场面或人群，不说“我真的沸腾了”来表示心里难受。"}, {"text": "开花", "is_correct": false, "explanation": "语义：“开花”指植物长出花朵，不能用来描述人因难过而承受不住的心理状态。"}, {"text": "腐烂", "is_correct": false, "explanation": "语义：“腐烂”指有机物分解，不能用于描述人的心理状态。"}], "explanations": {"崩溃": "“我真的崩溃了”表达难过到受不了，与语境一致。", "沸腾": "搭配：“沸腾”多用于水、场面或人群，不说“我真的沸腾了”来表示心里难受。", "开花": "语义：“开花”指植物长出花朵，不能用来描述人因难过而承受不住的心理状态。", "腐烂": "语义：“腐烂”指有机物分解，不能用于描述人的心理状态。"}, "sentence_index": 0, "correct_answer": "崩溃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的生活一直很平静，每天都很开心，我却快崩溃了。", "explanation": "“崩溃”表示心里难过到受不了，与句中安稳、快乐的状态矛盾；这里应该用〈满足〉。"}, {"text": "这件事让我的信心很足，我决心一定要做好它，所以我特别崩溃。", "explanation": "“崩溃”表示难过到受不了，与句中信心十足、决心坚定的状态矛盾；这里应该用〈振奋〉。"}, {"text": "我很崩溃地帮他做完了作业。", "explanation": "“崩溃”表示情绪失控，与“认真完成任务”的状态不符；这里应该用〈认真〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "崩溃", "is_correct": true, "explanation": "“同学们都要崩溃了”指因作业太多而几近承受不住，与语境一致。"}, {"text": "振奋", "is_correct": false, "explanation": "语义：“振奋”指情绪昂扬，与“作业太多”带来的负担相反。"}, {"text": "缺氧", "is_correct": false, "explanation": "语义：“缺氧”指身体缺少氧气，与作业压力无关，不能描述群体的心理状态。"}, {"text": "发烫", "is_correct": false, "explanation": "搭配：“发烫”指身体温度升高，不说“同学们都要发烫了”来表示心理压力。"}], "explanations": {"崩溃": "“同学们都要崩溃了”指因作业太多而几近承受不住，与语境一致。", "振奋": "语义：“振奋”指情绪昂扬，与“作业太多”带来的负担相反。", "缺氧": "语义：“缺氧”指身体缺少氧气，与作业压力无关，不能描述群体的心理状态。", "发烫": "搭配：“发烫”指身体温度升高，不说“同学们都要发烫了”来表示心理压力。"}, "sentence_index": 6, "correct_answer": "崩溃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "别说了，我吃饱了，心里很平静，崩溃极了。", "explanation": "“崩溃”表示心里难过到受不了，与句中吃饱、平静的状态矛盾；这里应该用〈满足〉。"}, {"text": "别说了，我很平静，特别崩溃。", "explanation": "“崩溃”表示心里难过到受不了，与句中的平稳心态矛盾；这里应该用〈淡定〉。"}, {"text": "别说了，我今天睡得很好，精神饱满，已经快崩溃了。", "explanation": "“崩溃”表示心里难过到受不了，与句中睡得好、精神饱满的状态矛盾；这里应该用〈轻松〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到这个消息，我真的快崩溃过了。", "corrected_sentence": "听到这个消息，我真的快崩溃了。", "error_description": "“快……”表示即将发生，不能与表示已经完成的“过了”同用；正确说“快崩溃了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么多的任务堆在一起，大家都快崩溃掉了。", "corrected_sentence": "这么多的任务堆在一起，大家都快崩溃了。", "error_description": "“崩溃”后不接结果补语“掉”，应直接说“快崩溃了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
