INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27126, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一样东西连着一串东西，像瀑布一样落下来。", "primary_collocate": null, "pronunciation": "jí lián", "ipa": "tɕi˧˥ ljɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这些小水池是级联的。", "target_word": "级联", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公园里的水是级联的，一层流到一层。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个水景是级联的，很好看。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这三个盒子摆成级联的样子，一个连着一个。", "target_word": "级联", "complexity_tier": "T3", "furigana": "zhè sān gè hé zi bǎi chéng jí lián de yàng zi, yí gè lián zhe yí gè。", "sentence_source": "generated"}, {"text": "小朋友用杯子做了一个级联的小瀑布。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那些灯是级联的，一盏亮了，下一盏也亮。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的水是级联的，一层一层往下流。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最喜欢这个级联的喷泉。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套设备是级联的，水会一级一级往下落。", "target_word": "级联", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家花园里有一个级联的小水池。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "级联式", "label": "复合"}, {"form": "级联反应", "label": "复合"}, {"form": "級聯", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个连着一个、像瀑布一样一层层往下的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2009d73c-bf4e-4a49-ada1-b6ff159c7f51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27126, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "级联", "is_correct": true, "explanation": "正确。小水池一层层相连，是级联的。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：水池没有勇气，不能说“勇敢”。"}, {"text": "饥饿", "is_correct": false, "explanation": "搭配：“饥饿”多用于人或动物，不用于水池。"}, {"text": "愤怒", "is_correct": false, "explanation": "语义：水池不会有情绪，不能“愤怒”。"}], "explanations": {"级联": "正确。小水池一层层相连，是级联的。", "勇敢": "语义：水池没有勇气，不能说“勇敢”。", "饥饿": "搭配：“饥饿”多用于人或动物，不用于水池。", "愤怒": "语义：水池不会有情绪，不能“愤怒”。"}, "sentence_index": 0, "correct_answer": "级联"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老人的性格很级联，大家都喜欢他。", "explanation": "这里应该用〈温和〉。级联形容一层层相连的样子，不用来形容人的性格。"}, {"text": "这湖水很级联，平静得没有波纹。", "explanation": "用错义项：级联形容一层层往下流的水，不用来形容平静的湖面。"}, {"text": "他级联三天迟到了。", "explanation": "这里应该用〈连续〉。级联形容一层层相连的样子，不用来说重复发生的次数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "级联", "is_correct": true, "explanation": "正确。山上的水一层层往下流，形容为级联的。"}, {"text": "静止", "is_correct": false, "explanation": "语义：静止的水不会一层层往下流。"}, {"text": "干涸", "is_correct": false, "explanation": "语义：水已干涸，不能再往下流。"}, {"text": "冰冻", "is_correct": false, "explanation": "搭配：冰冻的水不能说“一层一层往下流”。"}], "explanations": {"级联": "正确。山上的水一层层往下流，形容为级联的。", "静止": "语义：静止的水不会一层层往下流。", "干涸": "语义：水已干涸，不能再往下流。", "冰冻": "搭配：冰冻的水不能说“一层一层往下流”。"}, "sentence_index": 6, "correct_answer": "级联"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头很级联，形状非常圆。", "explanation": "用错义项：级联形容层层相连的样子，不用来形容物体的形状。"}, {"text": "这块草地很级联，适合踢球。", "explanation": "这里应该用〈平坦〉。级联形容一层层相连的样子，不能用来形容地面平不平。"}, {"text": "他的成绩很级联，每次考试都排第一。", "explanation": "用错对象：级联只形容事物的排列或变化方式，不用来评价成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些小水池是级联，水一层层往下流。", "corrected_sentence": "这些小水池是级联的，水一层层往下流。", "error_description": "缺少“的”：“是”后作表语的形容词要加“的”，应为“级联的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "花园里的水池是级联地，水一层层往下落。", "corrected_sentence": "花园里的水池是级联的，水一层层往下落。", "error_description": "“地”用错：修饰“是”后的形容词应用“的”，“地”只修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8abe0830-0f59-43d0-8095-f7cd25deb8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
