INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27132, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "脆弱性就是东西很容易坏掉。", "primary_collocate": null, "pronunciation": "cuì ruò xìng", "ipa": "tsʰuei̯˥˩ ʐuo̯˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "玻璃杯的脆弱性让我们搬家时特别小心。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种陶瓷很漂亮，但是脆弱性也很明显。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为鸡蛋壳的脆弱性，我们把它放在软盒子里。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料一碰就碎，脆弱性很高。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕的脆弱性让人们都买保护壳。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古书的纸张很旧，脆弱性很高，要小心翻。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了减少脆弱性，工人把玻璃做得更厚。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员知道玻璃制品的脆弱性，所以轻拿轻放。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶翅膀的脆弱性让人不敢用手碰它。", "target_word": "脆弱性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋老房子的墙很薄，脆弱性很高。", "target_word": "脆弱性", "complexity_tier": "T3", "furigana": "zhè dòng lǎo fángzi de qiáng hěn báo, cuìruòxìng hěn gāo.", "sentence_source": "generated"}], "morphological_forms": [{"form": "脆弱", "label": "词根"}], "register": "书面", "sense_fingerprint": "具体物品一碰就碎、容易损坏的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca6241f-7cd5-4227-99f1-641110d74754') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脆弱性", "is_correct": true, "explanation": "指具体物品一碰就碎、容易损坏的特性，与“玻璃杯的……让我们小心”的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与搬家时需要特别小心没有关系，句意不通。"}, {"text": "容量", "is_correct": false, "explanation": "语义：容量大小并不要求搬家时特别小心，句意不通。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：物品说“年头”，不说“年纪”。"}], "explanations": {"脆弱性": "指具体物品一碰就碎、容易损坏的特性，与“玻璃杯的……让我们小心”的语境相符。", "颜色": "语义：颜色与搬家时需要特别小心没有关系，句意不通。", "容量": "语义：容量大小并不要求搬家时特别小心，句意不通。", "年纪": "搭配：物品说“年头”，不说“年纪”。"}, "sentence_index": 0, "correct_answer": "脆弱性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种橡胶的脆弱性很好，拉伸后能恢复原状。", "explanation": "这里应该用〈弹性〉。脆弱性指一碰就碎、容易损坏，“拉伸后能恢复原状”描述的是弹性。"}, {"text": "这双鞋的脆弱性很好，穿很久都不坏。", "explanation": "这里应该用〈耐用性〉。“穿很久都不坏”说的是耐用，脆弱性指容易损坏。"}, {"text": "这座桥的脆弱性很好，人们可以放心过桥。", "explanation": "这里应该用〈强度〉。“放心过桥”说的是强度高，脆弱性指容易碎、容易坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脆弱性", "is_correct": true, "explanation": "指玻璃一类物品容易碎的特性，与“为了减少……，把玻璃做得更厚”的语境相符。"}, {"text": "厚度", "is_correct": false, "explanation": "语义：为了减少厚度而把玻璃做得更厚，前后矛盾。"}, {"text": "重量", "is_correct": false, "explanation": "语义：做得更厚会增加重量，“减少重量”与句意冲突。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“减少”不能修饰颜色，句意不通。"}], "explanations": {"脆弱性": "指玻璃一类物品容易碎的特性，与“为了减少……，把玻璃做得更厚”的语境相符。", "厚度": "语义：为了减少厚度而把玻璃做得更厚，前后矛盾。", "重量": "语义：做得更厚会增加重量，“减少重量”与句意冲突。", "颜色": "搭配：“减少”不能修饰颜色，句意不通。"}, "sentence_index": 6, "correct_answer": "脆弱性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人的脆弱性很高，走路需要人扶。", "explanation": "这里应该用〈虚弱〉。脆弱性指物品一碰就碎的特性，形容老人身体应说〈虚弱〉。"}, {"text": "孩子的脆弱性很强，老师一句批评就哭了。", "explanation": "这里应该用〈敏感〉。脆弱性指物品容易损坏的特性，形容孩子的情绪反应应说〈敏感〉。"}, {"text": "这位选手的脆弱性很高，一输球就想放弃。", "explanation": "这里应该用〈意志薄弱〉。脆弱性指物品容易碎的特性，形容选手的心理状态应说〈意志薄弱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批鸡蛋的脆弱性高很，运输时要特别小心。", "corrected_sentence": "这批鸡蛋的脆弱性很高，运输时要特别小心。", "error_description": "错误：语序错误。程度副词“很”应放在形容词“高”前，应说“脆弱性很高”，不能说“高很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批瓷器有一只很高的脆弱性，搬运时要格外小心。", "corrected_sentence": "这批瓷器有一种很高的脆弱性，搬运时要格外小心。", "error_description": "错误：量词用错。“脆弱性”是抽象名词，应用量词“种”；“只”多用于动物或成对的物件，不能修饰抽象名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
