INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27134, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "像小鸟一样来回跑动。", "primary_collocate": null, "pronunciation": "chuān suō", "ipa": "tʂʰwan˥ swo˥", "syllable_count": 2, "sentences": [{"text": "孩子们像小鸟一样在院子里穿梭。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友在花园里穿梭，笑声不断。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个小女孩在树下穿梭着捉迷藏。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动场上，孩子们快乐地穿梭。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩在客人中穿梭，一会儿这儿一会儿那儿。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，孩子们在亲戚之间穿梭，要红包。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学生在操场上穿梭，像一群小鸟。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿园的孩子在草地上穿梭玩耍。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小姑娘在厨房和客厅之间穿梭，帮妈妈拿东西。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在花丛里穿梭，跟着蝴蝶跑。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿梭了", "label": "体标（了）"}, {"form": "穿梭着", "label": "体标（着）"}, {"form": "穿梭过", "label": "体标（过）"}, {"form": "穿梭机", "label": "复合词"}, {"form": "穿梭巴士", "label": "复合词"}], "register": "通用", "sense_fingerprint": "孩子或小动物轻快地来回跑动，像小鸟一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51a2ec1-03d3-479d-a707-0e526ca5f366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27134, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穿梭", "is_correct": true, "explanation": "正确：穿梭指像小鸟一样轻快地来回跑动，与孩子在院子里玩耍的画面相合。"}, {"text": "静坐", "is_correct": false, "explanation": "语义：静坐指安静地坐着不动，与“像小鸟一样”的轻快跑动相反。"}, {"text": "下降", "is_correct": false, "explanation": "搭配：下降多用于价格、水平或飞行器，不说孩子在院子里下降。"}, {"text": "沉睡", "is_correct": false, "explanation": "语义：沉睡指熟睡不醒，与孩子在院子里活动的画面不合。"}], "explanations": {"穿梭": "正确：穿梭指像小鸟一样轻快地来回跑动，与孩子在院子里玩耍的画面相合。", "静坐": "语义：静坐指安静地坐着不动，与“像小鸟一样”的轻快跑动相反。", "下降": "搭配：下降多用于价格、水平或飞行器，不说孩子在院子里下降。", "沉睡": "语义：沉睡指熟睡不醒，与孩子在院子里活动的画面不合。"}, "sentence_index": 0, "correct_answer": "穿梭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们静静地在教室里穿梭，认真听讲。", "explanation": "这里应该用〈静坐〉。穿梭指像小鸟一样轻快地跑动，听讲时孩子应当静坐。"}, {"text": "孩子们在门口穿梭，排队等候进场。", "explanation": "这里应该用〈站立〉。穿梭是轻快地来回跑动，排队时要站定不动，应说站立。"}, {"text": "他在草地上穿梭，一直朝一个方向走，没有回头。", "explanation": "这里应该用〈穿行〉。穿梭是来回往复地跑动，一直朝一个方向走、不回头应说穿行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿梭", "is_correct": true, "explanation": "正确：穿梭指像小鸟一样来回跑动，与“像一群小鸟”的形象相合。"}, {"text": "静立", "is_correct": false, "explanation": "语义：静立指站着不动，与“像一群小鸟”的活跃形象不合。"}, {"text": "漂浮", "is_correct": false, "explanation": "搭配：漂浮用于水面或空中，不说小学生在操场上漂浮。"}, {"text": "下沉", "is_correct": false, "explanation": "语义：下沉指向下落或沉没，与在操场上来回跑动的意思不合。"}], "explanations": {"穿梭": "正确：穿梭指像小鸟一样来回跑动，与“像一群小鸟”的形象相合。", "静立": "语义：静立指站着不动，与“像一群小鸟”的活跃形象不合。", "漂浮": "搭配：漂浮用于水面或空中，不说小学生在操场上漂浮。", "下沉": "语义：下沉指向下落或沉没，与在操场上来回跑动的意思不合。"}, "sentence_index": 6, "correct_answer": "穿梭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "木箱在院子角落穿梭，堆得整整齐齐。", "explanation": "这里应该用〈摆放〉。穿梭只说能自行来回跑动的人或动物，堆放的木箱不能用穿梭。"}, {"text": "花草在院子里穿梭，长得很高。", "explanation": "这里应该用〈生长〉。穿梭指轻快地来回跑动，植物长高应该用生长。"}, {"text": "老爷爷在树下穿梭，拄着拐杖一动不动。", "explanation": "这里应该用〈静立〉。穿梭指来回跑动，“一动不动”与之矛盾，应说静立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "放学后，孩子们在操场上很穿梭，玩得很开心。", "corrected_sentence": "放学后，孩子们在操场上穿梭，玩得很开心。", "error_description": "错误在“穿梭”前加了程度副词“很”。“穿梭”是动词，不能受“很”修饰，应去掉“很”，改为“在操场上穿梭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下课后，孩子们在走廊里被穿梭，互相追逐。", "corrected_sentence": "下课后，孩子们在走廊里穿梭，互相追逐。", "error_description": "错误形式：“被穿梭”，给不及物动词穿梭加上被字。正确形式：“在走廊里穿梭”。穿梭没有被动用法，句中不需要被。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27136, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "数学", "is_correct": false, "explanation": "无关：“数学”与“稳健性”没有反义关系。"}, {"text": "脆弱性", "is_correct": true, "explanation": "反义：“脆弱性”与“稳健性”相对，指东西容易损坏、不结实。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”与“稳健性”没有反义关系。"}, {"text": "厨房", "is_correct": false, "explanation": "无关：“厨房”与“稳健性”没有反义关系。"}], "correct_answer": "脆弱性", "explanations": {"数学": "无关：“数学”与“稳健性”没有反义关系。", "脆弱性": "反义：“脆弱性”与“稳健性”相对，指东西容易损坏、不结实。", "河流": "无关：“河流”与“稳健性”没有反义关系。", "厨房": "无关：“厨房”与“稳健性”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27136, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "钢琴", "is_correct": false, "explanation": "无关：“钢琴”与“稳健性”没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "无关：“花园”与“稳健性”没有反义关系。"}, {"text": "脆弱性", "is_correct": true, "explanation": "反义：“脆弱性”与“稳健性”相对，指东西容易损坏、不结实。"}, {"text": "海洋", "is_correct": false, "explanation": "无关：“海洋”与“稳健性”没有反义关系。"}], "correct_answer": "脆弱性", "explanations": {"钢琴": "无关：“钢琴”与“稳健性”没有反义关系。", "花园": "无关：“花园”与“稳健性”没有反义关系。", "脆弱性": "反义：“脆弱性”与“稳健性”相对，指东西容易损坏、不结实。", "海洋": "无关：“海洋”与“稳健性”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27136, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西很稳，不容易坏。", "primary_collocate": null, "pronunciation": "wěn jiàn xìng", "ipa": "wən˨˩ tɕjɛn˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这张桌子的稳健性很好，用了十年都没坏。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买登山鞋时我很看重稳健性。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个梯子的稳健性让工人放心。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的墙很厚，稳健性不错。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆自行车看起来旧，但稳健性很高。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了桌子的稳健性，他加了四条腿。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种椅子的稳健性好，小孩踩着也不会倒。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁桥的稳健性比木桥高多了。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木工师傅说，这个柜子的稳健性没问题。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他检查了架子的稳健性，才把书放上去。", "target_word": "稳健性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "稳健", "label": "词根"}], "register": "书面", "sense_fingerprint": "具体物品结实稳固、不容易损坏的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca6241f-7cd5-4227-99f1-641110d74754') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27136, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "搭配：桌子没有味道，“味道很好”不能用来形容桌子的结实程度。"}, {"text": "稳健性", "is_correct": true, "explanation": "正确。“稳健性”指东西结实、不容易坏，与“用了十年都没坏”相符。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：桌子没有脾气，“脾气很好”与句意不合。"}, {"text": "香气", "is_correct": false, "explanation": "搭配：“香气”不能用来形容桌子的结实程度。"}], "explanations": {"味道": "搭配：桌子没有味道，“味道很好”不能用来形容桌子的结实程度。", "稳健性": "正确。“稳健性”指东西结实、不容易坏，与“用了十年都没坏”相符。", "脾气": "语义：桌子没有脾气，“脾气很好”与句意不合。", "香气": "搭配：“香气”不能用来形容桌子的结实程度。"}, "sentence_index": 0, "correct_answer": "稳健性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子的稳健性很漂亮。", "explanation": "这里应该用〈外观〉。稳健性指东西结实、不易坏，评价桌子好看与否应从〈外观〉方面说。"}, {"text": "这个灯泡的稳健性很亮。", "explanation": "这里应该用〈亮度〉。稳健性指东西结实、不易坏，说灯泡的明暗应用〈亮度〉。"}, {"text": "这辆汽车的稳健性很快。", "explanation": "这里应该用〈速度〉。稳健性指东西结实、不易坏，说汽车快不快应用〈速度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色好”与“小孩踩着也不会倒”没有因果关系，句意不通。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“气味”不能用来形容椅子的结实程度。"}, {"text": "稳健性", "is_correct": true, "explanation": "正确。“稳健性好”指椅子结实，小孩踩着也不会倒，与句意相符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：椅子发出的声音好坏与“小孩踩着也不会倒”无关。"}], "explanations": {"颜色": "语义：“颜色好”与“小孩踩着也不会倒”没有因果关系，句意不通。", "气味": "搭配：“气味”不能用来形容椅子的结实程度。", "稳健性": "正确。“稳健性好”指椅子结实，小孩踩着也不会倒，与句意相符。", "声音": "语义：椅子发出的声音好坏与“小孩踩着也不会倒”无关。"}, "sentence_index": 6, "correct_answer": "稳健性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子的稳健性很温柔。", "explanation": "这里应该用〈柔软〉。稳健性指东西结实、不易损坏，形容椅子的软硬应说〈柔软〉。"}, {"text": "这条路的稳健性很长。", "explanation": "这里应该用〈长度〉。稳健性指东西牢固、不易坏，路的远近或长短应说〈长度〉。"}, {"text": "这个水杯的稳健性很便宜。", "explanation": "这里应该用〈价格〉。稳健性指东西牢固、不易坏，说水杯贵不贵应谈〈价格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把椅子的稳健性好很，坐上去很踏实。", "corrected_sentence": "这把椅子的稳健性很好，坐上去很踏实。", "error_description": "错误：“很”的位置放错了。“很”应放在形容词“好”的前面，说“稳健性很好”，不能说“稳健性好很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个书架很稳健性没问题，放很多书也不会倒。", "corrected_sentence": "这个书架的稳健性没问题，放很多书也不会倒。", "error_description": "错误：用了“很”代替“的”。“很”不能修饰名词“稳健性”，应说“书架的稳健性没问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
