INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27138, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人帮助花的花粉从一朵花飞到另一朵花上，这样花就能结出果实。", "primary_collocate": null, "pronunciation": "rén gōng shòu fěn", "ipa": "ʐən˧˥ kʊŋ˥ ʂou˥˩ fən˨˩˦", "syllable_count": 4, "sentences": [{"text": "没有蜜蜂，我们就自己给花人工授粉。", "target_word": "人工授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用小刷子给南瓜花人工授粉。", "target_word": "人工授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人工授粉就是人来帮花传花粉。", "target_word": "人工授粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早上，奶奶在阳台给番茄花人工授粉。", "target_word": "人工授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跟姐姐一起学人工授粉。", "target_word": "人工授粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小朋友第一次做人工授粉，很开心。", "target_word": "人工授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里蜜蜂少，需要人工授粉。", "target_word": "人工授粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做人工授粉时，要轻轻碰花。", "target_word": "人工授粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，老师正在给西瓜花人工授粉。", "target_word": "人工授粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人工授粉以后，花就会结果。", "target_word": "人工授粉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "人工授粉了", "label": "体标"}], "register": "中性", "sense_fingerprint": "人帮花传花粉，让花结出果实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca6241f-7cd5-4227-99f1-641110d74754') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人工授粉", "is_correct": true, "explanation": "正确：没有蜜蜂时，我们自己给花做的就是人工授粉。"}, {"text": "人工放牧", "is_correct": false, "explanation": "语义：放牧与花无关，“给花人工放牧”没有意义。"}, {"text": "人工接生", "is_correct": false, "explanation": "搭配：接生只用于人或动物，不用于花。"}, {"text": "人工授精", "is_correct": false, "explanation": "搭配：授精用于动物或人，不说给花授精。"}], "explanations": {"人工授粉": "正确：没有蜜蜂时，我们自己给花做的就是人工授粉。", "人工放牧": "语义：放牧与花无关，“给花人工放牧”没有意义。", "人工接生": "搭配：接生只用于人或动物，不用于花。", "人工授精": "搭配：授精用于动物或人，不说给花授精。"}, "sentence_index": 0, "correct_answer": "人工授粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶牛要做人工授粉，才能有小牛。", "explanation": "这里应该用〈人工授精〉。授粉只用于植物，奶牛的繁殖要用授精。"}, {"text": "我用小刷子给小狗人工授粉。", "explanation": "这里应该用〈梳理〉。授粉只用于植物，小狗是动物，没有花，不能人工授粉；给小狗梳理毛发才是这里的说法。"}, {"text": "番茄已经红了，才开始人工授粉。", "explanation": "这里应该用〈采摘〉。人工授粉是花期帮花传粉，番茄已经成熟，此时应说采摘，不能说授粉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人工授粉", "is_correct": true, "explanation": "正确：花园里蜜蜂少，需要的就是人工授粉。"}, {"text": "人工织布", "is_correct": false, "explanation": "语义：织布与花的传粉无关，无法解决蜜蜂少的问题。"}, {"text": "人工接种", "is_correct": false, "explanation": "搭配：接种多用于疫苗或菌种，不用于给花传粉。"}, {"text": "人工收割", "is_correct": false, "explanation": "语义：收割发生在果实成熟之后，与蜜蜂少的情况不符。"}], "explanations": {"人工授粉": "正确：花园里蜜蜂少，需要的就是人工授粉。", "人工织布": "语义：织布与花的传粉无关，无法解决蜜蜂少的问题。", "人工接种": "搭配：接种多用于疫苗或菌种，不用于给花传粉。", "人工收割": "语义：收割发生在果实成熟之后，与蜜蜂少的情况不符。"}, "sentence_index": 6, "correct_answer": "人工授粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "渔场常用人工授粉的方法培育鱼苗。", "explanation": "这里应该用〈人工繁殖〉。授粉只用于植物传粉，培育鱼苗不能用人工授粉。"}, {"text": "梨树还没长出花苞，就已经人工授粉了。", "explanation": "这里应该用〈修剪〉。人工授粉要在花开时帮花传粉，花苞还没长出时可以修剪，但不能说授粉。"}, {"text": "我们给一张椅子人工授粉。", "explanation": "这里应该用〈刷漆〉。人工授粉是帮植物的花传粉，椅子不是植物，应说刷漆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们昨天做了一个人工授粉。", "corrected_sentence": "我们昨天做了一次人工授粉。", "error_description": "错误：“一个人工授粉”；正确：“一次人工授粉”。人工授粉是一次动作，应使用动量词“次”，不用通用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家的西瓜花正在人工授粉过。", "corrected_sentence": "我们家的西瓜花正在人工授粉。", "error_description": "错误：“正在人工授粉过”；正确：“正在人工授粉”。“正在”表示动作进行中，“过”表示曾经有过的经历，二者不能同用，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27140, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”与“相互依存”没有反义关系。"}, {"text": "学习", "is_correct": false, "explanation": "无关：“学习”与“相互依存”没有反义关系。"}, {"text": "独立", "is_correct": true, "explanation": "反义：“独立”与“相互依存”相对，指不依靠他人、自己能够生活。"}, {"text": "购物", "is_correct": false, "explanation": "无关：“购物”与“相互依存”没有反义关系。"}], "correct_answer": "独立", "explanations": {"唱歌": "无关：“唱歌”与“相互依存”没有反义关系。", "学习": "无关：“学习”与“相互依存”没有反义关系。", "独立": "反义：“独立”与“相互依存”相对，指不依靠他人、自己能够生活。", "购物": "无关：“购物”与“相互依存”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27140, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "写字", "is_correct": false, "explanation": "无关：“写字”与“相互依存”没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "无关：“画画”与“相互依存”没有反义关系。"}, {"text": "独立", "is_correct": true, "explanation": "反义：“独立”与“相互依存”相对，指不依靠他人、自主生活。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：“睡觉”与“相互依存”没有反义关系。"}], "correct_answer": "独立", "explanations": {"写字": "无关：“写字”与“相互依存”没有反义关系。", "画画": "无关：“画画”与“相互依存”没有反义关系。", "独立": "反义：“独立”与“相互依存”相对，指不依靠他人、自主生活。", "睡觉": "无关：“睡觉”与“相互依存”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27140, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "你靠我，我靠你，谁也离不开谁。", "primary_collocate": null, "pronunciation": "xiāng hù yī cún", "ipa": "ɕjɑŋ˥ xu˥˩ i˥ tsʰuən˧˥", "syllable_count": 4, "sentences": [{"text": "夫妻俩多年来相互依存，生活很幸福。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟两个相互依存，谁也不想分开。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在山区，村民和邻居们相互依存。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鱼和海草相互依存，少了谁都不行。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是好朋友，在陌生的城市里相互依存。", "target_word": "相互依存", "complexity_tier": "T3", "furigana": "wǒ men shì hǎo péng you, zài mò shēng de chéng shì lǐ xiāng hù yī cún.", "sentence_source": "generated"}, {"text": "老两口住在小村里，相互依存了三十年。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孤儿院的孩子们相互依存，像一家人。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对姐妹从小相互依存，感情特别深。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬到新城市后，我们三个人相互依存。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个公司在产业链上相互依存，缺一不可。", "target_word": "相互依存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "人与人之间你靠我、我靠你，谁也离不开谁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca6241f-7cd5-4227-99f1-641110d74754') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相互攻击", "is_correct": false, "explanation": "语义：“攻击”与“生活很幸福”相悖，夫妻之间相互攻击不合句意。"}, {"text": "相互依存", "is_correct": true, "explanation": "正确。夫妻俩你靠我、我靠你，与“多年来”和“生活很幸福”的语境相符。"}, {"text": "相互收养", "is_correct": false, "explanation": "搭配：“收养”指领养他人的子女，不能说夫妻之间相互收养。"}, {"text": "相互凑合", "is_correct": false, "explanation": "语域：“凑合”是口语，含将就之意，与书面的“生活很幸福”不合。"}], "explanations": {"相互攻击": "语义：“攻击”与“生活很幸福”相悖，夫妻之间相互攻击不合句意。", "相互依存": "正确。夫妻俩你靠我、我靠你，与“多年来”和“生活很幸福”的语境相符。", "相互收养": "搭配：“收养”指领养他人的子女，不能说夫妻之间相互收养。", "相互凑合": "语域：“凑合”是口语，含将就之意，与书面的“生活很幸福”不合。"}, "sentence_index": 0, "correct_answer": "相互依存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两位邻居相互依存，却互不认识。", "explanation": "这里应该用〈陌生〉。相互依存强调关系密切、彼此离不开，互不认识说明彼此陌生，应说〈陌生〉。"}, {"text": "两位作家相互依存，常年不来往。", "explanation": "这里应该用〈疏远〉。相互依存强调彼此离不开、关系密切，两位作家常年不来往，是关系疏远，应说〈疏远〉。"}, {"text": "两家店铺相互依存，却毫不往来，各做各的生意。", "explanation": "这里应该用〈独立〉。相互依存强调彼此离不开，两家店铺毫不往来、各做各的生意，应说〈独立〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相互欺负", "is_correct": false, "explanation": "语义：“欺负”与“像一家人”的温暖关系相悖。"}, {"text": "相互依存", "is_correct": true, "explanation": "正确。孤儿院的孩子们彼此依靠、缺一不可，与“像一家人”相符。"}, {"text": "相互辞职", "is_correct": false, "explanation": "搭配：“辞职”是个人离开工作的行为，不能说孩子们之间相互辞职。"}, {"text": "相互推诿", "is_correct": false, "explanation": "语义：“推诿”是互相推卸责任，与“像一家人”的温情不符。"}], "explanations": {"相互欺负": "语义：“欺负”与“像一家人”的温暖关系相悖。", "相互依存": "正确。孤儿院的孩子们彼此依靠、缺一不可，与“像一家人”相符。", "相互辞职": "搭配：“辞职”是个人离开工作的行为，不能说孩子们之间相互辞职。", "相互推诿": "语义：“推诿”是互相推卸责任，与“像一家人”的温情不符。"}, "sentence_index": 6, "correct_answer": "相互依存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同事们相互依存，各自为政，谁也不管谁。", "explanation": "这里应该用〈独立〉。相互依存强调彼此离不开，同事们各自为政、谁也不管谁，是各自独立，应说〈独立〉。"}, {"text": "他一个人相互依存，过得很好。", "explanation": "这里应该用〈独立〉。“相互”需要两方或多方彼此依靠，只有一个人时不能说相互依存，应说独立。"}, {"text": "两人为小事相互依存。", "explanation": "这里应该用〈争吵〉。相互依存指彼此离不开，为小事起争执应说〈争吵〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个小镇相互依存很紧，谁也离不开谁。", "corrected_sentence": "这两个小镇相互依存得很紧，谁也离不开谁。", "error_description": "错误：漏了“得”。“依存”后面带程度补语时要用“得”，应说“相互依存得很紧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄弟俩之间是相互依存地关系。", "corrected_sentence": "兄弟俩之间是相互依存的关系。", "error_description": "错误：“地”应为“的”。“地”修饰动词，而“相互依存的关系”中的“的”修饰名词“关系”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
