INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27142, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "花谢了，小果子开始长出来。", "primary_collocate": null, "pronunciation": "zuò guǒ", "ipa": "tswo˥˩ kwo˨˩˦", "syllable_count": 2, "sentences": [{"text": "桃花谢了以后，树上开始坐果了。", "target_word": "坐果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天花开，夏天坐果，秋天丰收。", "target_word": "坐果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花谢了，几天后枝上就坐果了。", "target_word": "坐果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，那棵梨树已经坐果了。", "target_word": "坐果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小草莓刚刚坐果，还是绿色的。", "target_word": "坐果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这朵黄瓜花谢了，马上就要坐果。", "target_word": "坐果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷说，花谢后一个月会坐果。", "target_word": "坐果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈阳台上的西红柿终于坐果了。", "target_word": "坐果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杏树花开得早，坐果也早。", "target_word": "坐果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树枝上刚坐果，小果子只有豆子大。", "target_word": "坐果", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坐果了", "label": "体标"}, {"form": "坐果率", "label": "复合"}], "register": "中性", "sense_fingerprint": "花谢后小果子开始长出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca6241f-7cd5-4227-99f1-641110d74754') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27142, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "坐果", "is_correct": true, "explanation": "正确答案：坐果，花谢后小果子开始长出来。"}, {"text": "坐骨", "is_correct": false, "explanation": "gǔ（第三声）与 guǒ（第三声）韵母不同：u 与 o。坐骨意思是骨盆下部的骨头。"}, {"text": "做过", "is_correct": false, "explanation": "guò（第四声）与 guǒ（第三声）声调不同，做过意思是做过某件事。"}, {"text": "坐过", "is_correct": false, "explanation": "guò（第四声）与 guǒ（第三声）声调不同，坐过意思是曾经坐过某物。"}], "explanations": {"坐果": "正确答案：坐果，花谢后小果子开始长出来。", "坐骨": "gǔ（第三声）与 guǒ（第三声）韵母不同：u 与 o。坐骨意思是骨盆下部的骨头。", "做过": "guò（第四声）与 guǒ（第三声）声调不同，做过意思是做过某件事。", "坐过": "guò（第四声）与 guǒ（第三声）声调不同，坐过意思是曾经坐过某物。"}, "sentence_index": null, "correct_answer": "坐果"}, "level_3": {"options": [{"text": "坐果", "is_correct": true, "explanation": "正确：花谢以后树上开始长出小果子，即坐果。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：树不会唱歌，“树上开始唱歌了”没有意义。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：树不会睡觉，与花谢后的变化无关。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：植物不说“出生”，只有人和动物说出生。"}], "explanations": {"坐果": "正确：花谢以后树上开始长出小果子，即坐果。", "唱歌": "语义：树不会唱歌，“树上开始唱歌了”没有意义。", "睡觉": "语义：树不会睡觉，与花谢后的变化无关。", "出生": "搭配：植物不说“出生”，只有人和动物说出生。"}, "sentence_index": 0, "correct_answer": "坐果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那几个小梨已经坐果了，可以摘下来吃了。", "explanation": "这里应该用〈成熟〉。坐果是花谢后果实刚开始长出，还很小，不能说可以吃；果子成熟了才能吃。"}, {"text": "我家的小狗已经坐果了。", "explanation": "这里应该用〈生〉。坐果只用于植物，指花谢后子房发育成果实；动物繁殖说“生”，不能说坐果。"}, {"text": "这些梨摘下来以后，又坐果了。", "explanation": "这里应该用〈长大〉。坐果指果实刚开始形成，摘下来的梨已经长成，不会再坐果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坐果", "is_correct": true, "explanation": "正确：花谢后一个月，树上会长出小果子，即坐果。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：花不会跳舞，“花谢后一个月会跳舞”没有意义。"}, {"text": "退休", "is_correct": false, "explanation": "语义：花不会退休，与花谢后的变化无关。"}, {"text": "出嫁", "is_correct": false, "explanation": "搭配：“出嫁”只用于女子，不用于植物。"}], "explanations": {"坐果": "正确：花谢后一个月，树上会长出小果子，即坐果。", "跳舞": "语义：花不会跳舞，“花谢后一个月会跳舞”没有意义。", "退休": "语义：花不会退休，与花谢后的变化无关。", "出嫁": "搭配：“出嫁”只用于女子，不用于植物。"}, "sentence_index": 6, "correct_answer": "坐果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的坐果很好。", "explanation": "这里应该用〈结果〉。坐果只指植物花谢后果实开始形成，不能用来说比赛的结果。"}, {"text": "花还没开，树上就已经坐果了。", "explanation": "这里应该用〈形成〉。坐果指花谢后果实开始形成，花还没开时不能说坐果。"}, {"text": "这块石头今年坐果了。", "explanation": "这里应该用〈长出〉。坐果只用于植物，指花谢后果实开始形成；石头没有花，不能说坐果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桃花谢后，树上坐果着。", "corrected_sentence": "桃花谢后，树上坐果了。", "error_description": "错误：“坐果着”；正确：“坐果了”。坐果表示果实已经开始形成，要用“了”，不用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "树枝上刚开始被坐果，小果子只有豆子大。", "corrected_sentence": "树枝上刚开始坐果，小果子只有豆子大。", "error_description": "错误：“被坐果”；正确：“坐果”。坐果是不及物动词，不能用“被”构成被动句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
