INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "家里要花的钱太多了。", "primary_collocate": null, "pronunciation": "jīng jì fù dān", "ipa": "tɕiŋ˥ tɕi˥˩ fu˥˩ tan˥", "syllable_count": 4, "sentences": [{"text": "家里有三个孩子，经济负担很大。", "target_word": "经济负担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸生病了，我们家的经济负担很重。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想早点工作，减轻家里的经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买车对我们来说是一个经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房租太贵，成了我的经济负担。", "target_word": "经济负担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈不想给孩子增加经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学费这么高，对农村家庭是经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有了工作，家里的经济负担小多了。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个月还房贷，给我们带来经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶住院的钱，是全家的经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "口语", "sense_fingerprint": "家里要花的钱太多，压力很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca6241f-7cd5-4227-99f1-641110d74754') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经济负担", "is_correct": true, "explanation": "指家里花钱太多带来的压力，与“很大”搭配，符合句意。"}, {"text": "口音", "is_correct": false, "explanation": "语义：“口音”与“家里有三个孩子”无关，句意不通。"}, {"text": "学习成绩", "is_correct": false, "explanation": "搭配：成绩说“好”或“高”，不说“很大”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：形容身高用“高”，不用“大”，句子不通。"}], "explanations": {"经济负担": "指家里花钱太多带来的压力，与“很大”搭配，符合句意。", "口音": "语义：“口音”与“家里有三个孩子”无关，句意不通。", "学习成绩": "搭配：成绩说“好”或“高”，不说“很大”。", "身高": "体貌：形容身高用“高”，不用“大”，句子不通。"}, "sentence_index": 0, "correct_answer": "经济负担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "社区为困难家庭提供了很大的经济负担。", "explanation": "这里应该用〈经济帮助〉。经济负担指家庭要承担的金钱压力，不能“提供”给别人；给予金钱帮助要说经济帮助。"}, {"text": "公司给优秀员工发放了很多经济负担。", "explanation": "这里应该用〈经济奖励〉。“发放”的是奖金、奖励，经济负担是压力，不能发放。"}, {"text": "这次创作让他获得了不少经济负担。", "explanation": "这里应该用〈经济收入〉。“获得”搭配收入，经济负担是需要承担的压力，不能获得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济负担", "is_correct": true, "explanation": "指家庭承受的金钱压力，与“对农村家庭是”搭配，符合句意。"}, {"text": "教育机会", "is_correct": false, "explanation": "语义：学费高是负担，不会是教育机会，句意相反。"}, {"text": "经济优势", "is_correct": false, "explanation": "语义：学费很高不会给家庭带来经济优势，句意相反。"}, {"text": "生财之道", "is_correct": false, "explanation": "语域：“生财之道”是书面成语，与口语句“学费这么高”不协调；且学费高不是致富的途径。"}], "explanations": {"经济负担": "指家庭承受的金钱压力，与“对农村家庭是”搭配，符合句意。", "教育机会": "语义：学费高是负担，不会是教育机会，句意相反。", "经济优势": "语义：学费很高不会给家庭带来经济优势，句意相反。", "生财之道": "语域：“生财之道”是书面成语，与口语句“学费这么高”不协调；且学费高不是致富的途径。"}, "sentence_index": 6, "correct_answer": "经济负担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一直为他承担着一条经济负担。", "explanation": "这里应该用〈种〉。“条”用于细长的东西，不能修饰抽象的经济负担。"}, {"text": "这次意外让家里多了一把经济负担。", "explanation": "这里应该用〈种〉。“把”用于有柄的器具，不能用于经济负担。"}, {"text": "孩子的教育费用是我家的一只经济负担。", "explanation": "这里应该用〈种〉。“只”用于动物等，不用于抽象名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔医药费对我们家来说是很大的经济负担们。", "corrected_sentence": "这笔医药费对我们家来说是很大的经济负担。", "error_description": "错误：“经济负担”后加了“们”；“们”只用于指人的名词，不能用在“经济负担”后。正确：去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学费这么高，对我们家来说确实是一把沉重的经济负担。", "corrected_sentence": "学费这么高，对我们家来说确实是一种沉重的经济负担。", "error_description": "“经济负担”的量词应为“种”；“把”用于有柄的器具，不能修饰这个抽象名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9637fa6e-afec-4d71-ac99-d8da950ec2ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
