INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27150, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "本来就这样，不是从别处来的。", "primary_collocate": null, "pronunciation": "yuán shēng", "ipa": "ɥɛn˧˥ ʂɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "这种竹子是中国原生的。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的原生鱼和外来鱼不一样。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原生的花草不需要太多水。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护原生的小树林。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟是原生的，不是从外地引进的。", "target_word": "原生", "complexity_tier": "T3", "furigana": "zhè zhǒng niǎo shì yuán shēng de, bú shì cóng wài dì yǐn jìn de.", "sentence_source": "generated"}, {"text": "山上的原生草很高。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛上的动物都是原生的，没有一只是从外地来的。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这棵树是原生的吗？", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外来的草多了，原生的草就少了。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢在原生的森林里走路。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原生植物", "label": "复合"}, {"form": "原生态", "label": "复合"}], "register": "书面", "sense_fingerprint": "本来如此、非外来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51a2ec1-03d3-479d-a707-0e526ca5f366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27150, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原生", "is_correct": true, "explanation": "正确：句子说竹子在中国本来就有、不是从外地来的，“中国原生的”正合语境。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：陌生指不熟悉，与竹子“原本产于中国”的来源描述不符。"}, {"text": "新鲜", "is_correct": false, "explanation": "搭配：新鲜用来形容食物或空气，不能用来说明竹子的产地。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：雪白描述颜色，与“是中国……的”所说的来源无关，句子意思不通。"}], "explanations": {"原生": "正确：句子说竹子在中国本来就有、不是从外地来的，“中国原生的”正合语境。", "陌生": "语义：陌生指不熟悉，与竹子“原本产于中国”的来源描述不符。", "新鲜": "搭配：新鲜用来形容食物或空气，不能用来说明竹子的产地。", "雪白": "语义：雪白描述颜色，与“是中国……的”所说的来源无关，句子意思不通。"}, "sentence_index": 0, "correct_answer": "原生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱是原生的，是工厂里生产出来的。", "explanation": "这里应该用〈原装〉。“原生”指本来就这样、不是后来造出来的，工厂生产的冰箱应说“原装”。"}, {"text": "这种植物是原生的，是十年前从国外引进的。", "explanation": "这里应该用〈外来〉。“原生”指本来就这样、不是从别处来的，从国外引进的植物应说“外来”。"}, {"text": "这个品种是科学家原生培育出来的。", "explanation": "这里应该用〈人工〉。这个品种是科学家人为培育的，“原生”指本来就这样、不是人为造出来的，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原生", "is_correct": true, "explanation": "正确：句子说岛上动物都没有从外地来，“都是原生的”正合语境。"}, {"text": "外来", "is_correct": false, "explanation": "语义：后半句说“没有一只是从外地来的”，填“外来”则“都是外来的”与之矛盾。"}, {"text": "荒凉", "is_correct": false, "explanation": "语义：荒凉指环境冷清，不能用来形容动物的归属，句子意思不通。"}, {"text": "幼稚", "is_correct": false, "explanation": "搭配：幼稚多用来形容人的想法或行为，不能用来修饰动物。"}], "explanations": {"原生": "正确：句子说岛上动物都没有从外地来，“都是原生的”正合语境。", "外来": "语义：后半句说“没有一只是从外地来的”，填“外来”则“都是外来的”与之矛盾。", "荒凉": "语义：荒凉指环境冷清，不能用来形容动物的归属，句子意思不通。", "幼稚": "搭配：幼稚多用来形容人的想法或行为，不能用来修饰动物。"}, "sentence_index": 6, "correct_answer": "原生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥是原生建的。", "explanation": "这里应该用〈新建〉。桥是人建造的，“原生”指非人工的本来状态，不能用于建造。"}, {"text": "这盏灯是原生的，是他自己焊接出来的。", "explanation": "这里应该用〈自制〉。“原生”指本来就这样、不是后来做出来的，自己焊的灯应说“自制”。"}, {"text": "这辆车是原生的，是他刚花钱改造的。", "explanation": "这里应该用〈改装〉。车是他花钱改造过的，“原生”指本来就这样、没人动过，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种花是被中国原生的。", "corrected_sentence": "这种花是中国原生的。", "error_description": "错误形式：“是被中国原生的”；正确形式：“是中国原生的”。“原生”是描述本来状态的词，不能用“被”构成被动式，应去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家附近有一片原生了的小树林。", "corrected_sentence": "我家附近有一片原生的小树林。", "error_description": "错误在“原生”后多加了“了”。“原生”作修饰语时不能带“了”，应改为“我家附近有一片原生的小树林”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27152, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27152, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27152, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "把几个数加起来，再除以它们的个数，得到的结果。", "primary_collocate": null, "pronunciation": "píng jūn", "ipa": "pʰiŋ˧˥ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "三、五、七的平均是五。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这四个数的平均是多少？", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把我们的分数算出了平均。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "求平均要先把数字加起来。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天温度的平均是二十度。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三次数学考试的平均是九十分。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你来算一下这五个数的平均吧。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八和十二的平均是十。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这些数加起来再除，就得到了平均。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这组数的平均是六，不是七。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平均数", "label": "复合词"}, {"form": "平均值", "label": "复合词"}, {"form": "平均分", "label": "复合词"}], "register": "通用", "sense_fingerprint": "几个数相加再除以个数所得的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51a2ec1-03d3-479d-a707-0e526ca5f366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平均", "is_correct": true, "explanation": "平均指这三个数相加后除以个数所得的结果，与“是五”相符。"}, {"text": "和", "is_correct": false, "explanation": "语义：“和”指相加的总数，三、五、七的和是十五，不是五。"}, {"text": "最大值", "is_correct": false, "explanation": "语义：三、五、七的最大值是七，不是五。"}, {"text": "平方", "is_correct": false, "explanation": "搭配：“平方”只作用于单个数，不能对三、五、七整体使用。"}], "explanations": {"平均": "平均指这三个数相加后除以个数所得的结果，与“是五”相符。", "和": "语义：“和”指相加的总数，三、五、七的和是十五，不是五。", "最大值": "语义：三、五、七的最大值是七，不是五。", "平方": "搭配：“平方”只作用于单个数，不能对三、五、七整体使用。"}, "sentence_index": 0, "correct_answer": "平均"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他算出了一块平均。", "explanation": "这里应该用〈个〉。量词“块”用于块状的东西，不能用于“平均”这样抽象的结果。"}, {"text": "这次比赛的平均是他。", "explanation": "“平均”指算出的数值结果，不能指人，这里说的是人，应该说“第一名”。"}, {"text": "老师递给我一道平均。", "explanation": "这里应该用〈个〉。道用于题目、菜肴等，平均这样的数值结果不能用“道”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平均", "is_correct": true, "explanation": "平均是对这五个数算出来的结果，与“算一下”相符。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是可以计算的数值，句意不通。"}, {"text": "字母", "is_correct": false, "explanation": "语义：“字母”不能用“算”来求得，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“算”后面不能接“颜色”这类不可计算的名词。"}], "explanations": {"平均": "平均是对这五个数算出来的结果，与“算一下”相符。", "名字": "语义：“名字”不是可以计算的数值，句意不通。", "字母": "语义：“字母”不能用“算”来求得，句意不通。", "颜色": "搭配：“算”后面不能接“颜色”这类不可计算的名词。"}, "sentence_index": 6, "correct_answer": "平均"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头的平均很重。", "explanation": "这里应该用〈分量〉。平均要对一组数求得，单独一块石头的数值不能说“平均”。"}, {"text": "他的平均是十二岁，比我大。", "explanation": "这里应该用〈年龄〉。平均要对一组数求得，单独一个人的数值不能说“平均”。"}, {"text": "我们把这些平均加起来算了。", "explanation": "“平均”是算完的结果，不能再当作被加的数字，应先把数字加起来再求平均。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这三个数的平均了是六。", "corrected_sentence": "这三个数的平均是六。", "error_description": "错误形式：“平均了”；正确形式：“平均”。“平均”作名词表示计算结果时不能带动态助词“了”，应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这五个数的平均了十。", "corrected_sentence": "这五个数的平均是十。", "error_description": "错误字：“了”应为“是”。“平均”作主语，后接判断动词“是”，不能用动态助词“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
