INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27154, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "所有都死光了，再也没有了。", "primary_collocate": null, "pronunciation": "miè jué", "ipa": "mjɛ˥˩ tɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这个岛上的鸟全都灭绝了。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林着火后，那里的蛇灭绝了。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，这种鱼两百年前就灭绝了。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多动物因为天气变冷而灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家担心这种花会灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种动物早就灭绝了，我们只能在博物馆里看到它。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球上有过很多灭绝的动物。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道渡渡鸟为什么灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种青蛙快要灭绝了，大家要小心。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护小动物，不让它们灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灭绝了", "label": "体标"}, {"form": "灭绝过", "label": "体标"}], "register": "书面", "sense_fingerprint": "全部死光再也没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51a2ec1-03d3-479d-a707-0e526ca5f366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27154, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灭绝", "is_correct": true, "explanation": "正确：句子说这个岛上的鸟全部死光了，“灭绝了”正符合“全都”的语境。"}, {"text": "上学", "is_correct": false, "explanation": "语义：鸟不会上学，“全都上学了”与岛上的情况完全不符。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：鸟不会毕业，“全都毕业了”说的事情与鸟类无关。"}, {"text": "考试", "is_correct": false, "explanation": "配价：考试需要能参加考试的人，鸟不能作为“考试”的主体，句子说不通。"}], "explanations": {"灭绝": "正确：句子说这个岛上的鸟全部死光了，“灭绝了”正符合“全都”的语境。", "上学": "语义：鸟不会上学，“全都上学了”与岛上的情况完全不符。", "毕业": "语义：鸟不会毕业，“全都毕业了”说的事情与鸟类无关。", "考试": "配价：考试需要能参加考试的人，鸟不能作为“考试”的主体，句子说不通。"}, "sentence_index": 0, "correct_answer": "灭绝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨停后，天上的云全都灭绝了。", "explanation": "这里应该用〈消散〉。云气散开应说“消散”，“灭绝”指生物全部死光，不能用于云。"}, {"text": "他生病了，在家灭绝了一个星期。", "explanation": "这里应该用〈休息〉。在家养病一段时间应说“休息”，“灭绝”指全部死光，不能用于一个人的休养。"}, {"text": "战争时兄弟俩灭绝了，几十年后才重逢。", "explanation": "这里应该用〈失散〉。兄弟在战乱中分开应说“失散”，“灭绝”指全部死光、再也没有了，不能用于人暂时分开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灭绝", "is_correct": true, "explanation": "正确：这里说的是地球上过去的动物，“灭绝的动物”指已经不存在的种类。"}, {"text": "现存", "is_correct": false, "explanation": "语义：现存指当下仍然存在，与“地球上有过”所指的过去时间相矛盾。"}, {"text": "当代", "is_correct": false, "explanation": "语义：当代指现在这个时代，与“有过”所表示的过去相冲突。"}, {"text": "现有", "is_correct": false, "explanation": "搭配：“有过”表示过去，“现有”表示当下，二者不能在同一句中搭配。"}], "explanations": {"灭绝": "正确：这里说的是地球上过去的动物，“灭绝的动物”指已经不存在的种类。", "现存": "语义：现存指当下仍然存在，与“地球上有过”所指的过去时间相矛盾。", "当代": "语义：当代指现在这个时代，与“有过”所表示的过去相冲突。", "现有": "搭配：“有过”表示过去，“现有”表示当下，二者不能在同一句中搭配。"}, "sentence_index": 6, "correct_answer": "灭绝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小偷见到警察，马上灭绝了。", "explanation": "这里应该用〈逃跑〉。小偷逃走应说“逃跑”，“灭绝”指种类全部死光，不能用于人的逃走。"}, {"text": "太阳落山后，天边的晚霞慢慢灭绝了。", "explanation": "这里应该用〈消失〉。晚霞慢慢散去应说“消失”，“灭绝”只指生物全部死光，不能用于景象。"}, {"text": "夏天到了，温度不停地灭绝。", "explanation": "这里应该用〈升高〉。温度上升应说“升高”，“灭绝”不能用于温度这类数值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那种蛇已经很灭绝了。", "corrected_sentence": "那种蛇已经灭绝了。", "error_description": "错误在“灭绝”前多加了程度副词“很”。“灭绝”是动词，不能受“很”修饰，应改为“那种蛇已经灭绝了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种鸟灭绝了了。", "corrected_sentence": "这种鸟灭绝了。", "error_description": "错误在“灭绝”后的“了”重复了一次。动词后只需一个“了”，应改为“这种鸟灭绝了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '651f6b1f-0ef2-438d-814b-46780d908167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27156, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27156, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27156, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "毒性是指某种东西能让人或动物生病或死去的能力，比如老鼠药有毒性。", "primary_collocate": null, "pronunciation": "dú xìng", "ipa": "tu˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老鼠药有毒性，孩子不能碰。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种草有毒性，牛不吃它。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毒性越大，越危险。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种蘑菇的毒性很强。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说这瓶水有毒性，不能喝。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛇的毒性可以让人生病。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种花的毒性不大，但是别吃。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生检测了这种药的毒性，结果显示很低。", "target_word": "毒性", "complexity_tier": "T3", "furigana": "yī shēng jiǎn cè le zhè zhǒng yào de dú xìng, jié guǒ xiǎn shì hěn dī.", "sentence_source": "generated"}, {"text": "这种虫子没有毒性，别害怕。", "target_word": "毒性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗吃了有毒性的东西，生病了。", "target_word": "毒性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "毒性反应", "label": "复合"}, {"form": "毒性物质", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西能让人或动物生病或死去的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16167f6b-a703-4ef3-812d-318e93e86d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27156, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毒性", "is_correct": true, "explanation": "正确。“老鼠药有毒性”指它能伤害人或动物，与“孩子不能碰”相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与“孩子不能碰”所强调的危险无关，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”只用于生物，不用于老鼠药这类物品。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重与危险性无关，句中强调的是老鼠药的危害。"}], "explanations": {"毒性": "正确。“老鼠药有毒性”指它能伤害人或动物，与“孩子不能碰”相符。", "价格": "语义：价格与“孩子不能碰”所强调的危险无关，句意不通。", "年龄": "搭配：“年龄”只用于生物，不用于老鼠药这类物品。", "体重": "语义：体重与危险性无关，句中强调的是老鼠药的危害。"}, "sentence_index": 0, "correct_answer": "毒性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子误喝了毒性，被送进了医院。", "explanation": "这里应该用〈毒药〉。毒性是性质，不能被喝下，说“喝了毒药”。"}, {"text": "这块毒性很大，别碰它。", "explanation": "量词错误：〈块〉用于块状物，毒性是抽象性质，不能用量词“块”计量。"}, {"text": "他的毒性很大，总是欺负同学。", "explanation": "语义：毒性指物质对生物的损害性质，不用来形容人的性格，形容人应说“恶毒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毒性", "is_correct": true, "explanation": "正确。“这种花的毒性不大，但是别吃”指花对人的损害性质，句中转折与“别吃”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色一般说“深”或“浅”，不说“颜色不大”。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：名字不用“大小”来形容，“名字不大”说不通。"}, {"text": "长相", "is_correct": false, "explanation": "语义：长相与“别吃”的提醒无关，句中转折说的是危险性。"}], "explanations": {"毒性": "正确。“这种花的毒性不大，但是别吃”指花对人的损害性质，句中转折与“别吃”相符。", "颜色": "搭配：颜色一般说“深”或“浅”，不说“颜色不大”。", "名字": "搭配：名字不用“大小”来形容，“名字不大”说不通。", "长相": "语义：长相与“别吃”的提醒无关，句中转折说的是危险性。"}, "sentence_index": 6, "correct_answer": "毒性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他染上了毒性，戒不掉了。", "explanation": "这里应该用〈毒瘾〉。毒性是物质的损害性质，不能被染上，应说“染上毒瘾”。"}, {"text": "这粒毒性很低，可以放心吃。", "explanation": "量词错误：〈粒〉用于颗粒，毒性是抽象性质，不能用量词“粒”计量。"}, {"text": "工厂排出的毒性污染了河水。", "explanation": "这里应该用〈毒物〉。毒性是性质，不能被排放，排放的是毒物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种草有一棵毒性，牛最好别吃。", "corrected_sentence": "这种草有一定的毒性，牛最好别吃。", "error_description": "量词错误：“棵”用于植物，“毒性”是抽象名词，不能用“棵”计量，应说“一定的毒性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生说这种花有一片毒性。", "corrected_sentence": "医生说这种花有一定的毒性。", "error_description": "量词错误：“片”用于面状的东西，“毒性”是抽象名词，不能用“片”计量，应说“一定的毒性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
