INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "农场主就是种地、养动物的人，他管理着一个大农场。", "primary_collocate": null, "pronunciation": "nóng chǎng zhǔ", "ipa": "nʊŋ˧˥ tʂʰɑŋ˨˩ tʂu˨˩", "syllable_count": 3, "sentences": [{"text": "农场主有一个很大的农场。", "target_word": "农场主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农场主每天都给牛喂草。", "target_word": "农场主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的朋友是农场主，他家有很多羊。", "target_word": "农场主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农场主在地里种了玉米。", "target_word": "农场主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农场主的狗跟着他走来走去。", "target_word": "农场主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位农场主很忙，早上五点就起床。", "target_word": "农场主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去农场玩，农场主请我们喝牛奶。", "target_word": "农场主", "complexity_tier": "T3", "furigana": "nóng chǎng zhǔ", "sentence_source": "generated"}, {"text": "农场主说，今年的苹果很甜。", "target_word": "农场主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农场主开着车去镇上买东西。", "target_word": "农场主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场主养了鸡、鸭和马。", "target_word": "农场主", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "种地养动物、管理大农场的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16167f6b-a703-4ef3-812d-318e93e86d9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农场主", "is_correct": true, "explanation": "农场主就是管理大农场的人，正符合“有一个很大的农场”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头无生命，不能拥有农场。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器不能拥有农场。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“有”的主语应是人或机构，“教室”不能与“有一个很大的农场”搭配。"}], "explanations": {"农场主": "农场主就是管理大农场的人，正符合“有一个很大的农场”。", "石头": "语义：石头无生命，不能拥有农场。", "机器": "语义：机器不能拥有农场。", "教室": "搭配：“有”的主语应是人或机构，“教室”不能与“有一个很大的农场”搭配。"}, "sentence_index": 0, "correct_answer": "农场主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是农场主，每天在医院给病人看病。", "explanation": "这里应该用〈医生〉。“农场主”指经营农场的人，给病人看病的是“医生”。"}, {"text": "这家饭店的农场主很有经验，客人越来越多。", "explanation": "这里应该用〈老板〉。“农场主”只指经营农场的人，饭店的经营者应称“老板”。"}, {"text": "他是这家纺织厂的农场主，管理着两千多名工人。", "explanation": "这里应该用〈厂长〉。“农场主”只指经营农场的人，不能用于纺织厂的管理者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "农场主", "is_correct": true, "explanation": "农场主是农场的主人，可以请客人喝自家的牛奶。"}, {"text": "牛", "is_correct": false, "explanation": "语义：牛不能请客。"}, {"text": "拖拉机", "is_correct": false, "explanation": "语义：拖拉机是机器，不能请人喝牛奶。"}, {"text": "草地", "is_correct": false, "explanation": "语义：草地是地面，不会请人喝牛奶。"}], "explanations": {"农场主": "农场主是农场的主人，可以请客人喝自家的牛奶。", "牛": "语义：牛不能请客。", "拖拉机": "语义：拖拉机是机器，不能请人喝牛奶。", "草地": "语义：草地是地面，不会请人喝牛奶。"}, "sentence_index": 6, "correct_answer": "农场主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是农场主，每天在学校里教孩子们画画。", "explanation": "这里应该用〈老师〉。“农场主”指经营农场的人，在学校教孩子画画的是“老师”。"}, {"text": "他是农场主，每天在工地上搬砖，挣钱养家。", "explanation": "这里应该用〈搬运工〉。“农场主”指经营农场的人，在工地上搬砖的是“搬运工”。"}, {"text": "他是农场主，每个月从别人那里领工资，负责给牛挤奶。", "explanation": "这里应该用〈雇工〉。“农场主”是自己拥有并经营农场的人，靠工资给别人干活的是“雇工”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村有两农场主，他们很熟。", "corrected_sentence": "我们村有两位农场主，他们很熟。", "error_description": "数量词后缺少量词：“两”加指人的名词要有量词，应说“两位农场主”，不能说“两农场主”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位农场主孩子在城里读书。", "corrected_sentence": "这位农场主的孩子在城里读书。", "error_description": "漏掉“的”：“农场主的孩子”表示所属关系，定语与中心语之间要用“的”，不能说“农场主孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4610cc2-327e-40d3-b231-79215f5cf940') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
