INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们通过看、想和做实验来学习新知识。", "primary_collocate": null, "pronunciation": "kē xué yán jiū", "ipa": "kʰɤ˥ ɕɥɛ˧˥ jɛn˧˥ tɕjoʊ˥", "syllable_count": 4, "sentences": [{"text": "科学研究就是用实验学习新知识。", "target_word": "科学研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥在大学做科学研究。", "target_word": "科学研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学研究常常要做很多实验。", "target_word": "科学研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对科学研究很感兴趣。", "target_word": "科学研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做科学研究要有耐心。", "target_word": "科学研究", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个实验室专门做科学研究。", "target_word": "科学研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学研究让人们知道了很多新事情。", "target_word": "科学研究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参加过一项海洋科学研究。", "target_word": "科学研究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们也可以参加科学研究。", "target_word": "科学研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学研究需要大家一起努力。", "target_word": "科学研究", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项科学研究", "label": "量词"}], "register": "书面语", "sense_fingerprint": "通过观察、思考和实验来学习新知识的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa05ba3-543a-4f57-9e53-db31b3068c9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27160, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科学研究", "is_correct": true, "explanation": "正确：作主语，指通过实验学习新知识的活动，与句子定义相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不是通过实验学习新知识的活动。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是学习活动，无法“就是用实验学习新知识”。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语词，与这句书面定义的语体不合。"}], "explanations": {"科学研究": "正确：作主语，指通过实验学习新知识的活动，与句子定义相符。", "厨房": "语义：厨房是场所，不是通过实验学习新知识的活动。", "天气": "语义：天气不是学习活动，无法“就是用实验学习新知识”。", "玩意儿": "语域：“玩意儿”是口语词，与这句书面定义的语体不合。"}, "sentence_index": 0, "correct_answer": "科学研究"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名科学研究，负责修桥。", "explanation": "这里应该用〈工程师〉。科学研究指活动，不指人。"}, {"text": "这台科学研究很贵，我们买不起。", "explanation": "这里应该用〈仪器〉。科学研究指活动，不是设备，不能说“这台科学研究很贵”；这台设备应说仪器。"}, {"text": "这个科学研究很大，里面有很多设备。", "explanation": "这里应该用〈实验室〉。科学研究是活动，不是场所，不能说“很大”“里面有设备”；说地点要用实验室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科学研究", "is_correct": true, "explanation": "正确：作主语，指学习新知识的活动，能让人们知道新事情。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不能让人们知道新事情。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是物体，句中主语需要是能传递知识的事物。"}, {"text": "饺子", "is_correct": false, "explanation": "搭配：“让人们知道新事情”常搭配知识、发现，“饺子”不搭。"}], "explanations": {"科学研究": "正确：作主语，指学习新知识的活动，能让人们知道新事情。", "沙发": "语义：沙发是家具，不能让人们知道新事情。", "石头": "语义：石头是物体，句中主语需要是能传递知识的事物。", "饺子": "搭配：“让人们知道新事情”常搭配知识、发现，“饺子”不搭。"}, "sentence_index": 6, "correct_answer": "科学研究"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "科学研究每天给病人看病。", "explanation": "这里应该用〈医生〉。科学研究是活动，不能给病人看病；指人的要用医生。"}, {"text": "老师把科学研究放在了书包里。", "explanation": "这里应该用〈课本〉。科学研究是活动，不能放进书包；放进书包的是课本。"}, {"text": "孩子们喜欢吃科学研究。", "explanation": "这里应该用〈糖果〉。科学研究是活动，不能吃；孩子们吃的是糖果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上周我参加了一场科学研究。", "corrected_sentence": "上周我参加了一项科学研究。", "error_description": "量词错误：“场”用于比赛、演出等，抽象活动应用“项”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座科学研究很有意义，大家都很支持。", "corrected_sentence": "这项科学研究很有意义，大家都很支持。", "error_description": "量词错误：“座”用于建筑、山等大型固定物，科学研究是活动，应用“项”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
