INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27162, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家一起做决定。", "primary_collocate": null, "pronunciation": "qún tǐ jué cè", "ipa": "tɕʰyn˧˥ tʰi˨˩˦ tɕɥe˧˥ tsʰɤ˥˩", "syllable_count": 4, "sentences": [{"text": "全家旅行去哪儿，我们用群体决策。", "target_word": "群体决策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群体决策就是大家一起做决定。", "target_word": "群体决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们聚会时常常用群体决策。", "target_word": "群体决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "群体决策要先听每个人的想法。", "target_word": "群体决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢群体决策，因为大家都能说话。", "target_word": "群体决策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让同学们练习群体决策。", "target_word": "群体决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "群体决策有时要花很多时间。", "target_word": "群体决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小组里的群体决策让每个人都满意。", "target_word": "群体决策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次群体决策的结果是去爬山。", "target_word": "群体决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在游戏里学会了群体决策。", "target_word": "群体决策", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次群体决策", "label": "量词"}], "register": "书面语", "sense_fingerprint": "大家一起商量并做出决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa05ba3-543a-4f57-9e53-db31b3068c9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27162, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群体决策", "is_correct": true, "explanation": "正确：作宾语，指大家一起商量并做出决定的方式，符合“用”的语境。"}, {"text": "烤箱", "is_correct": false, "explanation": "语义：烤箱是厨具，不是决定去哪儿的方式。"}, {"text": "白糖", "is_correct": false, "explanation": "搭配：“用”的对象是方式或工具，“白糖”做菜用，不搭“决定去哪儿”。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不能作为决定去向的方式。"}], "explanations": {"群体决策": "正确：作宾语，指大家一起商量并做出决定的方式，符合“用”的语境。", "烤箱": "语义：烤箱是厨具，不是决定去哪儿的方式。", "白糖": "搭配：“用”的对象是方式或工具，“白糖”做菜用，不搭“决定去哪儿”。", "老虎": "语义：老虎是动物，不能作为决定去向的方式。"}, "sentence_index": 0, "correct_answer": "群体决策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是班里的群体决策，大家都听他的。", "explanation": "这里应该用〈领导〉。群体决策是做决定的方式，不指人。"}, {"text": "他把群体决策装进了行李箱。", "explanation": "这里应该用〈文件〉。群体决策是做决定的过程，不能装进行李箱；装进行李箱的是文件。"}, {"text": "孩子们喜欢吃群体决策。", "explanation": "这里应该用〈糖果〉。群体决策是做决定的过程，不能吃；孩子们吃的是糖果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群体决策", "is_correct": true, "explanation": "正确：作主语，指大家一起做决定的过程，常常要花时间。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是物体，不是需要花时间的过程。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，“要花很多时间”不能用来形容它。"}, {"text": "红色", "is_correct": false, "explanation": "语义：“红色”是颜色，不是需要花时间的过程，不能用“要花很多时间”来形容。"}], "explanations": {"群体决策": "正确：作主语，指大家一起做决定的过程，常常要花时间。", "石头": "语义：石头是物体，不是需要花时间的过程。", "太阳": "语义：太阳是天体，“要花很多时间”不能用来形容它。", "红色": "语义：“红色”是颜色，不是需要花时间的过程，不能用“要花很多时间”来形容。"}, "sentence_index": 6, "correct_answer": "群体决策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "群体决策做饭很快。", "explanation": "这里应该用〈厨师〉。群体决策是做决定的方式，不能做饭。"}, {"text": "小猫躺在群体决策上睡觉。", "explanation": "这里应该用〈沙发〉。群体决策是做决定的过程，不能躺；躺的是沙发、床等。"}, {"text": "妈妈把群体决策切成了小块。", "explanation": "这里应该用〈蛋糕〉。群体决策是做决定的过程，不能切成小块；切的是蛋糕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张群体决策让大家都满意。", "corrected_sentence": "这次群体决策让大家都满意。", "error_description": "量词错误：“张”用于纸、桌子等，群体决策是过程，应用“次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把群体决策让孩子们很开心。", "corrected_sentence": "这次群体决策让孩子们很开心。", "error_description": "量词错误：“把”用于有柄的东西，群体决策是过程，应用“次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
