INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27164, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把有用的东西拿过来用。", "primary_collocate": null, "pronunciation": "jí qǔ", "ipa": "tɕi˧˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "我想从他的做法里汲取有用的经验。", "target_word": "汲取", "complexity_tier": "T3", "furigana": "jí qǔ", "sentence_source": "generated"}, {"text": "学习别人的长处，就是汲取有用的东西。", "target_word": "汲取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从老师那里汲取了很多经验。", "target_word": "汲取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们应该汲取别人的好经验。", "target_word": "汲取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明从这件事中汲取了教训。", "target_word": "汲取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的想法，我们都可以汲取，为自己所用。", "target_word": "汲取", "complexity_tier": "T3", "furigana": "jí qǔ", "sentence_source": "generated"}, {"text": "她从古诗里汲取了写作的灵感。", "target_word": "汲取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司汲取了其他国家的先进经验。", "target_word": "汲取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以汲取朋友的优点，改正自己的缺点。", "target_word": "汲取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他汲取前人的经验，做得更好。", "target_word": "汲取", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "汲取了", "label": "体标"}, {"form": "汲取过", "label": "体标"}, {"form": "汲取着", "label": "体标"}], "register": "书面语", "sense_fingerprint": "把别人或别处有用的东西拿来为自己所用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa05ba3-543a-4f57-9e53-db31b3068c9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27164, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "汲取", "is_correct": true, "explanation": "jí qǔ，意思是把有用的东西拿来为自己所用。"}, {"text": "提取", "is_correct": false, "explanation": "tí 与 jí 声母不同（t 与 j），意思是取出、提炼，与“汲取”不同。"}, {"text": "截取", "is_correct": false, "explanation": "jié 与 jí 韵母不同（多一个 e），意思是截下一段。"}, {"text": "计取", "is_correct": false, "explanation": "jì 与 jí 声调不同（第四声与第二声），意思是按标准计算后收取。"}, {"text": "极区", "is_correct": false, "explanation": "jí qū 与 jí qǔ 的第二音节声调不同（qū 为第一声），意思是南北极附近的地区。"}], "explanations": {"汲取": "jí qǔ，意思是把有用的东西拿来为自己所用。", "提取": "tí 与 jí 声母不同（t 与 j），意思是取出、提炼，与“汲取”不同。", "截取": "jié 与 jí 韵母不同（多一个 e），意思是截下一段。", "计取": "jì 与 jí 声调不同（第四声与第二声），意思是按标准计算后收取。", "极区": "jí qū 与 jí qǔ 的第二音节声调不同（qū 为第一声），意思是南北极附近的地区。"}, "sentence_index": null, "correct_answer": "汲取"}, "level_3": {"options": [{"text": "倾倒", "is_correct": false, "explanation": "搭配：“倾倒”指把液体倒出，不能说从做法里倾倒经验。"}, {"text": "吞食", "is_correct": false, "explanation": "语义：“吞食”指咽下食物，与“有用的经验”不符。"}, {"text": "汲取", "is_correct": true, "explanation": "汲取：从他的做法里吸收有用的经验，与“有用的经验”搭配，句意通顺。"}, {"text": "排放", "is_correct": false, "explanation": "语义：“排放”指排出废物，与“有用的经验”的意思相反。"}], "explanations": {"倾倒": "搭配：“倾倒”指把液体倒出，不能说从做法里倾倒经验。", "吞食": "语义：“吞食”指咽下食物，与“有用的经验”不符。", "汲取": "汲取：从他的做法里吸收有用的经验，与“有用的经验”搭配，句意通顺。", "排放": "语义：“排放”指排出废物，与“有用的经验”的意思相反。"}, "sentence_index": 0, "correct_answer": "汲取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个节目汲取了很多年轻观众。", "explanation": "这里应该用〈吸引〉。汲取 的对象是有益的知识、经验等，观众要用“吸引”，不能被“汲取”。"}, {"text": "他凭实力汲取了大家的尊重。", "explanation": "这里应该用〈赢得〉。尊重是别人给予的，要用“赢得”；汲取 只用于吸收有益的内容。"}, {"text": "他通过收购汲取了一家工厂。", "explanation": "这里应该用〈获取〉。汲取 不能用于整个企业或工厂，获得企业要用“获取”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于树木、头发等，不能用于灵感。"}, {"text": "汲取", "is_correct": true, "explanation": "汲取：从古诗中吸收有益的素材，与“灵感”搭配，句意通顺。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”针对具体物件，不能说搬运灵感。"}, {"text": "吞食", "is_correct": false, "explanation": "语义：“吞食”指咽下食物，与灵感无关。"}], "explanations": {"修剪": "搭配：“修剪”用于树木、头发等，不能用于灵感。", "汲取": "汲取：从古诗中吸收有益的素材，与“灵感”搭配，句意通顺。", "搬运": "搭配：“搬运”针对具体物件，不能说搬运灵感。", "吞食": "语义：“吞食”指咽下食物，与灵感无关。"}, "sentence_index": 6, "correct_answer": "汲取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在会议上汲取了大家的掌声。", "explanation": "这里应该用〈博得〉。汲取 指把有用的东西拿来利用，掌声是别人给予的，要用“博得”。"}, {"text": "这家店汲取了一大批老客户。", "explanation": "这里应该用〈招揽〉。汲取 指拿有用的东西来用，招揽顾客要用“招揽”，不能说“汲取”。"}, {"text": "他向父亲汲取了一笔钱去买车。", "explanation": "这里应该用〈借〉。汲取 指拿有用的东西来用，向别人借钱要用“借”，不能说“汲取”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在汲取了别人的好经验。", "corrected_sentence": "他正在汲取别人的好经验。", "error_description": "“汲取”后的“了”与“正在”矛盾：“正在”表示动作进行中，不能与表示完成的“了”同用。应去掉“了”，说“正在汲取别人的好经验”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她汲取了着写作的灵感。", "corrected_sentence": "她汲取着写作的灵感。", "error_description": "“汲取”后的“了”与“着”同用错误：“着”表示持续，不与“了”连用。应去掉“了”，说“汲取着写作的灵感”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
