INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27178, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房屋、桥梁等建筑物中撑住重量的柱子。", "primary_collocate": null, "pronunciation": "zhī zhù", "ipa": "ʈʂɨ˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这座桥有四根粗大的支柱。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的支柱断了，屋顶掉了下来。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在检查大厅里的支柱，看有没有裂缝。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，帐篷的支柱就弯了。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一根木头做帐篷的支柱。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请扶住这根支柱，不要让它倒下。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的支柱是木头做的，已经很旧了。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下室里有几根水泥支柱，撑着上面的楼。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把新的支柱放在桥下面。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震时，房子的支柱倒了，楼也塌了。", "target_word": "支柱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "精神支柱", "label": "复合"}, {"form": "支柱产业", "label": "复合"}], "register": "中性", "sense_fingerprint": "实物义：房屋、桥梁、帐篷等建筑物上撑住重量的柱子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa05ba3-543a-4f57-9e53-db31b3068c9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27178, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "支柱", "is_correct": true, "explanation": "正确答案：支柱（zhī zhù），指房屋、桥梁等建筑中撑住重量的柱子。"}, {"text": "止住", "is_correct": false, "explanation": "止（zhǐ，第三声）与支（zhī，第一声）声调不同，「止住」意思是停下来、制止。"}, {"text": "植株", "is_correct": false, "explanation": "植株（zhí zhū）与支柱两个音节声调都不同：zhí 为第二声，zhū 为第一声，意思是植物的整个株体。"}, {"text": "支出", "is_correct": false, "explanation": "出（chū）与柱（zhù）声母不同（ch 与 zh），声调也不同，意思是开支、花费。"}, {"text": "持住", "is_correct": false, "explanation": "持（chí）与支（zhī）声母不同（ch 与 zh），声调也不同，意思是握稳、坚持住。"}], "explanations": {"支柱": "正确答案：支柱（zhī zhù），指房屋、桥梁等建筑中撑住重量的柱子。", "止住": "止（zhǐ，第三声）与支（zhī，第一声）声调不同，「止住」意思是停下来、制止。", "植株": "植株（zhí zhū）与支柱两个音节声调都不同：zhí 为第二声，zhū 为第一声，意思是植物的整个株体。", "支出": "出（chū）与柱（zhù）声母不同（ch 与 zh），声调也不同，意思是开支、花费。", "持住": "持（chí）与支（zhī）声母不同（ch 与 zh），声调也不同，意思是握稳、坚持住。"}, "sentence_index": null, "correct_answer": "支柱"}, "level_3": {"options": [{"text": "支柱", "is_correct": true, "explanation": "正确答案：「这座桥有四根粗大的支柱」指桥下撑住桥身的柱子，与「四根粗大的」搭配。"}, {"text": "花瓣", "is_correct": false, "explanation": "搭配：「粗大」不形容花瓣，花瓣也不用「根」来计量，与「四根粗大的」不搭。"}, {"text": "树枝", "is_correct": false, "explanation": "语义：桥上不会长出树枝，句中说的是桥的构件，树枝与桥的结构不相关。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：「钥匙」用「把」计量，不说「粗大的钥匙」，与「四根」也不搭配。"}], "explanations": {"支柱": "正确答案：「这座桥有四根粗大的支柱」指桥下撑住桥身的柱子，与「四根粗大的」搭配。", "花瓣": "搭配：「粗大」不形容花瓣，花瓣也不用「根」来计量，与「四根粗大的」不搭。", "树枝": "语义：桥上不会长出树枝，句中说的是桥的构件，树枝与桥的结构不相关。", "钥匙": "搭配：「钥匙」用「把」计量，不说「粗大的钥匙」，与「四根」也不搭配。"}, "sentence_index": 0, "correct_answer": "支柱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人把这块布当支柱，挂在屋顶下撑住房梁。", "explanation": "这里应该用〈木头〉。布撑不住重物，把布当作支柱是误用；支柱应是坚硬的木头或金属。"}, {"text": "这张桌子的支柱很平，上面可以放书。", "explanation": "这里应该用〈桌面〉。支柱是竖着撑住东西的，不是平的台面，不能说支柱很平。"}, {"text": "这块玻璃是窗户的支柱，阳光才能照进来。", "explanation": "这里应该用〈窗框〉。玻璃透光却承不了重，支柱要承重，撑住窗户的是窗框。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27178, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "支柱", "is_correct": true, "explanation": "正确答案：支柱（zhī zhù），指房屋、桥梁等建筑中撑住重量的柱子。"}, {"text": "蜘蛛", "is_correct": false, "explanation": "蜘蛛（zhī zhū）与支柱只有第二个音节不同：zhū 为第一声，zhù 为第四声，意思是蜘蛛。"}, {"text": "资助", "is_correct": false, "explanation": "zī 与 zhī 声母不同（z 与 zh），声调相同，意思是资助、援助。"}, {"text": "制住", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，意思是控制住、压制住。"}, {"text": "吃住", "is_correct": false, "explanation": "chī 与 zhī 声母不同（ch 与 zh），声调相同，意思是吃和住。"}], "explanations": {"支柱": "正确答案：支柱（zhī zhù），指房屋、桥梁等建筑中撑住重量的柱子。", "蜘蛛": "蜘蛛（zhī zhū）与支柱只有第二个音节不同：zhū 为第一声，zhù 为第四声，意思是蜘蛛。", "资助": "zī 与 zhī 声母不同（z 与 zh），声调相同，意思是资助、援助。", "制住": "zhì（第四声）与 zhī（第一声）声调不同，意思是控制住、压制住。", "吃住": "chī 与 zhī 声母不同（ch 与 zh），声调相同，意思是吃和住。"}, "sentence_index": null, "correct_answer": "支柱"}, "level_3": {"options": [{"text": "支柱", "is_correct": true, "explanation": "正确答案：「老房子的支柱是木头做的」指老房子里承重的木柱，与「木头做的」相合。"}, {"text": "发动机", "is_correct": false, "explanation": "语义：房子里没有发动机，句中说的是房屋的承重结构，「发动机」与此无关。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：「是木头做的」不能用来说玻璃，玻璃一般不是木头做的。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾是穿戴的物品，不属于老房子的结构，句中说的是承重的柱子。"}], "explanations": {"支柱": "正确答案：「老房子的支柱是木头做的」指老房子里承重的木柱，与「木头做的」相合。", "发动机": "语义：房子里没有发动机，句中说的是房屋的承重结构，「发动机」与此无关。", "玻璃": "搭配：「是木头做的」不能用来说玻璃，玻璃一般不是木头做的。", "围巾": "语义：围巾是穿戴的物品，不属于老房子的结构，句中说的是承重的柱子。"}, "sentence_index": 6, "correct_answer": "支柱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这股烟是房子的支柱，能撑住屋顶。", "explanation": "这里应该用〈木头〉。烟没有承重能力，不能当支柱。"}, {"text": "这条河是桥的支柱，把桥撑在水上。", "explanation": "这里应该用〈桥墩〉。河流不能撑住桥身，支撑桥梁的是桥墩。"}, {"text": "这片云是房子的支柱，能挡住风雨。", "explanation": "这里应该用〈屋顶〉。云不能承重，支柱要撑住屋顶这类结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座桥下有三只支柱。", "corrected_sentence": "这座桥下有三根支柱。", "error_description": "量词错误：支柱应该用量词「根」计量，说「三根支柱」。「只」多用于动物和成对的东西，不能用于支柱。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把那块旧支柱换掉了。", "corrected_sentence": "工人把那根旧支柱换掉了。", "error_description": "量词错误：支柱应该用量词「根」计量，说「那根旧支柱」。「块」用于块状的东西，不能用于支柱。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27180, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27180, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27180, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "肉眼看不见的。", "primary_collocate": null, "pronunciation": "yǐn xíng", "ipa": "in˨˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这种墨水写的字是隐形的，要用光才看得见。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的魔法师有一件隐形的衣服。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子说他有一个隐形的朋友，我们都看不见他。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃擦得太干净，好像是隐形的。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的小精灵一挥手，就变成隐形的了，大家都看不见她。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿上隐形的斗篷，别人就看不见他了。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑猫在夜里几乎是隐形的，我们很难看见它。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上有一道隐形的门，只有他知道在哪里。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸上有隐形的字，我什么也看不见。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他想变得隐形，这样就没人能看见他。", "target_word": "隐形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隱形", "label": "繁体"}, {"form": "隐形人", "label": "复合"}, {"form": "隐形眼镜", "label": "复合"}], "register": "中性", "sense_fingerprint": "字面上眼睛看不见的，如隐形的墨水、隐形的斗篷", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa05ba3-543a-4f57-9e53-db31b3068c9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清晰", "is_correct": false, "explanation": "语义：“清晰”指看得很分明，与“要用光才看得见”矛盾。"}, {"text": "鲜艳", "is_correct": false, "explanation": "体貌：“鲜艳”描写颜色明亮，与字迹要用光才看见的情况相反。"}, {"text": "隐形", "is_correct": true, "explanation": "隐形：指眼睛看不见，与“要用光才看得见”相合。"}, {"text": "醒目", "is_correct": false, "explanation": "语义：“醒目”指引人注意，与字迹难以看见矛盾。"}], "explanations": {"清晰": "语义：“清晰”指看得很分明，与“要用光才看得见”矛盾。", "鲜艳": "体貌：“鲜艳”描写颜色明亮，与字迹要用光才看见的情况相反。", "隐形": "隐形：指眼睛看不见，与“要用光才看得见”相合。", "醒目": "语义：“醒目”指引人注意，与字迹难以看见矛盾。"}, "sentence_index": 0, "correct_answer": "隐形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏灯的光很隐形，房间里一下子亮堂了。", "explanation": "这里应该用〈明亮〉。隐形 指看不见，与“房间一下子亮堂了”矛盾；灯光充足要用“明亮”。"}, {"text": "这辆车的颜色很隐形，远处一眼就能认出来。", "explanation": "这里应该用〈鲜艳〉。隐形 指看不见，与“远处一眼就能认出来”矛盾；颜色鲜亮要用“鲜艳”。"}, {"text": "这块布料的花纹很隐形，穿在身上特别显眼。", "explanation": "这里应该用〈鲜明〉。隐形 指看不见，与“特别显眼”矛盾；花纹对比强烈要用“鲜明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "显眼", "is_correct": false, "explanation": "语义：“显眼”指容易被看见，与“我们很难看见它”矛盾。"}, {"text": "隐形", "is_correct": true, "explanation": "隐形：指眼睛看不见，与“几乎……很难看见”相合。"}, {"text": "闪亮", "is_correct": false, "explanation": "语义：“闪亮”指光线明亮，与夜里几乎看不见的情境矛盾。"}, {"text": "庞大", "is_correct": false, "explanation": "语义：“庞大”指体积很大、容易看见，与“很难看见它”相矛盾。"}], "explanations": {"显眼": "语义：“显眼”指容易被看见，与“我们很难看见它”矛盾。", "隐形": "隐形：指眼睛看不见，与“几乎……很难看见”相合。", "闪亮": "语义：“闪亮”指光线明亮，与夜里几乎看不见的情境矛盾。", "庞大": "语义：“庞大”指体积很大、容易看见，与“很难看见它”相矛盾。"}, "sentence_index": 6, "correct_answer": "隐形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋高楼很隐形，站在几公里外就能望见。", "explanation": "这里应该用〈高耸〉。隐形 指看不见，与“几公里外就能望见”矛盾；建筑高大要用“高耸”。"}, {"text": "黑板上的字很隐形，全班都能看见。", "explanation": "这里应该用〈清晰〉。隐形 指看不见，与“全班都能看见”矛盾；字迹清楚要说“清晰”。"}, {"text": "那个红色标志很隐形，远处也能看到。", "explanation": "这里应该用〈醒目〉。隐形 指看不见，与“远处也能看到”矛盾；引人注意要用“醒目”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件斗篷是隐形地，谁也看不见他。", "corrected_sentence": "这件斗篷是隐形的，谁也看不见他。", "error_description": "“隐形”作谓语（“是”之后）要用“的”，不能用“地”。应说“是隐形的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙上有一道隐形地门，外人根本找不到。", "corrected_sentence": "墙上有一道隐形的门，外人根本找不到。", "error_description": "定语错误：“隐形”修饰名词“门”时用“的”，不能用“地”。应说“隐形的门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65e82641-eeb5-477e-b7d6-45981e2e407d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
