INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27184, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做研究，发现新知识。", "primary_collocate": null, "pronunciation": "kē yán", "ipa": "kʰɤ˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "她喜欢科研，每天都在实验室里。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科研的目的是发现新知识。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想做科研。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科研路上会遇到很多失败。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人愿意去做科研，国家就有希望。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搞科研要有好奇心。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把全部精力投入到科研中，从不觉得辛苦。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科研让他发现了一种新药。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业后留在学校搞科研。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做科研的人要多读书。", "target_word": "科研", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "科研人员", "label": "复合词"}, {"form": "科研工作", "label": "复合词"}, {"form": "科研成果", "label": "复合词"}], "register": "中性", "sense_fingerprint": "科研：做研究发现新知识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c983003c-8af0-4fb2-b466-92c6a7d210cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科研", "is_correct": true, "explanation": "科研：她喜欢做研究，正合“每天都在实验室里”的语境。"}, {"text": "逛街", "is_correct": false, "explanation": "语义：“逛街”与“每天都在实验室里”的场所相矛盾，句子说的是研究工作。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“每天都在实验室里”的活动不符，句子说的是研究工作。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“喜欢”一般不以“身高”这类身体指标作宾语。"}], "explanations": {"科研": "科研：她喜欢做研究，正合“每天都在实验室里”的语境。", "逛街": "语义：“逛街”与“每天都在实验室里”的场所相矛盾，句子说的是研究工作。", "睡觉": "语义：“睡觉”与“每天都在实验室里”的活动不符，句子说的是研究工作。", "身高": "搭配：“喜欢”一般不以“身高”这类身体指标作宾语。"}, "sentence_index": 0, "correct_answer": "科研"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去工厂做了一幅科研。", "explanation": "这里应该用〈项〉。“幅”用于画作，科研是活动，应说“一项科研”。"}, {"text": "他有一双很好的科研。", "explanation": "这里应该用〈项〉。“双”用于成对的东西，科研是活动，应说“一项科研”。"}, {"text": "科学家发现了一辆科研。", "explanation": "这里应该用〈项〉。“辆”用于车辆，科研是活动，应说“一项科研”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科研", "is_correct": true, "explanation": "科研：“投入到……中”指把精力放在研究工作上，正合语境。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“投入到……中”接事业或活动，“空气”不能作为“投入”的对象，句意不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”是动作的结果，不是可以投入精力的对象，句意不通。"}, {"text": "眉毛", "is_correct": false, "explanation": "体貌：“眉毛”属于外貌特征，不能作为“投入”的对象。"}], "explanations": {"科研": "科研：“投入到……中”指把精力放在研究工作上，正合语境。", "空气": "搭配：“投入到……中”接事业或活动，“空气”不能作为“投入”的对象，句意不通。", "脚步": "语义：“脚步”是动作的结果，不是可以投入精力的对象，句意不通。", "眉毛": "体貌：“眉毛”属于外貌特征，不能作为“投入”的对象。"}, "sentence_index": 6, "correct_answer": "科研"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爱迪生做了一颗科研。", "explanation": "这里应该用〈项〉。“颗”用于颗粒状的小东西，科研是活动，应说“一项科研”。"}, {"text": "这是一台很好的科研。", "explanation": "这里应该用〈项〉。“台”用于机器，科研是活动，应说“一项科研”。"}, {"text": "我们在会上做了一根科研。", "explanation": "这里应该用〈项〉。“根”用于条状物，科研是活动，应说“一项科研”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些很科研人员很努力。", "corrected_sentence": "这些科研人员很努力。", "error_description": "错误：“很”不能插在“科研人员”的“科研”前修饰名词性成分。正确：“这些科研人员”，“科研”直接修饰“人员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只科研很有意义。", "corrected_sentence": "这项科研很有意义。", "error_description": "错误：“科研”作名词计量时应用“项”，“只”用于动物等，不能用于科研这类活动。正确：“这项科研”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2dca4975-deba-4c65-8812-2243cb648a20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
